const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:32,920",arabic:"وَلَكِنَّهُ عَلَامَةُ الْكُفْرِ.",segs:null,full_uz:"Lekin u kufrning belgisidir.",note:"عَلَامَةُ الْكُفْرِ — izofa birikmasi: kufrning belgisi."},
{num:2,time:"00:00:35,399 --> 00:00:38,120",arabic:"فَهَذِهِ الْأُخْرَى صَحِيحَةٌ.",segs:null,full_uz:"Bu ikkinchisi ham to‘g‘ri.",note:"الْأُخْرَى — boshqa biri, ikkinchisi; muannas shakl."},
{num:3,time:"00:00:38,120 --> 00:00:40,579",arabic:"فَإِنَّ عَدَمَ الدِّقَّةِ فِي ذَلِكَ،",segs:[{ar:"فَإِنَّ عَدَمَ الدِّقَّةِ",uz:"Chunki aniqlik yetishmasligi"},{ar:"فِي ذَلِكَ،",uz:"bu masalada,"}],full_uz:"Chunki bu masalada aniqlik yetishmasligi...",note:"عَدَمُ الدِّقَّةِ — aniqlikning yo‘qligi. Parchada fikr tugallanmagan."},
{num:4,time:"00:00:40,579 --> 00:00:47,140",arabic:"أَلَا تَسْمَعُ دَلِيلِي وَتَفْسِيرِي أَوَّلًا يَا ابْنَ إِدْرِيسَ؟",segs:[{ar:"أَلَا تَسْمَعُ دَلِيلِي وَتَفْسِيرِي",uz:"Dalilim va izohimni eshitmaysizmi"},{ar:"أَوَّلًا",uz:"avval"},{ar:"يَا ابْنَ إِدْرِيسَ؟",uz:"Ibn Idris?"}],full_uz:"Avval dalilim va izohimni eshitmaysizmi, Ibn Idris?",note:"أَلَا تَسْمَعُ؟ — eshitmaysizmi?; taklif yoki undash ma’nosida ham keladi."},
{num:5,time:"00:00:47,140 --> 00:00:50,219",arabic:"النُّصُوصُ الْقَاطِعَةُ آكَدُ الْأَدِلَّةِ وَأَبْيَنُهَا.",segs:[{ar:"النُّصُوصُ الْقَاطِعَةُ",uz:"Qat’iy matnlar"},{ar:"آكَدُ الْأَدِلَّةِ وَأَبْيَنُهَا.",uz:"dalillarning eng ishonchlisi va eng ravshanidir."}],full_uz:"Qat’iy matnlar dalillarning eng ishonchlisi va eng ravshanidir.",note:"آكَدُ — ishonchliroq, qat’iyroq; أَبْيَنُ — ravshanroq."},
{num:6,time:"00:00:50,219 --> 00:00:54,920",arabic:"وَقَبْلَ أَنْ أَسْمَعَ دَلِيلَكَ أَخْبِرْنِي عَمَّا تَدْعُو إِلَيْهِ.",segs:[{ar:"وَقَبْلَ أَنْ أَسْمَعَ دَلِيلَكَ",uz:"Dalilingizni eshitishimdan oldin"},{ar:"أَخْبِرْنِي",uz:"menga ayting"},{ar:"عَمَّا تَدْعُو إِلَيْهِ.",uz:"nimaga da’vat qilayotganingizni."}],full_uz:"Dalilingizni eshitishimdan oldin nimaga da’vat qilayotganingizni menga ayting.",note:"عَمَّا — عَنْ va مَا birikmasi. دَعَا إِلَى — ...ga da’vat qilmoq."},
{num:7,time:"00:00:54,920 --> 00:01:00,520",arabic:"أَكِتَابٌ نَاطِقٌ أَمْ فَرْضٌ مُفْتَرَضٌ أَمْ سُنَّةٌ قَائِمَةٌ؟",segs:[{ar:"أَكِتَابٌ نَاطِقٌ",uz:"Ochiq bayon qiluvchi Kitobmi"},{ar:"أَمْ فَرْضٌ مُفْتَرَضٌ",uz:"yoki belgilangan farzmi"},{ar:"أَمْ سُنَّةٌ قَائِمَةٌ؟",uz:"yoki sobit sunnatmi?"}],full_uz:"Bu ochiq bayon qiluvchi Kitobmi, belgilangan farzmi yoki sobit sunnatmi?",note:"أَ ... أَمْ ... — muqobil narsalar orasidan so‘rash: ...mi yoki ...mi?"},
{num:8,time:"00:01:00,520 --> 00:01:03,740",arabic:"وَوَجَدْتَ مِنَ السَّلَفِ الْبَحْثَ فِيهِ وَالسُّؤَالَ؟",segs:[{ar:"وَوَجَدْتَ مِنَ السَّلَفِ",uz:"Salaflardan topdingizmi"},{ar:"الْبَحْثَ فِيهِ وَالسُّؤَالَ؟",uz:"bu haqda izlanish va savol berishni?"}],full_uz:"Salaflarning bu haqda izlanib, savol berganini topdingizmi?",note:"السَّلَفُ — ilgari o‘tgan avlodlar; bu yerda dastlabki musulmon avlodlari."},
{num:9,time:"00:01:04,840 --> 00:01:13,099",arabic:"فَكَيْفَ إِذَنْ تُبْدِي حُجَجًا لَا أَصْلَ لَهَا فِي كِتَابِ اللَّهِ وَلَا فِي سُنَّةِ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",segs:[{ar:"فَكَيْفَ إِذَنْ تُبْدِي حُجَجًا",uz:"Unda qanday qilib dalillar keltirasiz"},{ar:"لَا أَصْلَ لَهَا",uz:"ularning asosi bo‘lmasa"},{ar:"فِي كِتَابِ اللَّهِ",uz:"Allohning Kitobida"},{ar:"وَلَا فِي سُنَّةِ نَبِيِّهِ",uz:"va Uning payg‘ambari sunnatida ham"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",uz:"Alloh u zotga salavot va salom yo‘llasin?"}],full_uz:"Unda Allohning Kitobida ham, payg‘ambari sollallohu alayhi vasallamning sunnatida ham asosi bo‘lmagan dalillarni qanday keltirasiz?",note:"أَبْدَى — namoyon qilmoq, bildirmoq. حُجَجٌ — حُجَّةٌ so‘zining ko‘pligi: dalillar."},
{num:10,time:"00:01:13,099 --> 00:01:15,219",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:null,full_uz:"Alloh u zotga salavot va salom yo‘llasin.",note:"Payg‘ambar zikr qilinganida aytiladigan duo."},
{num:11,time:"00:01:15,219 --> 00:01:18,900",arabic:"وَلَمْ نَسْمَعْ أَنَّ أَحَدًا مِنَ الصَّحَابَةِ أَوْ مِنَ السَّلَفِ الْأَخْيَارِ،",segs:[{ar:"وَلَمْ نَسْمَعْ أَنَّ أَحَدًا",uz:"Hech kimning qilganini eshitmadik"},{ar:"مِنَ الصَّحَابَةِ",uz:"sahobalardan"},{ar:"أَوْ مِنَ السَّلَفِ الْأَخْيَارِ،",uz:"yoki yaxshi salaflardan,"}],full_uz:"Sahobalardan yoki yaxshi salaflardan biror kishining",note:"الْأَخْيَارُ — yaxshi, fazilatli kishilar. Gapning mazmuni keyingi parchada tugallanadi."},
{num:12,time:"00:01:18,900 --> 00:01:22,280",arabic:"قَدْ خَاضَ فِي هَذِهِ الْمَسَائِلِ أَوْ قَبِلَهَا.",segs:[{ar:"قَدْ خَاضَ فِي هَذِهِ الْمَسَائِلِ",uz:"bu masalalarga kirishganini"},{ar:"أَوْ قَبِلَهَا.",uz:"yoki ularni qabul qilganini."}],full_uz:"Bu masalalarga kirishganini yoki ularni qabul qilganini eshitmadik.",note:"خَاضَ فِي — biror mavzuga chuqur kirishmoq, uni muhokama qilmoq."},
{num:13,time:"00:01:22,280 --> 00:01:24,099",arabic:"أَأُخَالِفُ مَا أَعْتَقِدُهُ؟",segs:[{ar:"أَأُخَالِفُ",uz:"Qarshi chiqaymi"},{ar:"مَا أَعْتَقِدُهُ؟",uz:"o‘zim ishongan narsaga?"}],full_uz:"O‘zim ishongan narsaga qarshi chiqaymi?",note:"Birinchi أَ — so‘roq yuklamasi; ikkinchisi أُخَالِفُ fe’lining bir qismi."},
{num:14,time:"00:01:24,099 --> 00:01:31,899",arabic:"أَيْنَ أَنْتَ يَا بِشْرُ عَنِ الْكَلَامِ فِي الْفِقْهِ وَالْأَخْبَارِ؟",segs:[{ar:"أَيْنَ أَنْتَ يَا بِشْرُ",uz:"Nega siz, Bishr"},{ar:"عَنِ الْكَلَامِ فِي الْفِقْهِ وَالْأَخْبَارِ؟",uz:"fiqh va rivoyatlar haqida gapirishdan uzoqsiz?"}],full_uz:"Bishr, nega fiqh va rivoyatlar haqida gapirish bilan shug‘ullanmaysiz?",note:"أَيْنَ أَنْتَ عَنْ...؟ — nega ...bilan shug‘ullanmaysiz? mazmunida undash uchun ishlatiladi."},
{num:15,time:"00:01:31,899 --> 00:01:35,239",arabic:"فَتَكْسِبَ رِضَا اللَّهِ وَرِضَا النَّاسِ،",segs:[{ar:"فَتَكْسِبَ رِضَا اللَّهِ",uz:"Shunda Allohning roziligini qozonasiz"},{ar:"وَرِضَا النَّاسِ،",uz:"odamlarning roziligini ham,"}],full_uz:"Shunda Allohning ham, odamlarning ham roziligini qozonasiz,",note:"كَسَبَ رِضَا فُلَانٍ — birovning roziligini qozonmoq."},
{num:16,time:"00:01:35,239 --> 00:01:37,039",arabic:"وَتَتْرُكَ هَذَا.",segs:null,full_uz:"Buni esa tark etasiz.",note:null},
{num:17,time:"00:01:37,039 --> 00:01:39,079",arabic:"هَلِ اطَّلَعْتَ عَلَى عِلْمِ الْكَلَامِ؟",segs:[{ar:"هَلِ اطَّلَعْتَ",uz:"Tanishganmisiz"},{ar:"عَلَى عِلْمِ الْكَلَامِ؟",uz:"kalom ilmi bilan?"}],full_uz:"Kalom ilmi bilan tanishganmisiz?",note:"اطَّلَعَ عَلَى — biror narsa bilan tanishmoq, undan xabardor bo‘lmoq."},
{num:18,time:"00:01:40,899 --> 00:01:44,259",arabic:"اطَّلَعْتُ مِنْ أَهْلِ الْكَلَامِ عَلَى شَيْءٍ،",segs:[{ar:"اطَّلَعْتُ مِنْ أَهْلِ الْكَلَامِ",uz:"Kalom ahlidan xabardor bo‘ldim"},{ar:"عَلَى شَيْءٍ،",uz:"bir narsadan,"}],full_uz:"Kalom ahlidan shunday bir narsani bildimki,",note:"أَهْلُ الْكَلَامِ — kalom ilmi bilan shug‘ullanuvchilar."},
{num:19,time:"00:01:45,259 --> 00:01:48,560",arabic:"مَا ظَنَنْتُ مُسْلِمًا عَاقِلًا يَقُولُهُ.",segs:[{ar:"مَا ظَنَنْتُ",uz:"O‘ylamagan edim"},{ar:"مُسْلِمًا عَاقِلًا يَقُولُهُ.",uz:"aqlli musulmon buni aytadi deb."}],full_uz:"Aqlli musulmon buni aytadi deb o‘ylamagan edim.",note:"مَا ظَنَنْتُ — o‘ylamagan edim; مَا o‘tgan zamonni inkor qilmoqda."},
{num:20,time:"00:01:48,560 --> 00:01:55,379",arabic:"لَأَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ الْعَبْدُ بِكُلِّ ذَنْبٍ مَا خَلَا الشِّرْكَ،",segs:[{ar:"لَأَنْ يَلْقَى اللَّهَ عَزَّ وَجَلَّ الْعَبْدُ",uz:"Bandaning qudratli va ulug‘ Allohga yuzlanishi"},{ar:"بِكُلِّ ذَنْبٍ",uz:"har qanday gunoh bilan"},{ar:"مَا خَلَا الشِّرْكَ،",uz:"shirkdan tashqari,"}],full_uz:"Bandaning qudratli va ulug‘ Allohga shirkdan tashqari har qanday gunoh bilan yuzlanishi",note:"مَا خَلَا — ...dan tashqari; istisno bildiradi. الْعَبْدُ fe’lning egasi, اللَّهَ esa to‘ldiruvchisi."},
{num:21,time:"00:01:55,379 --> 00:01:59,200",arabic:"خَيْرٌ مِنْ أَنْ يَلْقَاهُ بِشَيْءٍ مِنَ الْكَلَامِ.",segs:[{ar:"خَيْرٌ مِنْ أَنْ يَلْقَاهُ",uz:"Unga yuzlanishidan yaxshiroq"},{ar:"بِشَيْءٍ مِنَ الْكَلَامِ.",uz:"kalomdan biror narsa bilan."}],full_uz:"Unga kalomdan biror narsa bilan yuzlanishidan yaxshiroq.",note:"خَيْرٌ مِنْ — ...dan yaxshiroq. Bu parcha oldingi gapning kesimi."},
{num:22,time:"00:01:59,200 --> 00:02:02,879",arabic:"أَمَّا أَنَا فَلِي نَهْمَةٌ فِي عِلْمِ الْكَلَامِ.",segs:[{ar:"أَمَّا أَنَا",uz:"Menga kelsak"},{ar:"فَلِي نَهْمَةٌ",uz:"menda kuchli ishtiyoq bor"},{ar:"فِي عِلْمِ الْكَلَامِ.",uz:"kalom ilmiga."}],full_uz:"Menga kelsak, kalom ilmiga kuchli ishtiyoqim bor.",note:"نَهْمَةٌ — kuchli, to‘ymaydigan ishtiyoq. أَمَّا ... فَـ — ...ga kelsak, ..."},
{num:23,time:"00:02:02,879 --> 00:02:06,920",arabic:"أَتَظُنُّ رَدَّكَ هَذَا مُقْنِعًا؟",segs:[{ar:"أَتَظُنُّ رَدَّكَ هَذَا",uz:"Bu javobingizni deb o‘ylaysizmi"},{ar:"مُقْنِعًا؟",uz:"ishontiradigan?"}],full_uz:"Bu javobingizni ishontiradigan deb o‘ylaysizmi?",note:"رَدٌّ — javob. مُقْنِعٌ — ishontiradigan, qanoatlantiradigan."},
{num:24,time:"00:02:06,920 --> 00:02:11,199",arabic:"أَقُولُ لَكَ: قَالَ اللَّهُ تَعَالَى وَقَالَ الرَّسُولُ،",segs:[{ar:"أَقُولُ لَكَ:",uz:"Sizga aytyapman:"},{ar:"قَالَ اللَّهُ تَعَالَى",uz:"Alloh taolo dedi"},{ar:"وَقَالَ الرَّسُولُ،",uz:"Rasul dedi,"}],full_uz:"Men sizga Alloh taolo dedi, Rasul dedi deb aytyapman,",note:null},
{num:25,time:"00:02:11,199 --> 00:02:13,860",arabic:"وَتَقُولُ: لِي نَهْمَةٌ فِي عِلْمِ الْكَلَامِ!",segs:[{ar:"وَتَقُولُ:",uz:"Siz esa deysiz:"},{ar:"لِي نَهْمَةٌ فِي عِلْمِ الْكَلَامِ!",uz:"kalom ilmiga kuchli ishtiyoqim bor!"}],full_uz:"Siz esa kalom ilmiga kuchli ishtiyoqim bor deysiz!",note:null},
{num:26,time:"00:02:13,860 --> 00:02:16,580",arabic:"أَأُنْزِلَ الذِّكْرُ عَلَيْكَ مِنْ بَيْنِنَا؟",segs:[{ar:"أَأُنْزِلَ الذِّكْرُ عَلَيْكَ",uz:"Zikr sizga nozil qilinganmi"},{ar:"مِنْ بَيْنِنَا؟",uz:"oramizdan?"}],full_uz:"Oramizdan aynan sizga Zikr nozil qilinganmi?",note:"أُنْزِلَ — nozil qilindi, majhul nisbat. الذِّكْرُ bu yerda vahiy ma’nosida."},
{num:27,time:"00:02:16,580 --> 00:02:22,020",arabic:"أَمْ عَلَى خَاتَمِ النَّبِيِّينَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",segs:[{ar:"أَمْ عَلَى خَاتَمِ النَّبِيِّينَ",uz:"Yoki payg‘ambarlarning so‘nggisiga"},{ar:"مُحَمَّدٍ",uz:"Muhammadga"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",uz:"Alloh u zotga salavot va salom yo‘llasin?"}],full_uz:"Yoki payg‘ambarlarning so‘nggisi Muhammad sollallohu alayhi vasallamga nozil qilinganmi?",note:"خَاتَمُ النَّبِيِّينَ — payg‘ambarlarning so‘nggisi."},
{num:28,time:"00:02:23,600 --> 00:02:30,920",arabic:"تَبْدُو لِي رَجُلًا عَاقِلًا أَيُّهَا الْمَرِيسِيُّ.",segs:[{ar:"تَبْدُو لِي رَجُلًا عَاقِلًا",uz:"Menga aqlli kishi bo‘lib ko‘rinyapsiz"},{ar:"أَيُّهَا الْمَرِيسِيُّ.",uz:"ey Marisiy."}],full_uz:"Menga aqlli kishi bo‘lib ko‘rinyapsiz, Marisiy.",note:"بَدَا لِي — menga ko‘rindi; hozirgi zamoni يَبْدُو."},
{num:29,time:"00:02:30,920 --> 00:02:36,580",arabic:"فَدَعْ عَنْكَ هَذِهِ الْبِدَعَ، وَاتَّبِعْ وَلَا تَبْتَدِعْ، وَارْجِعْ إِلَى الْحَقِّ.",segs:[{ar:"فَدَعْ عَنْكَ هَذِهِ الْبِدَعَ،",uz:"Bu bid’atlarni tashlang,"},{ar:"وَاتَّبِعْ وَلَا تَبْتَدِعْ،",uz:"ergashing, bid’at chiqarmang,"},{ar:"وَارْجِعْ إِلَى الْحَقِّ.",uz:"haqqa qayting."}],full_uz:"Bu bid’atlarni tashlang, ergashing, bid’at chiqarmang va haqqa qayting.",note:"اتَّبَعَ — ergashmoq; ابْتَدَعَ — yangilik kiritmoq, bu yerda bid’at chiqarmoq."},
{num:30,time:"00:02:36,580 --> 00:02:45,220",arabic:"فَمَا أَحَدٌ يَتْرُكُ كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّهِ لِقَوْلِ فُلَانٍ أَوْ فُلَانٍ مِنْ فَلَاسِفَةِ الْيُونَانِ.",segs:[{ar:"فَمَا أَحَدٌ يَتْرُكُ",uz:"Hech kim tark etmaydi"},{ar:"كِتَابَ اللَّهِ وَسُنَّةَ نَبِيِّهِ",uz:"Allohning Kitobi va payg‘ambarining sunnatini"},{ar:"لِقَوْلِ فُلَانٍ أَوْ فُلَانٍ",uz:"falonchi yoki pistonchining gapi uchun"},{ar:"مِنْ فَلَاسِفَةِ الْيُونَانِ.",uz:"yunon faylasuflaridan."}],full_uz:"Hech kim yunon faylasuflaridan falonchi yoki pistonchining gapi uchun Allohning Kitobi va payg‘ambarining sunnatini tark etmaydi.",note:"فُلَانٌ — ismi aytilmagan kishini bildiradi: falonchi. فَلَاسِفَةٌ — faylasuflar."},
{num:31,time:"00:02:45,219 --> 00:02:48,379",arabic:"خُذْ مِنِّي يَا بِشْرُ،",segs:[{ar:"خُذْ مِنِّي",uz:"Mendan qabul qiling"},{ar:"يَا بِشْرُ،",uz:"Bishr,"}],full_uz:"Mendan qabul qiling, Bishr:",note:"خُذْ مِنِّي — mendan ol; maslahat yoki hikmatni qabul qilishga undash uchun ham aytiladi."},
{num:32,time:"00:02:48,379 --> 00:02:52,939",arabic:"كُلُّ الْعُلُومِ سِوَى الْقُرْآنِ مَشْغَلَةٌ،",segs:[{ar:"كُلُّ الْعُلُومِ سِوَى الْقُرْآنِ",uz:"Qur’ondan boshqa barcha ilmlar"},{ar:"مَشْغَلَةٌ،",uz:"bir mashg‘ulotdir,"}],full_uz:"Qur’ondan boshqa barcha ilmlar bir mashg‘ulotdir,",note:"سِوَى — ...dan boshqa. مَشْغَلَةٌ — kishini band qiladigan narsa."},
{num:33,time:"00:02:52,939 --> 00:02:57,219",arabic:"إِلَّا الْحَدِيثَ وَعِلْمَ الْفِقْهِ فِي الدِّينِ.",segs:[{ar:"إِلَّا الْحَدِيثَ",uz:"hadis bundan mustasno"},{ar:"وَعِلْمَ الْفِقْهِ فِي الدِّينِ.",uz:"va dindagi fiqh ilmi ham."}],full_uz:"Hadis va dindagi fiqh ilmi bundan mustasno.",note:"إِلَّا oldingi umumiy hukmdan istisno qilmoqda."},
{num:34,time:"00:02:57,219 --> 00:03:01,800",arabic:"الْعِلْمُ مَا كَانَ فِيهِ قَالَ حَدَّثَنَا،",segs:[{ar:"الْعِلْمُ مَا كَانَ فِيهِ",uz:"Ilm shuki, unda bo‘ladi"},{ar:"قَالَ حَدَّثَنَا،",uz:"u dedi: bizga rivoyat qildi,"}],full_uz:"Ilm — unda «u dedi, bizga rivoyat qildi» deyiladigan narsadir,",note:"قَالَ حَدَّثَنَا rivoyatning kimdan olinganini ko‘rsatuvchi iboraga ishora qiladi."},
{num:35,time:"00:03:01,800 --> 00:03:06,280",arabic:"وَمَا سِوَى ذَاكَ وَسْوَاسُ الشَّيَاطِينِ.",segs:[{ar:"وَمَا سِوَى ذَاكَ",uz:"Undan boshqasi esa"},{ar:"وَسْوَاسُ الشَّيَاطِينِ.",uz:"shaytonlarning vasvasasidir."}],full_uz:"Undan boshqasi esa shaytonlarning vasvasasidir.",note:"وَسْوَاسٌ — vasvasa, ichdan keladigan chalg‘ituvchi undov."},
{num:36,time:"00:03:15,219 --> 00:03:17,439",arabic:"مَاذَا قُلْتَ؟",segs:null,full_uz:"Nima dedingiz?",note:null},
{num:37,time:"00:03:17,439 --> 00:03:18,599",arabic:"قُلْتُ...",segs:null,full_uz:"Dedimki...",note:"قُلْتُ — men dedim; قُلْتَ — sen deding."},
{num:38,time:"00:03:27,860 --> 00:03:36,219",arabic:"إِنْ بَقِيَ عَلَى هَذِهِ الْحَالِ فَلَنْ يُفْلِحَ أَبَدًا.",segs:[{ar:"إِنْ بَقِيَ عَلَى هَذِهِ الْحَالِ",uz:"Agar shu holida qolsa"},{ar:"فَلَنْ يُفْلِحَ أَبَدًا.",uz:"hech qachon najot topmaydi."}],full_uz:"Agar shu holida qolsa, hech qachon najot topmaydi.",note:"أَفْلَحَ — muvaffaqiyatga erishmoq, najot topmoq."},
{num:39,time:"00:03:38,579 --> 00:03:41,079",arabic:"مَا اتَّجَرَ أَحَدٌ بِالْكَلَامِ فَأَفْلَحَ.",segs:[{ar:"مَا اتَّجَرَ أَحَدٌ بِالْكَلَامِ",uz:"Hech kim kalom bilan savdo qilib"},{ar:"فَأَفْلَحَ.",uz:"najot topmagan."}],full_uz:"Hech kim kalom bilan savdo qilib najot topmagan.",note:"اتَّجَرَ بِـ — ...bilan savdo qilmoq; bu yerda undan manfaat izlash ma’nosida."},
{num:40,time:"00:03:41,079 --> 00:03:45,099",arabic:"وَلَا ابْتَدَعَ إِلَّا ضَلَّ وَأَضَلَّ.",segs:[{ar:"وَلَا ابْتَدَعَ",uz:"Bid’at chiqargan hech kim yo‘qki"},{ar:"إِلَّا ضَلَّ وَأَضَلَّ.",uz:"o‘zi adashmagan va boshqalarni adashtirmagan bo‘lsin."}],full_uz:"Bid’at chiqargan kishi o‘zi ham adashadi, boshqalarni ham adashtiradi.",note:"ضَلَّ — adashdi; أَضَلَّ — boshqani adashtirdi."},
{num:41,time:"00:03:45,219 --> 00:03:50,000",arabic:"اللَّهُمَّ اهْدِهِ وَأَمْثَالَهُ إِلَى طَرِيقِ الْحَقِّ،",segs:[{ar:"اللَّهُمَّ",uz:"Allohim,"},{ar:"اهْدِهِ وَأَمْثَالَهُ",uz:"uni va unga o‘xshaganlarni hidoyat qil"},{ar:"إِلَى طَرِيقِ الْحَقِّ،",uz:"haq yo‘liga,"}],full_uz:"Allohim, uni va unga o‘xshaganlarni haq yo‘liga hidoyat qil,",note:"اهْدِ — هَدَى fe’lining buyruq shakli; duoda yo‘l ko‘rsat, hidoyat qil ma’nosida."},
{num:42,time:"00:03:50,000 --> 00:03:52,740",arabic:"وَجَنِّبْهُمُ الشَّيْطَانَ وَشَرَكَهُ.",segs:[{ar:"وَجَنِّبْهُمُ",uz:"va ularni uzoq tut"},{ar:"الشَّيْطَانَ وَشَرَكَهُ.",uz:"shayton va uning tuzog‘idan."}],full_uz:"Ularni shayton va uning tuzog‘idan uzoq tut.",note:"شَرَكٌ — tuzoq; شِرْكٌ so‘zidan harakati va ma’nosi bilan farq qiladi."},
{num:43,time:"00:03:52,740 --> 00:03:59,139",arabic:"أَهْلُ الِاعْتِزَالِ يَضِلُّونَ وَيُضِلُّونَ.",segs:[{ar:"أَهْلُ الِاعْتِزَالِ",uz:"Mu’tazila ahli"},{ar:"يَضِلُّونَ وَيُضِلُّونَ.",uz:"o‘zlari adashadilar va boshqalarni adashtiradilar."}],full_uz:"Mu’tazila ahli o‘zlari adashadilar va boshqalarni adashtiradilar.",note:"يَضِلُّونَ — adashadilar; يُضِلُّونَ — adashtiradilar. Birinchi harakat ma’noni o‘zgartiradi."},
{num:44,time:"00:03:59,139 --> 00:04:02,900",arabic:"بَلْ وَيَعْمَلُونَ عَلَى اسْتِقْطَابِ الْكَفَاءَاتِ وَأَهْلِ الْعِلْمِ.",segs:[{ar:"بَلْ وَيَعْمَلُونَ عَلَى اسْتِقْطَابِ",uz:"Hatto o‘zlariga jalb qilishga intiladilar"},{ar:"الْكَفَاءَاتِ وَأَهْلِ الْعِلْمِ.",uz:"qobiliyatli kishilarni va ilm ahlini."}],full_uz:"Hatto qobiliyatli kishilar va ilm ahlini o‘zlariga jalb qilishga intiladilar.",note:"اسْتِقْطَابٌ — o‘z tomoniga jalb qilish. الْكَفَاءَاتُ bu yerda qobiliyatli kishilarni bildiradi."},
{num:45,time:"00:04:02,900 --> 00:04:06,199",arabic:"مَا أَعْجَبُ لَهُ أَنَّ شَابًّا كَبَدْرٍ،",segs:[{ar:"مَا أَعْجَبُ لَهُ",uz:"Meni hayratga solayotgani"},{ar:"أَنَّ شَابًّا كَبَدْرٍ،",uz:"Badrdek bir yigitning,"}],full_uz:"Meni hayratga solayotgani — Badrdek bir yigit...",note:"أَعْجَبُ لَهُ — men undan hayratlanaman; bu yerda أَعْجَبُ hozirgi zamon fe’li."},
{num:46,time:"00:04:06,199 --> 00:04:09,860",arabic:"كُنْتُ أَحْسَبُهُ عَلَى عِلْمٍ أَبْعَدَ عَنْ تَفْكِيرِهِمْ،",segs:[{ar:"كُنْتُ أَحْسَبُهُ عَلَى عِلْمٍ",uz:"Uni ilmli deb o‘ylardim"},{ar:"أَبْعَدَ عَنْ تَفْكِيرِهِمْ،",uz:"ularning fikrlashidan uzoqroq,"}],full_uz:"Uni ilmli, ularning fikrlashidan uzoq deb o‘ylardim,",note:"أَحْسَبُهُ — uni ...deb o‘ylayman. أَبْعَدَ عَنْ — ...dan uzoqroq."},
{num:47,time:"00:04:09,860 --> 00:04:12,300",arabic:"ثُمَّ أَكْتَشِفُ أَنَّهُ وَاحِدٌ مِنْهُمْ.",segs:[{ar:"ثُمَّ أَكْتَشِفُ",uz:"Keyin bilib qolaman"},{ar:"أَنَّهُ وَاحِدٌ مِنْهُمْ.",uz:"u ham ulardan biri ekanini."}],full_uz:"Keyin uning ham ulardan biri ekanini bilib qolaman.",note:"وَاحِدٌ مِنْهُمْ — ulardan biri."},
{num:48,time:"00:04:12,300 --> 00:04:15,960",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"Qudrat va kuch yo‘q"},{ar:"إِلَّا بِاللَّهِ.",uz:"faqat Allohning yordami bilandir."}],full_uz:"Qudrat va kuch faqat Allohning yordami bilandir.",note:null},
{num:49,time:"00:04:15,960 --> 00:04:22,759",arabic:"هُمْ قَوْمٌ لَا يَنْقُصُهُمُ الْعَمَلُ وَالتَّخْطِيطُ.",segs:[{ar:"هُمْ قَوْمٌ",uz:"Ular shunday kishilarki"},{ar:"لَا يَنْقُصُهُمُ الْعَمَلُ وَالتَّخْطِيطُ.",uz:"harakat va rejalashtirishlari kam emas."}],full_uz:"Ular harakat va rejalashtirishda sust kishilar emas.",note:"لَا يَنْقُصُهُمْ — ularda yetishmovchilik yo‘q. تَخْطِيطٌ — rejalashtirish."},
{num:50,time:"00:04:22,759 --> 00:04:27,800",arabic:"وَأَحْسَبُ أَنَّ مُرَادَهُمْ لَنْ يَتَوَقَّفَ عِنْدَ أَهْلِ الْفِقْهِ وَالْعِلْمِ.",segs:[{ar:"وَأَحْسَبُ أَنَّ مُرَادَهُمْ",uz:"Menimcha, ularning maqsadi"},{ar:"لَنْ يَتَوَقَّفَ",uz:"cheklanib qolmaydi"},{ar:"عِنْدَ أَهْلِ الْفِقْهِ وَالْعِلْمِ.",uz:"fiqh va ilm ahli bilan."}],full_uz:"Menimcha, ularning maqsadi fiqh va ilm ahli bilan cheklanib qolmaydi.",note:"تَوَقَّفَ عِنْدَ — ...da to‘xtamoq; bu yerda ...bilan cheklanmoq."},
{num:51,time:"00:04:27,800 --> 00:04:31,460",arabic:"أَخَافُ أَنْ يَصِلُوا إِلَى مَوَاقِعِ السُّلْطَةِ وَالْقَرَارِ.",segs:[{ar:"أَخَافُ أَنْ يَصِلُوا",uz:"Ularning yetib borishidan qo‘rqaman"},{ar:"إِلَى مَوَاقِعِ السُّلْطَةِ وَالْقَرَارِ.",uz:"hokimiyat va qaror qabul qilish lavozimlariga."}],full_uz:"Ularning hokimiyat va qaror qabul qilish lavozimlariga yetib borishidan qo‘rqaman.",note:"مَوَاقِعُ — o‘rinlar, mavqelar; bu yerda boshqaruv lavozimlari."},
{num:52,time:"00:04:31,460 --> 00:04:34,580",arabic:"لَا أَظُنُّ ذَلِكَ يَا أَبَا زَكَرِيَّا.",segs:[{ar:"لَا أَظُنُّ ذَلِكَ",uz:"Men bunday deb o‘ylamayman"},{ar:"يَا أَبَا زَكَرِيَّا.",uz:"Abu Zakariyo."}],full_uz:"Men bunday deb o‘ylamayman, Abu Zakariyo.",note:null},
{num:53,time:"00:04:34,580 --> 00:04:37,199",arabic:"فَالْمُعْتَزِلَةُ لَا يَهْتَمُّونَ بِذَلِكَ.",segs:[{ar:"فَالْمُعْتَزِلَةُ",uz:"Chunki mu’tazilalar"},{ar:"لَا يَهْتَمُّونَ بِذَلِكَ.",uz:"bunga qiziqmaydilar."}],full_uz:"Chunki mu’tazilalar bunga qiziqmaydilar.",note:"اهْتَمَّ بِـ — ...ga qiziqmoq, e’tibor bermoq."},
{num:54,time:"00:04:37,199 --> 00:04:40,060",arabic:"لَا سِيَّمَا أَنَّ أَمِيرَ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدَ،",segs:[{ar:"لَا سِيَّمَا أَنَّ",uz:"Ayniqsa, shuni hisobga olsakki"},{ar:"أَمِيرَ الْمُؤْمِنِينَ هَارُونَ الرَّشِيدَ،",uz:"mo‘minlar amiri Horun ar-Rashid,"}],full_uz:"Ayniqsa, mo‘minlar amiri Horun ar-Rashid",note:"لَا سِيَّمَا — ayniqsa; keyingi fikrga alohida urg‘u beradi."},
{num:55,time:"00:04:40,060 --> 00:04:42,300",arabic:"يُقَرِّبُ أَهْلَ الْحَدِيثِ وَالْفِقْهِ،",segs:[{ar:"يُقَرِّبُ",uz:"o‘ziga yaqin tutadi"},{ar:"أَهْلَ الْحَدِيثِ وَالْفِقْهِ،",uz:"hadis va fiqh ahlini,"}],full_uz:"Hadis va fiqh ahlini o‘ziga yaqin tutadi,",note:"قَرَّبَ — yaqinlashtirmoq; hukmdorning kishilarga e’tibor va mavqe berishini ham bildiradi."},
{num:56,time:"00:04:42,300 --> 00:04:44,920",arabic:"وَيُضَيِّقُ عَلَى أَهْلِ الْفَلْسَفَةِ وَعِلْمِ الْكَلَامِ.",segs:[{ar:"وَيُضَيِّقُ عَلَى",uz:"va siquvga oladi"},{ar:"أَهْلِ الْفَلْسَفَةِ وَعِلْمِ الْكَلَامِ.",uz:"falsafa va kalom ilmi ahlini."}],full_uz:"Falsafa va kalom ilmi ahlini esa siquvga oladi.",note:"ضَيَّقَ عَلَى — imkoniyatlarini cheklamoq, siquvga olmoq."},
{num:57,time:"00:04:44,920 --> 00:04:49,879",arabic:"أَزْمَانُ الْأُمَمِ لَا تُقَاسُ بِعُمْرِ حُكَّامِهَا يَا ابْنَ نُوحٍ.",segs:[{ar:"أَزْمَانُ الْأُمَمِ لَا تُقَاسُ",uz:"Xalqlarning davrlari o‘lchanmaydi"},{ar:"بِعُمْرِ حُكَّامِهَا",uz:"hukmdorlarining umri bilan"},{ar:"يَا ابْنَ نُوحٍ.",uz:"Ibn Nuh."}],full_uz:"Xalqlarning davrlari hukmdorlarining umri bilan o‘lchanmaydi, Ibn Nuh.",note:"تُقَاسُ — o‘lchanadi, majhul nisbat; faol shakli تَقِيسُ."},
{num:58,time:"00:04:49,879 --> 00:04:52,279",arabic:"إِنْ عَجَزُوا الْيَوْمَ فِي عَهْدِ الرَّشِيدِ،",segs:[{ar:"إِنْ عَجَزُوا الْيَوْمَ",uz:"Agar bugun ojiz qolsalar"},{ar:"فِي عَهْدِ الرَّشِيدِ،",uz:"Rashid davrida,"}],full_uz:"Agar bugun Rashid davrida bunga ojiz qolsalar,",note:"عَجَزَ — uddalay olmaslik, ojiz qolmoq. عَهْدٌ — davr."},
{num:59,time:"00:04:52,279 --> 00:04:55,519",arabic:"فَلَنْ يَعْجِزُوا غَدًا فِي عَهْدِ غَيْرِهِ.",segs:[{ar:"فَلَنْ يَعْجِزُوا غَدًا",uz:"ertaga ojiz qolmaydilar"},{ar:"فِي عَهْدِ غَيْرِهِ.",uz:"boshqa hukmdor davrida."}],full_uz:"Ertaga boshqa hukmdor davrida ojiz qolmaydilar.",note:"غَدًا — ertaga; bu yerda kelajak ma’nosida."},
{num:60,time:"00:04:55,519 --> 00:04:58,519",arabic:"مَا يَهُمُّنِي الْآنَ يَا أَبَا الْمُغِيرَةِ هُوَ بَدْرٌ.",segs:[{ar:"مَا يَهُمُّنِي الْآنَ",uz:"Hozir meni tashvishga solayotgani"},{ar:"يَا أَبَا الْمُغِيرَةِ",uz:"Abu Mug‘ira"},{ar:"هُوَ بَدْرٌ.",uz:"Badrdir."}],full_uz:"Abu Mug‘ira, hozir meni tashvishga solayotgani Badrdir.",note:"مَا يَهُمُّنِي — menga muhim bo‘lgan, meni tashvishga solayotgan narsa."},
{num:61,time:"00:04:58,519 --> 00:05:01,459",arabic:"إِنَّهُ شَابٌّ طَيِّبٌ وَذُو عَقْلٍ وَفَهْمٍ.",segs:[{ar:"إِنَّهُ شَابٌّ طَيِّبٌ",uz:"U yaxshi yigit"},{ar:"وَذُو عَقْلٍ وَفَهْمٍ.",uz:"va aql-fahm egasi."}],full_uz:"U yaxshi, aql-fahmli yigit.",note:"ذُو — egasi, sohibi; ذُو عَقْلٍ — aqlli."},
{num:62,time:"00:05:01,459 --> 00:05:05,800",arabic:"وَيَجِبُ عَلَيْنَا أَنْ نَسْعَى إِلَى انْتِشَالِهِ مِنْ بَرَاثِنِ أَهْلِ الْبِدَعِ وَالضَّلَالِ.",segs:[{ar:"وَيَجِبُ عَلَيْنَا أَنْ نَسْعَى",uz:"Biz harakat qilishimiz kerak"},{ar:"إِلَى انْتِشَالِهِ",uz:"uni qutqarishga"},{ar:"مِنْ بَرَاثِنِ أَهْلِ الْبِدَعِ وَالضَّلَالِ.",uz:"bid’at va adashish ahlining changalidan."}],full_uz:"Uni bid’at va adashish ahlining changalidan qutqarishga harakat qilishimiz kerak.",note:"انْتِشَالٌ — tortib chiqarib qutqarish. بَرَاثِنُ — changallar; ko‘chma ma’noda ta’sir yoki hukmronlik."},
{num:63,time:"00:05:05,800 --> 00:05:09,480",arabic:"وَمَا الَّذِي نَسْتَطِيعُ فِعْلَهُ حِيَالَ ذَلِكَ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"وَمَا الَّذِي نَسْتَطِيعُ فِعْلَهُ",uz:"Nima qila olamiz"},{ar:"حِيَالَ ذَلِكَ",uz:"bu borada"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"Abu Abdulloh?"}],full_uz:"Bu borada nima qila olamiz, Abu Abdulloh?",note:"حِيَالَ ذَلِكَ — bu masala yuzasidan, bu borada."},
{num:64,time:"00:05:09,480 --> 00:05:12,000",arabic:"نَسْتَطِيعُ أَنْ نَفْعَلَ الْكَثِيرَ مَعَ بَدْرٍ وَغَيْرِهِ.",segs:[{ar:"نَسْتَطِيعُ أَنْ نَفْعَلَ الْكَثِيرَ",uz:"Ko‘p ish qila olamiz"},{ar:"مَعَ بَدْرٍ وَغَيْرِهِ.",uz:"Badr va boshqalar bilan."}],full_uz:"Badr va boshqalar uchun ko‘p ish qila olamiz.",note:null},
{num:65,time:"00:05:12,000 --> 00:05:17,900",arabic:"أَتُرِيدُنَا أَنْ نَقِفَ مَكْتُوفِي الْأَيْدِي وَنَحْنُ نَرَى مُسْلِمًا يُودِي بِنَفْسِهِ إِلَى الضَّلَالِ؟",segs:[{ar:"أَتُرِيدُنَا أَنْ نَقِفَ",uz:"Bizning turishimizni istaysizmi"},{ar:"مَكْتُوفِي الْأَيْدِي",uz:"qo‘l qovushtirib"},{ar:"وَنَحْنُ نَرَى مُسْلِمًا",uz:"bir musulmonni ko‘rib turib"},{ar:"يُودِي بِنَفْسِهِ إِلَى الضَّلَالِ؟",uz:"o‘zini adashishga olib borayotgan?"}],full_uz:"Bir musulmon o‘zini adashishga olib borayotganini ko‘rib turib, qo‘l qovushtirib turishimizni istaysizmi?",note:"مَكْتُوفِي الْأَيْدِي — qo‘l qovushtirib, hech qanday chora ko‘rmay."},
{num:66,time:"00:05:17,900 --> 00:05:20,960",arabic:"يَجِبُ أَنْ نُنَبِّهَ النَّاسَ إِلَى الْهَاوِيَةِ الَّتِي يَنْجَرِفُونَ إِلَيْهَا.",segs:[{ar:"يَجِبُ أَنْ نُنَبِّهَ النَّاسَ",uz:"Odamlarni ogohlantirishimiz kerak"},{ar:"إِلَى الْهَاوِيَةِ",uz:"tubsiz jarlik haqida"},{ar:"الَّتِي يَنْجَرِفُونَ إِلَيْهَا.",uz:"ular tomon oqib ketayotgan."}],full_uz:"Odamlarni o‘zlari tomon oqib ketayotgan tubsiz jarlikdan ogohlantirishimiz kerak.",note:"هَاوِيَةٌ — chuqur jarlik. انْجَرَفَ — oqimga qo‘shilib ketmoq, ta’sirga berilmoq."},
{num:67,time:"00:05:20,960 --> 00:05:26,480",arabic:"وَسَعْيُنَا إِلَى ذَلِكَ خَيْرٌ لَنَا مِنْ مُدَارَسَةِ مَسْأَلَةٍ أَوْ مَسَائِلَ فِي الْعِلْمِ.",segs:[{ar:"وَسَعْيُنَا إِلَى ذَلِكَ",uz:"Bunga intilishimiz"},{ar:"خَيْرٌ لَنَا",uz:"biz uchun yaxshiroq"},{ar:"مِنْ مُدَارَسَةِ مَسْأَلَةٍ أَوْ مَسَائِلَ",uz:"bir yoki bir nechta masalani birgalikda o‘rganishdan"},{ar:"فِي الْعِلْمِ.",uz:"ilmda."}],full_uz:"Bunga intilishimiz biz uchun ilmning bir yoki bir nechta masalasini birgalikda o‘rganishdan yaxshiroq.",note:"مُدَارَسَةٌ — birgalikda o‘rganish, o‘zaro muhokama qilish."},
{num:68,time:"00:05:26,480 --> 00:05:32,900",arabic:"وَمَا يَنْفَعُ عِلْمُنَا إِذَا لَمْ نُصْلِحْ بِهِ أَحْوَالَ الْمُسْلِمِينَ وَنُرْشِدْهُمْ إِلَى الطَّرِيقِ الْحَقِّ؟",segs:[{ar:"وَمَا يَنْفَعُ عِلْمُنَا",uz:"Ilmimizdan nima foyda"},{ar:"إِذَا لَمْ نُصْلِحْ بِهِ",uz:"agar u bilan tuzatmasak"},{ar:"أَحْوَالَ الْمُسْلِمِينَ",uz:"musulmonlarning ahvolini"},{ar:"وَنُرْشِدْهُمْ إِلَى الطَّرِيقِ الْحَقِّ؟",uz:"va ularni haq yo‘lga boshlamasak?"}],full_uz:"Ilmimiz bilan musulmonlarning ahvolini tuzatib, ularni haq yo‘lga boshlamasak, undan nima foyda?",note:"أَصْلَحَ — tuzatmoq; أَرْشَدَ إِلَى — ...ga yo‘l ko‘rsatmoq."},
{num:69,time:"00:05:35,800 --> 00:05:40,980",arabic:"تَفَضَّلْ يَا أَبَا عَبْدِ الرَّحْمَنِ، تَفَضَّلْ.",segs:[{ar:"تَفَضَّلْ يَا أَبَا عَبْدِ الرَّحْمَنِ،",uz:"Marhamat, Abu Abdurahmon,"},{ar:"تَفَضَّلْ.",uz:"marhamat."}],full_uz:"Marhamat, Abu Abdurahmon, marhamat.",note:null},
{num:70,time:"00:05:40,980 --> 00:05:42,800",arabic:"لِمَاذَا تَضْحَكُ؟",segs:null,full_uz:"Nega kulyapsiz?",note:null},
{num:71,time:"00:05:42,800 --> 00:05:47,819",arabic:"لَقَدْ ذَهَبْتَ لِاصْطِيَادِ الشَّافِعِيِّ فَأَوْشَكَ عَلَى اصْطِيَادِكَ أَيُّهَا الْمَرِيسِيُّ.",segs:[{ar:"لَقَدْ ذَهَبْتَ لِاصْطِيَادِ الشَّافِعِيِّ",uz:"Shofe’iyni ovlashga borgan edingiz"},{ar:"فَأَوْشَكَ عَلَى اصْطِيَادِكَ",uz:"u esa sal bo‘lmasa sizni ovlab olardi"},{ar:"أَيُّهَا الْمَرِيسِيُّ.",uz:"ey Marisiy."}],full_uz:"Shofe’iyni ovlashga borgan edingiz, sal bo‘lmasa u sizni ovlab olardi, Marisiy.",note:"اصْطِيَادٌ — ovlash; bu yerda o‘z fikriga og‘dirish ma’nosida. أَوْشَكَ — sal qoldi."},
{num:72,time:"00:05:47,819 --> 00:05:52,120",arabic:"ظَنَنْتُ أَنَّ فِيهِ خَيْرًا.",segs:null,full_uz:"Unda yaxshilik bor deb o‘ylagandim.",note:null},
{num:73,time:"00:05:52,120 --> 00:05:54,240",arabic:"مَا فَحْوَى مَا دَارَ بَيْنَكُمَا مِنْ حَدِيثٍ؟",segs:[{ar:"مَا فَحْوَى",uz:"Mazmuni nima"},{ar:"مَا دَارَ بَيْنَكُمَا مِنْ حَدِيثٍ؟",uz:"ikkovingiz o‘rtasidagi suhbatning?"}],full_uz:"Ikkovingiz o‘rtasidagi suhbatning mazmuni nima edi?",note:"فَحْوَى — mazmun, asosiy ma’no. دَارَ بَيْنَكُمَا — ikkovingiz o‘rtasida bo‘lib o‘tdi."},
{num:74,time:"00:05:54,240 --> 00:05:58,300",arabic:"دَعْكَ مِمَّا دَارَ بَيْنَنَا، تَعْرِفُ ضَلَالَاتِ أَمْثَالِهِ.",segs:[{ar:"دَعْكَ مِمَّا دَارَ بَيْنَنَا،",uz:"Oramizda bo‘lgan gaplarni qo‘ying,"},{ar:"تَعْرِفُ ضَلَالَاتِ أَمْثَالِهِ.",uz:"unga o‘xshaganlarning adashishlarini bilasiz."}],full_uz:"Oramizda bo‘lgan gaplarni qo‘ying. Unga o‘xshaganlarning adashishlarini bilasiz.",note:"دَعْكَ مِنْ — ...ni qo‘y. أَمْثَالُهُ — unga o‘xshaganlar."},
{num:75,time:"00:05:58,300 --> 00:06:02,240",arabic:"مَتَى يَرْعَوِي أَمْثَالُ هَؤُلَاءِ عَنْ شِرْكِهِمْ؟",segs:[{ar:"مَتَى يَرْعَوِي أَمْثَالُ هَؤُلَاءِ",uz:"Bunday kishilar qachon qaytadilar"},{ar:"عَنْ شِرْكِهِمْ؟",uz:"shirklaridan?"}],full_uz:"Bunday kishilar shirklaridan qachon qaytadilar?",note:"ارْعَوَى عَنْ — yomon ishdan qaytmoq, o‘zini tiymoq."},
{num:76,time:"00:06:02,240 --> 00:06:06,759",arabic:"فَأَمْثَالُ هَؤُلَاءِ عَقَبَةٌ كَأْدَاءُ فِي طَرِيقِنَا.",segs:[{ar:"فَأَمْثَالُ هَؤُلَاءِ",uz:"Bunday kishilar"},{ar:"عَقَبَةٌ كَأْدَاءُ",uz:"juda og‘ir to‘siqdir"},{ar:"فِي طَرِيقِنَا.",uz:"yo‘limizda."}],full_uz:"Bunday kishilar yo‘limizdagi juda og‘ir to‘siqdir.",note:"عَقَبَةٌ كَأْدَاءُ — yengib o‘tish nihoyatda qiyin bo‘lgan to‘siq."},
{num:77,time:"00:06:06,759 --> 00:06:10,920",arabic:"مَا دَامَ هَارُونُ الرَّشِيدُ يُمَهِّدُ السَّاحَاتِ لَهُمْ وَيُضَيِّقُ عَلَيْنَا،",segs:[{ar:"مَا دَامَ هَارُونُ الرَّشِيدُ",uz:"Modomiki Horun ar-Rashid"},{ar:"يُمَهِّدُ السَّاحَاتِ لَهُمْ",uz:"ularga maydon ochib berar ekan"},{ar:"وَيُضَيِّقُ عَلَيْنَا،",uz:"bizni esa siquvga olar ekan,"}],full_uz:"Modomiki Horun ar-Rashid ularga maydon ochib berib, bizni siquvga olar ekan,",note:"مَا دَامَ — modomiki, ...ekan. مَهَّدَ — yo‘l ochmoq, sharoit yaratmoq."},
{num:78,time:"00:06:10,920 --> 00:06:13,620",arabic:"فَإِنَّهُمْ فِي مَنَعَةٍ مِنْ أَمْرِهِمْ.",segs:null,full_uz:"Ular o‘z ishlarida himoyadadirlar.",note:"مَنَعَةٌ — himoya, kishini zarar yetishidan saqlaydigan kuch."},
{num:79,time:"00:06:13,620 --> 00:06:16,660",arabic:"خَسَفَ اللَّهُ الْأَرْضَ بِهَارُونَ وَزَبَانِيَتِهِ!",segs:[{ar:"خَسَفَ اللَّهُ الْأَرْضَ",uz:"Alloh yerga yuttirsin"},{ar:"بِهَارُونَ وَزَبَانِيَتِهِ!",uz:"Horunni va uning zolim xizmatchilarini!"}],full_uz:"Alloh Horunni va uning zolim xizmatchilarini yerga yuttirsin!",note:"خَسَفَ بِهِ الْأَرْضَ — uni yerga yuttirdi. O‘tgan zamon bu yerda qarg‘ish ma’nosida."},
{num:80,time:"00:06:16,660 --> 00:06:20,300",arabic:"إِنَّهُ يُسِيءُ لِلِاسْمِ الَّذِي يَحْمِلُهُ.",segs:[{ar:"إِنَّهُ يُسِيءُ لِلِاسْمِ",uz:"U ismiga dog‘ tushirmoqda"},{ar:"الَّذِي يَحْمِلُهُ.",uz:"o‘zi olib yurgan."}],full_uz:"U o‘zi olib yurgan ismga dog‘ tushirmoqda.",note:"أَسَاءَ لِـ — ...ga yomonlik qilmoq; bu yerda nomiga dog‘ tushirmoq."},
{num:81,time:"00:06:20,300 --> 00:06:25,460",arabic:"كَانَ الْأَجْدَرَ بِأَبِيهِ الْمَهْدِيِّ أَنْ يُسَمِّيَهُ فِرْعَوْنَ لَا هَارُونَ.",segs:[{ar:"كَانَ الْأَجْدَرَ بِأَبِيهِ الْمَهْدِيِّ",uz:"Otasi Mahdiyga munosibroq edi"},{ar:"أَنْ يُسَمِّيَهُ فِرْعَوْنَ",uz:"uni Fir’avn deb atash"},{ar:"لَا هَارُونَ.",uz:"Horun emas."}],full_uz:"Otasi Mahdiy unga Horun emas, Fir’avn deb ism qo‘ygani munosibroq edi.",note:"الْأَجْدَرُ بِـ — ...ga munosibroq, loyiqroq."},
{num:82,time:"00:06:25,460 --> 00:06:29,540",arabic:"وَيَمُدُّهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ.",segs:[{ar:"وَيَمُدُّهُمْ فِي طُغْيَانِهِمْ",uz:"Ularni tug‘yonlarida davom ettiradi"},{ar:"يَعْمَهُونَ.",uz:"adashib yuradigan hollarida."}],full_uz:"Ularni tug‘yonlarida adashib yurishlariga qo‘yib beradi.",note:"طُغْيَانٌ — haddan oshish, tug‘yon; يَعْمَهُونَ — yo‘l topolmay adashib yuradilar."},
{num:83,time:"00:06:29,540 --> 00:06:31,699",arabic:"لِلْبَاطِلِ جَوْلَةٌ يَا بِشْرُ،",segs:[{ar:"لِلْبَاطِلِ جَوْلَةٌ",uz:"Botilning ham bir davri bor"},{ar:"يَا بِشْرُ،",uz:"Bishr,"}],full_uz:"Botilning ham bir davri bor, Bishr,",note:"جَوْلَةٌ — navbat, bir bosqich; bu yerda vaqtinchalik ustunlik davri."},
{num:84,time:"00:06:31,699 --> 00:06:36,000",arabic:"ثُمَّ يَمْحَقُ اللَّهُ الْكَافِرِينَ عَلَى يَدِ أَهْلِ الْحَقِّ.",segs:[{ar:"ثُمَّ يَمْحَقُ اللَّهُ الْكَافِرِينَ",uz:"So‘ng Alloh kofirlarni yo‘q qiladi"},{ar:"عَلَى يَدِ أَهْلِ الْحَقِّ.",uz:"haq ahli qo‘li bilan."}],full_uz:"So‘ng Alloh kofirlarni haq ahli qo‘li bilan yo‘q qiladi.",note:"مَحَقَ — yo‘q qilmoq, barham bermoq. عَلَى يَدِ — ...ning qo‘li bilan, vositasida."},
{num:85,time:"00:06:36,000 --> 00:06:42,420",arabic:"اسْمَعْ يَا أَبَا عَبْدِ اللَّهِ،",segs:[{ar:"اسْمَعْ",uz:"Eshiting"},{ar:"يَا أَبَا عَبْدِ اللَّهِ،",uz:"Abu Abdulloh,"}],full_uz:"Eshiting, Abu Abdulloh,",note:null},
{num:86,time:"00:06:42,420 --> 00:06:50,879",arabic:"كُنْتُ أَخَذْتُ رَأْيَ أَبِي الْعَبَّاسِ فِي أَمْرٍ أَنْوِي طَرْحَهُ عَلَيْكَ.",segs:[{ar:"كُنْتُ أَخَذْتُ رَأْيَ أَبِي الْعَبَّاسِ",uz:"Abu Abbosning fikrini olgan edim"},{ar:"فِي أَمْرٍ",uz:"bir masala haqida"},{ar:"أَنْوِي طَرْحَهُ عَلَيْكَ.",uz:"sizga taklif qilmoqchi bo‘lgan."}],full_uz:"Sizga taklif qilmoqchi bo‘lgan bir masala haqida Abu Abbosning fikrini olgan edim.",note:"أَخَذَ رَأْيَهُ — uning fikrini so‘radi. طَرَحَ عَلَيْهِ أَمْرًا — unga bir masalani taklif qildi."},
{num:87,time:"00:06:50,879 --> 00:06:54,819",arabic:"حَالَفَكَ التَّوْفِيقُ فِي كُلِّ أَمْرِكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"حَالَفَكَ التَّوْفِيقُ",uz:"Muvaffaqiyat sizga yor bo‘lsin"},{ar:"فِي كُلِّ أَمْرِكَ",uz:"barcha ishlaringizda"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ.",uz:"ey mo‘minlar amiri."}],full_uz:"Barcha ishlaringizda muvaffaqiyat sizga yor bo‘lsin, mo‘minlar amiri.",note:"حَالَفَهُ التَّوْفِيقُ — muvaffaqiyat unga yor bo‘ldi; bu yerda tilak ma’nosida."},
{num:88,time:"00:06:55,379 --> 00:06:58,860",arabic:"كُنْتُ أَسْأَلُ عَنْ رَجُلِ دِينٍ وَعِلْمٍ وَخُلُقٍ،",segs:[{ar:"كُنْتُ أَسْأَلُ عَنْ رَجُلِ",uz:"Bir kishini surishtirayotgan edim"},{ar:"دِينٍ وَعِلْمٍ وَخُلُقٍ،",uz:"din, ilm va yaxshi xulq egasi bo‘lgan,"}],full_uz:"Din, ilm va yaxshi xulq egasi bo‘lgan bir kishini surishtirayotgan edim,",note:"رَجُلُ دِينٍ وَعِلْمٍ — din va ilm egasi bo‘lgan kishi."},
{num:89,time:"00:06:58,860 --> 00:07:02,420",arabic:"حَرِيصٍ عَلَى إِقَامَةِ الْعَدْلِ بِالْمِيزَانِ،",segs:[{ar:"حَرِيصٍ عَلَى إِقَامَةِ الْعَدْلِ",uz:"adolatni qaror toptirishga intiladigan"},{ar:"بِالْمِيزَانِ،",uz:"to‘g‘ri mezon bilan,"}],full_uz:"To‘g‘ri mezon bilan adolatni qaror toptirishga intiladigan,",note:"حَرِيصٌ عَلَى — biror ishga kuchli intiladigan, uni qilishga astoydil qiziqadigan."},
{num:90,time:"00:07:02,420 --> 00:07:05,439",arabic:"وَيَصْلُحُ لِوِلَايَةِ الْقَضَاءِ.",segs:[{ar:"وَيَصْلُحُ",uz:"va munosib bo‘lgan"},{ar:"لِوِلَايَةِ الْقَضَاءِ.",uz:"qozilik lavozimiga."}],full_uz:"Va qozilik lavozimiga munosib bo‘lgan kishini.",note:"صَلَحَ لِـ — ...ga yaroqli, munosib bo‘lmoq. وِلَايَةُ الْقَضَاءِ — qozilik vazifasi."},
{num:91,time:"00:07:05,439 --> 00:07:06,480",arabic:"وَإِنِّي وَاللَّهِ،",segs:null,full_uz:"Men esa, Allohga qasamki,",note:"وَاللَّهِ — Allohga qasamki; gap keyingi parchada davom etadi."},
{num:92,time:"00:07:06,480 --> 00:07:11,139",arabic:"وَاللَّهِ لَمْ أَرَ مَنْ هُوَ أَفْضَلُ مِنْكَ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasamki,"},{ar:"لَمْ أَرَ",uz:"ko‘rmadim"},{ar:"مَنْ هُوَ أَفْضَلُ مِنْكَ.",uz:"sizdan afzalroq kishini."}],full_uz:"Allohga qasamki, sizdan afzalroq kishini ko‘rmadim.",note:"لَمْ أَرَ — ko‘rmadim; jazm sababli أَرَى fe’lining oxirgi ا harfi tushgan."},
{num:93,time:"00:07:11,139 --> 00:07:12,439",arabic:"فَمَا تَقُولُ؟",segs:null,full_uz:"Xo‘sh, nima deysiz?",note:null},
{num:94,time:"00:07:15,160 --> 00:07:18,600",arabic:"إِنَّهُ لَشَرَفٌ لِكُلِّ أَحَدٍ،",segs:[{ar:"إِنَّهُ لَشَرَفٌ",uz:"Bu albatta sharafdir"},{ar:"لِكُلِّ أَحَدٍ،",uz:"har bir kishi uchun,"}],full_uz:"Bu har bir kishi uchun, albatta, sharafdir,",note:"إِنَّ va لَ birga kelib fikrni kuchli ta’kidlaydi."},
{num:95,time:"00:07:18,600 --> 00:07:21,160",arabic:"مَا تَفَضَّلَ بِهِ أَمِيرُ الْمُؤْمِنِينَ.",segs:[{ar:"مَا تَفَضَّلَ بِهِ",uz:"marhamat qilib taklif etgan narsa"},{ar:"أَمِيرُ الْمُؤْمِنِينَ.",uz:"mo‘minlar amiri."}],full_uz:"Mo‘minlar amiri marhamat qilib taklif etgan narsa.",note:"تَفَضَّلَ بِـ — marhamat qilib bermoq yoki taklif etmoq."},
{num:96,time:"00:07:21,160 --> 00:07:23,800",arabic:"وَإِنَّهُ لَيُسْعِدُنِي،",segs:null,full_uz:"Meni, albatta, xursand qiladi,",note:"أَسْعَدَ — xursand qilmoq. Nima xursand qilayotgani keyingi parchada aytiladi."},
{num:97,time:"00:07:23,800 --> 00:07:26,300",arabic:"أَنْ أَكُونَ عِنْدَ حُسْنِ ظَنِّكَ،",segs:null,full_uz:"Sizning ishonchingizga munosib bo‘lishim,",note:"كَانَ عِنْدَ حُسْنِ ظَنِّهِ — uning yaxshi gumoni va ishonchiga munosib bo‘lmoq."},
{num:98,time:"00:07:26,300 --> 00:07:28,800",arabic:"فَأَكُونَ أَوَّلَ خَاطِرٍ لِذِهْنِكَ.",segs:[{ar:"فَأَكُونَ أَوَّلَ خَاطِرٍ",uz:"va birinchi xayolga kelgan kishi bo‘lishim"},{ar:"لِذِهْنِكَ.",uz:"sizning ongingizga."}],full_uz:"Va xayolingizga birinchi kelgan kishi bo‘lishim.",note:"خَاطِرٌ — xayolga kelgan fikr; bu yerda birinchi eslangan nomzod nazarda tutilgan."},
{num:99,time:"00:07:28,800 --> 00:07:35,300",arabic:"كَمَا يُحْزِنُنِي يَا مَوْلَايَ أَنْ أَعْتَذِرَ عَنْ ذَلِكَ،",segs:[{ar:"كَمَا يُحْزِنُنِي",uz:"Shuningdek, meni xafa qiladi"},{ar:"يَا مَوْلَايَ",uz:"hazratim"},{ar:"أَنْ أَعْتَذِرَ عَنْ ذَلِكَ،",uz:"bu taklifni uzr aytib rad etishim,"}],full_uz:"Shuningdek, bu taklifni uzr aytib rad etishim meni xafa qiladi, hazratim,",note:"اعْتَذَرَ عَنْ — uzr aytmoq; taklif yoki vazifaga nisbatan uni uzr bilan qabul qilmaslikni ham bildiradi."},
{num:100,time:"00:07:35,300 --> 00:07:39,259",arabic:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ قَبُولَ اعْتِذَارِي.",segs:[{ar:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ",uz:"Agar mo‘minlar amiri ma’qul ko‘rsalar"},{ar:"قَبُولَ اعْتِذَارِي.",uz:"uzrimni qabul qilishni."}],full_uz:"Agar mo‘minlar amiri uzrimni qabul qilishni ma’qul ko‘rsalar.",note:"رَأَى — bu yerda ko‘rmoq emas, ma’qul ko‘rmoq, qaror qilmoq."},
{num:101,time:"00:07:39,259 --> 00:07:44,819",arabic:"وَلِمَ الِاعْتِذَارُ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"وَلِمَ الِاعْتِذَارُ",uz:"Nega uzr aytib rad etasiz"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"Abu Abdulloh?"}],full_uz:"Nega uzr aytib rad etasiz, Abu Abdulloh?",note:"لِمَ — nima uchun?; لِ va so‘roq bildiruvchi مَا birikishidan hosil bo‘lgan."},
{num:102,time:"00:07:44,819 --> 00:07:46,860",arabic:"لَقَدْ أَخْبَرْتُكَ يَا أَمِيرَ الْمُؤْمِنِينَ،",segs:[{ar:"لَقَدْ أَخْبَرْتُكَ",uz:"Sizga aytgan edim"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ،",uz:"mo‘minlar amiri,"}],full_uz:"Sizga aytgan edim, mo‘minlar amiri,",note:null},
{num:103,time:"00:07:46,860 --> 00:07:55,100",arabic:"إِنَّمَا أَنَا رَجُلٌ نَذَرَ نَفْسَهُ لِطَلَبِ الْعِلْمِ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ،",segs:[{ar:"إِنَّمَا أَنَا رَجُلٌ",uz:"Men faqat bir kishimanki"},{ar:"نَذَرَ نَفْسَهُ",uz:"o‘zini bag‘ishlagan"},{ar:"لِطَلَبِ الْعِلْمِ",uz:"ilm talab qilishga"},{ar:"فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ،",uz:"qudratli va ulug‘ Allohning Kitobidan,"}],full_uz:"Men o‘zini qudratli va ulug‘ Allohning Kitobidan ilm talab qilishga bag‘ishlagan bir kishiman,",note:"نَذَرَ نَفْسَهُ لِـ — o‘zini biror maqsadga bag‘ishlamoq."},
{num:104,time:"00:07:55,100 --> 00:07:58,639",arabic:"وَسُنَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"وَسُنَّةِ رَسُولِهِ",uz:"va Uning Rasulining sunnatidan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",uz:"Alloh u zotga salavot va salom yo‘llasin."}],full_uz:"Va Uning Rasuli sollallohu alayhi vasallamning sunnatidan.",note:"سُنَّةِ oldingi parchadagi كِتَابِ so‘ziga bog‘lanib, qaratqich holatida kelgan."},
{num:105,time:"00:08:00,439 --> 00:08:03,639",arabic:"وَلَا أُرِيدُ أَنْ يَشْغَلَنِي عَنْ ذَلِكَ أَيُّ شَاغِلٍ.",segs:[{ar:"وَلَا أُرِيدُ",uz:"Istamayman"},{ar:"أَنْ يَشْغَلَنِي عَنْ ذَلِكَ",uz:"meni bundan chalg‘itishini"},{ar:"أَيُّ شَاغِلٍ.",uz:"biror mashg‘ulotning."}],full_uz:"Biror mashg‘ulot meni bundan chalg‘itishini istamayman.",note:"شَغَلَهُ عَنْ — uni ...dan chalg‘itmoq, boshqa ish bilan band qilmoq."},
{num:106,time:"00:08:04,279 --> 00:08:08,639",arabic:"لِمَاذَا ذَهَبْتَ إِلَى الْيَمَنِ إِذَنْ؟",segs:[{ar:"لِمَاذَا ذَهَبْتَ إِلَى الْيَمَنِ",uz:"Nega Yamanga bordingiz"},{ar:"إِذَنْ؟",uz:"unday bo‘lsa?"}],full_uz:"Unday bo‘lsa, nega Yamanga bordingiz?",note:null},
{num:107,time:"00:08:10,159 --> 00:08:12,680",arabic:"ذَهَبْتُ إِلَيْهَا مُتَعَلِّمًا.",segs:[{ar:"ذَهَبْتُ إِلَيْهَا",uz:"U yerga bordim"},{ar:"مُتَعَلِّمًا.",uz:"ilm o‘rganuvchi sifatida."}],full_uz:"U yerga ilm o‘rganish uchun bordim.",note:"مُتَعَلِّمًا — hol: o‘rganuvchi sifatida, ta’lim olish niyatida."},
{num:108,time:"00:08:12,680 --> 00:08:19,060",arabic:"وَلَكِنَّ عِلْمَ أَبِي حَنِيفَةَ وَصَاحِبِهِ أَبِي يُوسُفَ رَحِمَهُمَا اللَّهُ،",segs:[{ar:"وَلَكِنَّ عِلْمَ أَبِي حَنِيفَةَ",uz:"Lekin Abu Hanifaning ilmi"},{ar:"وَصَاحِبِهِ أَبِي يُوسُفَ",uz:"va uning hamrohi Abu Yusufning"},{ar:"رَحِمَهُمَا اللَّهُ،",uz:"Alloh ikkovini rahmat qilsin,"}],full_uz:"Lekin Abu Hanifa va uning hamrohi Abu Yusufning ilmi — Alloh ikkovini rahmat qilsin —",note:"رَحِمَهُمَا — u ikkovini rahmat qilsin; ـهُمَا ikkilik olmoshi."},
{num:109,time:"00:08:19,060 --> 00:08:23,899",arabic:"أَخَذَ بِمَجَامِعِ عَقْلِي وَتَلَابِيبِ نَفْسِي.",segs:[{ar:"أَخَذَ بِمَجَامِعِ عَقْلِي",uz:"butun aqlimni band etdi"},{ar:"وَتَلَابِيبِ نَفْسِي.",uz:"va qalbimni mahkam tutdi."}],full_uz:"Butun aqlim va qalbimni o‘ziga rom etdi.",note:"أَخَذَ بِمَجَامِعِ... — butunlay rom etmoq. تَلَابِيبُ — yoqa qismlari; bu yerda ko‘chma ma’noda."},
{num:110,time:"00:08:23,899 --> 00:08:28,539",arabic:"فَوَدِدْتُ الْمُكُوثَ هُنَا فِي بَغْدَادَ لِكَيْ أَسْتَزِيدَ مِنْ عِلْمِهِمَا.",segs:[{ar:"فَوَدِدْتُ الْمُكُوثَ هُنَا",uz:"Shuning uchun shu yerda qolishni istadim"},{ar:"فِي بَغْدَادَ",uz:"Bag‘dodda"},{ar:"لِكَيْ أَسْتَزِيدَ مِنْ عِلْمِهِمَا.",uz:"ikkovining ilmidan ko‘proq olish uchun."}],full_uz:"Shuning uchun ikkovining ilmidan ko‘proq olish maqsadida shu yerda, Bag‘dodda qolishni istadim.",note:"الْمُكُوثُ — qolish. اسْتَزَادَ مِنْ — ...dan ko‘proq olishga intilmoq."},
{num:111,time:"00:08:28,639 --> 00:08:33,939",arabic:"وَقَرَّرْتُ أَنْ أَنْقَطِعَ لَا لِشَيْءٍ إِلَّا لِطَلَبِ الْعِلْمِ.",segs:[{ar:"وَقَرَّرْتُ أَنْ أَنْقَطِعَ",uz:"O‘zimni bag‘ishlashga qaror qildim"},{ar:"لَا لِشَيْءٍ",uz:"boshqa hech narsaga emas"},{ar:"إِلَّا لِطَلَبِ الْعِلْمِ.",uz:"faqat ilm talab qilishga."}],full_uz:"O‘zimni faqat ilm talab qilishga bag‘ishlashga qaror qildim.",note:"انْقَطَعَ لِـ — boshqa ishlardan chekinib, o‘zini bir ishga bag‘ishlamoq."},
{num:112,time:"00:08:33,939 --> 00:08:40,319",arabic:"فَأَنْتَ تَرْفُضُ تَوَلِّيَ مَنْصِبِ الْقَضَاءِ؟",segs:[{ar:"فَأَنْتَ تَرْفُضُ",uz:"Demak, siz rad etyapsizmi"},{ar:"تَوَلِّيَ مَنْصِبِ الْقَضَاءِ؟",uz:"qozilik lavozimini egallashni?"}],full_uz:"Demak, siz qozilik lavozimini egallashni rad etyapsizmi?",note:"تَوَلِّي مَنْصِبٍ — lavozimni egallash, vazifani zimmasiga olish."},
{num:113,time:"00:08:40,319 --> 00:08:44,019",arabic:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ أَنْ يُعْفِيَنِي.",segs:[{ar:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ",uz:"Agar mo‘minlar amiri ma’qul ko‘rsalar"},{ar:"أَنْ يُعْفِيَنِي.",uz:"meni ozod etishni."}],full_uz:"Agar mo‘minlar amiri meni bu vazifadan ozod etishni ma’qul ko‘rsalar.",note:"أَعْفَاهُ مِنْ — uni vazifa yoki majburiyatdan ozod qilmoq."},
{num:114,time:"00:08:58,639 --> 00:09:08,819",arabic:"وَأَمِيرُ الْمُؤْمِنِينَ لَنْ يَقِفَ بَيْنَكَ وَبَيْنَ رَغْبَتِكَ فِي فِقْهِ كِتَابِ اللَّهِ،",segs:[{ar:"وَأَمِيرُ الْمُؤْمِنِينَ لَنْ يَقِفَ",uz:"Mo‘minlar amiri to‘siq bo‘lmaydi"},{ar:"بَيْنَكَ وَبَيْنَ رَغْبَتِكَ",uz:"siz bilan istagingiz o‘rtasida"},{ar:"فِي فِقْهِ كِتَابِ اللَّهِ،",uz:"Allohning Kitobini chuqur tushunishdagi,"}],full_uz:"Mo‘minlar amiri Allohning Kitobini chuqur tushunish istagingizga to‘siq bo‘lmaydi,",note:"وَقَفَ بَيْنَهُ وَبَيْنَ... — u bilan ...orasiga tushib, to‘siq bo‘lmoq."},
{num:115,time:"00:09:08,819 --> 00:09:12,019",arabic:"وَسُنَّةِ النَّبِيِّ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ.",segs:[{ar:"وَسُنَّةِ النَّبِيِّ",uz:"va Payg‘ambarning sunnatini"},{ar:"عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ.",uz:"u zotga salavot va salom bo‘lsin."}],full_uz:"Va Payg‘ambar alayhissalotu vassalomning sunnatini chuqur tushunish istagingizga ham.",note:null},
{num:116,time:"00:09:12,019 --> 00:09:14,019",arabic:"عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ.",segs:null,full_uz:"U zotga salavot va salom bo‘lsin.",note:null},
{num:117,time:"00:09:14,019 --> 00:09:24,620",arabic:"وَلَكِنْ لِي عَلَيْكَ شَرْطٌ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"وَلَكِنْ لِي عَلَيْكَ شَرْطٌ",uz:"Lekin sizga bir shartim bor"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"Abu Abdulloh."}],full_uz:"Lekin sizga bir shartim bor, Abu Abdulloh.",note:"لِي عَلَيْكَ شَرْطٌ — sizga qo‘yadigan bir shartim bor."},
{num:118,time:"00:09:24,620 --> 00:09:28,620",arabic:"أَمِيرُ الْمُؤْمِنِينَ يَأْمُرُ وَنَحْنُ نُجِيبُ.",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ يَأْمُرُ",uz:"Mo‘minlar amiri buyuradilar"},{ar:"وَنَحْنُ نُجِيبُ.",uz:"biz esa javob beramiz."}],full_uz:"Mo‘minlar amiri buyuradilar, biz esa bajo keltiramiz.",note:"نُجِيبُ — javob beramiz; bu yerda buyruqqa rozilik bilan javob berish."},
{num:119,time:"00:09:28,620 --> 00:09:34,379",arabic:"أَلَّا تَنْقَطِعَ عَنْ زِيَارَةِ مَجْلِسِي بَيْنَ الْفَيْنَةِ وَالْفَيْنَةِ.",segs:[{ar:"أَلَّا تَنْقَطِعَ عَنْ زِيَارَةِ مَجْلِسِي",uz:"Majlisimga kelishni to‘xtatmasligingiz"},{ar:"بَيْنَ الْفَيْنَةِ وَالْفَيْنَةِ.",uz:"vaqti-vaqti bilan."}],full_uz:"Majlisimga vaqti-vaqti bilan kelib turishni to‘xtatmasligingiz.",note:"بَيْنَ الْفَيْنَةِ وَالْفَيْنَةِ — vaqti-vaqti bilan. أَلَّا — أَنْ va لَا birikmasi."},
{num:120,time:"00:09:34,379 --> 00:09:38,379",arabic:"لِأَمِيرِ الْمُؤْمِنِينَ مَا يُرِيدُ.",segs:[{ar:"لِأَمِيرِ الْمُؤْمِنِينَ",uz:"Mo‘minlar amiri uchun"},{ar:"مَا يُرِيدُ.",uz:"istaganlari bo‘ladi."}],full_uz:"Mo‘minlar amiri istaganlaridek bo‘ladi.",note:null},
{num:121,time:"00:09:38,379 --> 00:09:40,500",arabic:"بَارَكَ اللَّهُ فِيكَ.",segs:null,full_uz:"Alloh sizga baraka bersin.",note:null},
{num:122,time:"00:09:40,500 --> 00:09:44,039",arabic:"خَيْرًا يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"خَيْرًا",uz:"Tinchlikmi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"Abu Abdulloh?"}],full_uz:"Tinchlikmi, Abu Abdulloh?",note:"خَيْرًا؟ — biror chaqiruv yoki g‘ayrioddiy holat sababini so‘rashda tinchlikmi? ma’nosida keladi."},
{num:123,time:"00:09:44,039 --> 00:09:47,279",arabic:"مَا الْأَمْرُ الَّذِي نَادَيْتَنِي مِنْ أَجْلِهِ؟",segs:[{ar:"مَا الْأَمْرُ",uz:"Qanday masala"},{ar:"الَّذِي نَادَيْتَنِي مِنْ أَجْلِهِ؟",uz:"meni uning uchun chaqirdingiz?"}],full_uz:"Meni qanday masala uchun chaqirdingiz?",note:"مِنْ أَجْلِهِ — uning uchun, shu sababli."},
{num:124,time:"00:09:47,279 --> 00:09:50,419",arabic:"لَقَدْ سَمِعْتُ أَنَّكَ تَخْتَلِفُ إِلَى شُيُوخِ أَهْلِ الِاعْتِزَالِ.",segs:[{ar:"لَقَدْ سَمِعْتُ أَنَّكَ",uz:"Eshitdimki, sen"},{ar:"تَخْتَلِفُ إِلَى",uz:"qatnab yurarkansan"},{ar:"شُيُوخِ أَهْلِ الِاعْتِزَالِ.",uz:"mu’tazila ahli shayxlari huzuriga."}],full_uz:"Mu’tazila ahli shayxlari huzuriga qatnab yurganingni eshitdim.",note:"اخْتَلَفَ إِلَى — bir joyga qayta-qayta qatnamoq; اخْتَلَفَ مَعَ esa kelishmaslikni bildiradi."},
{num:125,time:"00:09:50,419 --> 00:09:54,820",arabic:"وَرَأَيْتُ نُصْحَكَ بِمَا بَيْنَنَا مِنَ الْأُخُوَّةِ وَالدِّينِ.",segs:[{ar:"وَرَأَيْتُ نُصْحَكَ",uz:"Senga nasihat qilishni lozim ko‘rdim"},{ar:"بِمَا بَيْنَنَا",uz:"oramizdagi sababli"},{ar:"مِنَ الْأُخُوَّةِ وَالدِّينِ.",uz:"birodarlik va din."}],full_uz:"Oramizdagi birodarlik va din tufayli senga nasihat qilishni lozim ko‘rdim.",note:"نُصْحٌ — samimiy maslahat, yaxshilikni ko‘zlab yo‘l ko‘rsatish."},
{num:126,time:"00:09:54,820 --> 00:09:58,600",arabic:"قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:",segs:[{ar:"قَدْ قَالَ رَسُولُ اللَّهِ",uz:"Allohning Rasuli aytganlar"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:",uz:"Alloh u zotga salavot va salom yo‘llasin:"}],full_uz:"Allohning Rasuli sollallohu alayhi vasallam aytganlar:",note:null},
{num:127,time:"00:10:00,100 --> 00:10:04,260",arabic:"إِنَّ الدِّينَ النَّصِيحَةُ.",segs:null,full_uz:"Albatta, din — nasihatdir.",note:"النَّصِيحَةُ — samimiylik, yaxshilikni istash va samimiy maslahat; faqat tanbeh berish bilan cheklanmaydi."},
{num:128,time:"00:10:04,260 --> 00:10:06,140",arabic:"قِيلَ: لِمَنْ يَا رَسُولَ اللَّهِ؟",segs:[{ar:"قِيلَ: لِمَنْ",uz:"Kimga, deb so‘raldi"},{ar:"يَا رَسُولَ اللَّهِ؟",uz:"ey Allohning Rasuli?"}],full_uz:"«Kimga, ey Allohning Rasuli?» deb so‘raldi.",note:"قِيلَ — aytildi, majhul nisbat; bu yerda savol berildi ma’nosida."},
{num:129,time:"00:10:06,140 --> 00:10:09,200",arabic:"قَالَ: لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ،",segs:[{ar:"قَالَ: لِلَّهِ",uz:"Dedilar: Allohga"},{ar:"وَلِكِتَابِهِ",uz:"va Uning Kitobiga"},{ar:"وَلِرَسُولِهِ،",uz:"va Uning Rasuliga,"}],full_uz:"Dedilar: «Allohga, Uning Kitobiga va Rasuliga,",note:"Bu o‘rinda nasihat Allohga, Kitobiga va Rasuliga samimiy sadoqat ma’nosini anglatadi."},
{num:130,time:"00:10:09,200 --> 00:10:11,600",arabic:"وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ.",segs:[{ar:"وَلِأَئِمَّةِ الْمُسْلِمِينَ",uz:"musulmonlarning rahbarlariga"},{ar:"وَعَامَّتِهِمْ.",uz:"va oddiy musulmonlarga»."}],full_uz:"Musulmonlarning rahbarlariga va oddiy musulmonlarga».",note:"أَئِمَّةٌ — إِمَامٌ so‘zining ko‘pligi; عَامَّتُهُمْ — ularning oddiy ommasi."},
{num:131,time:"00:10:11,600 --> 00:10:14,580",arabic:"هَؤُلَاءِ الْقَوْمُ ابْتَدَعُوا فِي دِينِ اللَّهِ،",segs:[{ar:"هَؤُلَاءِ الْقَوْمُ ابْتَدَعُوا",uz:"Bu kishilar bid’at chiqardilar"},{ar:"فِي دِينِ اللَّهِ،",uz:"Allohning dinida,"}],full_uz:"Bu kishilar Allohning dinida bid’at chiqardilar,",note:"ابْتَدَعَ — yangilik kiritmoq; diniy kontekstda bid’at chiqarmoq."},
{num:132,time:"00:10:14,580 --> 00:10:16,420",arabic:"وَقَالُوا فِيهِ مَقَالَاتٍ،",segs:null,full_uz:"Va u haqda shunday qarashlarni aytdilarki,",note:"مَقَالَاتٌ — bu yerda qarashlar, aytilgan fikrlar; maqolalar ma’nosida emas."},
{num:133,time:"00:10:16,420 --> 00:10:19,520",arabic:"لَمْ يَقُلْهَا مَنْ سَبَقَنَا مِنَ الصَّحَابَةِ وَالتَّابِعِينَ.",segs:[{ar:"لَمْ يَقُلْهَا مَنْ سَبَقَنَا",uz:"ularni bizdan ilgari o‘tganlar aytmagan"},{ar:"مِنَ الصَّحَابَةِ وَالتَّابِعِينَ.",uz:"sahobalar va tobeinlardan."}],full_uz:"Ularni bizdan ilgari o‘tgan sahobalar va tobeinlar aytmagan.",note:"مَنْ سَبَقَنَا — bizdan oldin o‘tganlar. التَّابِعُونَ — sahobalardan keyingi, ulardan ta’lim olgan avlod."},
{num:134,time:"00:10:19,520 --> 00:10:22,360",arabic:"وَمَاذَا نُقِلَ إِلَيْكَ مِنْ أَقْوَالِهِمْ؟",segs:[{ar:"وَمَاذَا نُقِلَ إِلَيْكَ",uz:"Sizga nima yetkazildi"},{ar:"مِنْ أَقْوَالِهِمْ؟",uz:"ularning so‘zlaridan?"}],full_uz:"Ularning qaysi so‘zlari sizga yetkazildi?",note:"نُقِلَ — yetkazildi; نَقَلَ — yetkazdi."},
{num:135,time:"00:10:22,360 --> 00:10:23,220",arabic:"كُلُّ سُوءٍ.",segs:null,full_uz:"Har qanday yomonlik.",note:null},
{num:136,time:"00:10:24,059 --> 00:10:26,699",arabic:"الْقُرْآنُ الْكَرِيمُ كَلَامُ اللَّهِ،",segs:[{ar:"الْقُرْآنُ الْكَرِيمُ",uz:"Qur’oni karim"},{ar:"كَلَامُ اللَّهِ،",uz:"Allohning kalomidir,"}],full_uz:"Qur’oni karim Allohning kalomidir,",note:null},
{num:137,time:"00:10:26,699 --> 00:10:29,239",arabic:"لَكِنَّ الْمُعْتَزِلَةَ يَقُولُونَ: لَا،",segs:[{ar:"لَكِنَّ الْمُعْتَزِلَةَ يَقُولُونَ:",uz:"Lekin mu’tazilalar deydilar:"},{ar:"لَا،",uz:"yo‘q,"}],full_uz:"Lekin mu’tazilalar: «Yo‘q,",note:null},
{num:138,time:"00:10:29,239 --> 00:10:31,199",arabic:"الْقُرْآنُ شَيْءٌ مَخْلُوقٌ،",segs:null,full_uz:"Qur’on yaratilgan narsadir», deydilar,",note:"مَخْلُوقٌ — yaratilgan; خَلَقَ fe’lining ism maf’ul shakli."},
{num:139,time:"00:10:31,199 --> 00:10:34,479",arabic:"قَاصِدِينَ مِنْ وَرَاءِ ذَلِكَ نَفْيَ الْعِصْمَةِ عَنْهُ.",segs:[{ar:"قَاصِدِينَ مِنْ وَرَاءِ ذَلِكَ",uz:"Bu orqali maqsad qilib"},{ar:"نَفْيَ الْعِصْمَةِ عَنْهُ.",uz:"uning xatodan xoliligini inkor etishni."}],full_uz:"Bu orqali uning xatodan xoliligini inkor etishni maqsad qiladilar.",note:"قَاصِدِينَ — maqsad qilgan holda, hol vazifasida. الْعِصْمَةُ — xatodan saqlanganlik."},
{num:140,time:"00:10:36,439 --> 00:10:40,159",arabic:"احْذَرْ هَؤُلَاءِ الْقَوْمَ أَنْ يُلَبِّسُوا عَلَيْكَ دِينَكَ.",segs:[{ar:"احْذَرْ هَؤُلَاءِ الْقَوْمَ",uz:"Bu kishilardan ehtiyot bo‘l"},{ar:"أَنْ يُلَبِّسُوا عَلَيْكَ دِينَكَ.",uz:"diningni senga chalkashtirib ko‘rsatishlaridan."}],full_uz:"Bu kishilar diningni senga chalkashtirib ko‘rsatishlaridan ehtiyot bo‘l.",note:"لَبَّسَ عَلَيْهِ الْأَمْرَ — unga ishni chalkashtirib ko‘rsatmoq. لَبِسَ — kiymoq fe’lidan farq qiladi."},
{num:141,time:"00:10:40,159 --> 00:10:43,919",arabic:"فَالدِّينُ لَا يُؤْخَذُ بِرَأْيِ ابْنِ الْأَشْرَسِ وَلَا الْمَرِيسِيِّ.",segs:[{ar:"فَالدِّينُ لَا يُؤْخَذُ",uz:"Chunki din olinmaydi"},{ar:"بِرَأْيِ ابْنِ الْأَشْرَسِ",uz:"Ibn Ashrasning fikriga ko‘ra"},{ar:"وَلَا الْمَرِيسِيِّ.",uz:"Marisiyning fikriga ko‘ra ham."}],full_uz:"Chunki din Ibn Ashras yoki Marisiyning fikriga ko‘ra olinmaydi.",note:"يُؤْخَذُ — olinadi; majhul nisbat."},
{num:142,time:"00:10:43,919 --> 00:10:48,679",arabic:"صُهَيْبٌ أَخْبَرَكَ؟",segs:null,full_uz:"Sizga Suhayb aytdimi?",note:null},
{num:143,time:"00:10:48,679 --> 00:10:49,959",arabic:"لَا يَهُمُّ مَنْ أَخْبَرَنِي.",segs:null,full_uz:"Menga kim aytgani muhim emas.",note:"لَا يَهُمُّ — muhim emas, ahamiyati yo‘q."},
{num:144,time:"00:10:49,959 --> 00:10:51,459",arabic:"وَاحْذَرِ الْمَاحِقَةَ،",segs:null,full_uz:"Halokatga olib boruvchi narsadan ehtiyot bo‘l,",note:"الْمَاحِقَةُ — yo‘q qiluvchi, halokatga olib boruvchi narsa."},
{num:145,time:"00:10:51,459 --> 00:10:53,739",arabic:"فَإِنَّ شَرَّ الْأُمُورِ مُحْدَثَاتُهَا،",segs:[{ar:"فَإِنَّ شَرَّ الْأُمُورِ",uz:"Chunki ishlarning eng yomoni"},{ar:"مُحْدَثَاتُهَا،",uz:"ularning yangidan kiritilganlaridir,"}],full_uz:"Chunki ishlarning eng yomoni yangidan kiritilganlaridir,",note:"مُحْدَثَاتٌ — keyin paydo qilingan narsalar; bu yerda dinga kiritilgan yangiliklar nazarda tutilgan."},
{num:146,time:"00:10:53,740 --> 00:10:55,580",arabic:"وَكُلُّ مُحْدَثَةٍ بِدْعَةٌ،",segs:null,full_uz:"Har bir yangidan kiritilgan narsa bid’atdir,",note:null},
{num:147,time:"00:10:55,580 --> 00:10:57,340",arabic:"وَكُلُّ بِدْعَةٍ ضَلَالَةٌ،",segs:null,full_uz:"Har bir bid’at adashishdir,",note:"ضَلَالَةٌ — to‘g‘ri yo‘ldan adashish."},
{num:148,time:"00:10:57,340 --> 00:10:58,940",arabic:"وَكُلُّ ضَلَالَةٍ فِي النَّارِ.",segs:null,full_uz:"Har bir adashish do‘zaxdadir.",note:null},
{num:149,time:"00:10:58,940 --> 00:11:01,240",arabic:"فَالنَّجَاةَ النَّجَاةَ، وَالْحَذَرَ الْحَذَرَ!",segs:[{ar:"فَالنَّجَاةَ النَّجَاةَ،",uz:"Najotga intil, najotga!"},{ar:"وَالْحَذَرَ الْحَذَرَ!",uz:"Ehtiyot bo‘l, ehtiyot!"}],full_uz:"Najotga intil, najotga! Ehtiyot bo‘l, ehtiyot!",note:"Otlarning takrorlanishi kuchli undash va ogohlantirishni bildiradi."},
{num:150,time:"00:11:01,240 --> 00:11:02,279",arabic:"اسْمَعْ يَا ابْنَ حَنْبَلٍ،",segs:[{ar:"اسْمَعْ",uz:"Eshiting"},{ar:"يَا ابْنَ حَنْبَلٍ،",uz:"Ibn Hanbal,"}],full_uz:"Eshiting, Ibn Hanbal,",note:null},
{num:151,time:"00:11:02,279 --> 00:11:07,259",arabic:"أَمَّا مَا أَعْتَقِدُهُ فَذَلِكَ أَمْرٌ يَخُصُّنِي،",segs:[{ar:"أَمَّا مَا أَعْتَقِدُهُ",uz:"Men ishongan narsaga kelsak"},{ar:"فَذَلِكَ أَمْرٌ يَخُصُّنِي،",uz:"bu o‘zimga tegishli ish,"}],full_uz:"E’tiqodimga kelsak, bu o‘zimga tegishli ish,",note:"يَخُصُّنِي — menga tegishli, menga taalluqli."},
{num:152,time:"00:11:07,259 --> 00:11:09,379",arabic:"لَا شَأْنَ لَكَ وَلِغَيْرِكَ بِهِ.",segs:[{ar:"لَا شَأْنَ لَكَ وَلِغَيْرِكَ",uz:"Sizning ham, boshqalarning ham aloqasi yo‘q"},{ar:"بِهِ.",uz:"bunga."}],full_uz:"Bunga sizning ham, boshqalarning ham aloqasi yo‘q.",note:"لَا شَأْنَ لَكَ بِـ — bu sening ishing emas, bunga aloqang yo‘q."},
{num:153,time:"00:11:09,379 --> 00:11:13,560",arabic:"وَأَمَّا مَا قُلْتَهُ عَنِ الشَّيْخِ بِشْرٍ وَثُمَامَةَ بْنِ الْأَشْرَسِ،",segs:[{ar:"وَأَمَّا مَا قُلْتَهُ",uz:"Aytganlaringizga kelsak"},{ar:"عَنِ الشَّيْخِ بِشْرٍ",uz:"shayx Bishr haqida"},{ar:"وَثُمَامَةَ بْنِ الْأَشْرَسِ،",uz:"va Sumoma ibn Ashras haqida,"}],full_uz:"Shayx Bishr va Sumoma ibn Ashras haqida aytganlaringizga kelsak,",note:null},
{num:154,time:"00:11:13,560 --> 00:11:16,320",arabic:"فَذَلِكَ مَا يَجِبُ أَنْ تَسْتَغْفِرَ اللَّهَ مِنْهُ.",segs:[{ar:"فَذَلِكَ مَا يَجِبُ",uz:"bu shunday narsaki, kerak"},{ar:"أَنْ تَسْتَغْفِرَ اللَّهَ مِنْهُ.",uz:"uning uchun Allohdan mag‘firat so‘rashingiz."}],full_uz:"Buning uchun Allohdan mag‘firat so‘rashingiz kerak.",note:"اسْتَغْفَرَ اللَّهَ مِنْ ذَنْبٍ — bir gunohi uchun Allohdan kechirim so‘ramoq."},
{num:155,time:"00:11:16,320 --> 00:11:19,700",arabic:"فَأَنْتَ لَمْ تَبْلُغْ مِنَ الْعِلْمِ مَا بَلَغَهُ الرَّجُلَانِ،",segs:[{ar:"فَأَنْتَ لَمْ تَبْلُغْ مِنَ الْعِلْمِ",uz:"Siz ilmda yetmagansiz"},{ar:"مَا بَلَغَهُ الرَّجُلَانِ،",uz:"u ikki kishi yetgan darajaga,"}],full_uz:"Siz ilmda u ikki kishi yetgan darajaga yetmagansiz,",note:"الرَّجُلَانِ — ikki kishi; ikkilikning bosh kelishik shakli."},
{num:156,time:"00:11:19,700 --> 00:11:24,680",arabic:"وَمِثْلِي وَمِثْلُكَ لَا يُدَانِيهِمَا فِي الْعِلْمِ مَنْزِلَةً حَتَّى يَخُوضَ فِي عِلْمِهِمَا.",segs:[{ar:"وَمِثْلِي وَمِثْلُكَ",uz:"Men va sizga o‘xshagan kishi"},{ar:"لَا يُدَانِيهِمَا فِي الْعِلْمِ مَنْزِلَةً",uz:"ilm darajasida ularga yaqin ham kelmaydi"},{ar:"حَتَّى يَخُوضَ فِي عِلْمِهِمَا.",uz:"ularning ilmi haqida bahs yurita oladigan darajada."}],full_uz:"Men va sizga o‘xshagan kishi ularning ilmi haqida bahs yuritish uchun ilm darajasida ularga yaqin ham kelmaydi.",note:"دَانَى — yaqinlashmoq, tenglashishga yaqin kelmoq. مَنْزِلَةً qaysi jihatdan yaqinlashishni aniqlashtiradi."},
{num:157,time:"00:11:24,680 --> 00:11:30,900",arabic:"إِنَّ مَا تَعِيبُونَهُ عَلَى هَؤُلَاءِ لَا يَعْدُو تَرْدِيدَ أَقْوَالِ الْمُغْرِضِينَ فِيهِمْ.",segs:[{ar:"إِنَّ مَا تَعِيبُونَهُ عَلَى هَؤُلَاءِ",uz:"Bu kishilarda ayb deb ko‘rsatayotganlaringiz"},{ar:"لَا يَعْدُو تَرْدِيدَ",uz:"takrorlashdan nariga o‘tmaydi"},{ar:"أَقْوَالِ الْمُغْرِضِينَ فِيهِمْ.",uz:"ular haqidagi g‘arazli kishilarning gaplarini."}],full_uz:"Bu kishilarda ayb deb ko‘rsatayotganlaringiz ular haqidagi g‘arazli gaplarni takrorlashdan nariga o‘tmaydi.",note:"لَا يَعْدُو — ...dan nariga o‘tmaydi. مُغْرِضٌ — g‘arazli maqsadi bor kishi."},
{num:158,time:"00:11:30,900 --> 00:11:36,340",arabic:"وَيَكْفِي أَنْ يَكُونَ فِيهِمْ خِيَرَةُ الرِّجَالِ حَتَّى تَعْلَمَ أَنَّهُمْ عَلَى الْحَقِّ،",segs:[{ar:"وَيَكْفِي أَنْ يَكُونَ فِيهِمْ",uz:"Ular orasida bo‘lishining o‘zi yetarli"},{ar:"خِيَرَةُ الرِّجَالِ",uz:"eng yaxshi kishilarning"},{ar:"حَتَّى تَعْلَمَ",uz:"bilishingiz uchun"},{ar:"أَنَّهُمْ عَلَى الْحَقِّ،",uz:"ular haq yo‘lda ekanini,"}],full_uz:"Ularning haq yo‘lda ekanini bilishingiz uchun oralarida eng yaxshi kishilar borligining o‘zi yetarli,",note:"خِيَرَةُ الرِّجَالِ — kishilarning eng yaxshilari, saralari."},
{num:159,time:"00:11:36,340 --> 00:11:43,580",arabic:"وَأَنَّ مَنْ عَدَاهُمْ هُوَ مَنْ يَجِبُ أَنْ يُرَاجِعَ نَفْسَهُ وَيَؤُوبَ إِلَى رُشْدِهِ بَعْدَ غَيِّهِ وَضَلَالِهِ.",segs:[{ar:"وَأَنَّ مَنْ عَدَاهُمْ",uz:"va ulardan boshqalar"},{ar:"هُوَ مَنْ يَجِبُ أَنْ يُرَاجِعَ نَفْسَهُ",uz:"o‘zini qayta ko‘rib chiqishi kerak bo‘lgan kishidir"},{ar:"وَيَؤُوبَ إِلَى رُشْدِهِ",uz:"va to‘g‘ri yo‘liga qaytishi"},{ar:"بَعْدَ غَيِّهِ وَضَلَالِهِ.",uz:"og‘ish va adashishidan keyin."}],full_uz:"Ulardan boshqalar esa o‘zini qayta ko‘rib chiqib, og‘ish va adashishidan keyin to‘g‘ri yo‘lga qaytishi kerakligini ham.",note:"آبَ يَؤُوبُ — qaytmoq. رُشْدٌ — to‘g‘ri yo‘l, oqilona yo‘l tutish."},
{num:160,time:"00:11:43,580 --> 00:11:46,800",arabic:"لَقَدْ جَاوَزْتَ الْحَدَّ يَا بَدْرُ، جَاوَزْتَهُ كَثِيرًا.",segs:[{ar:"لَقَدْ جَاوَزْتَ الْحَدَّ",uz:"Haddingdan oshding"},{ar:"يَا بَدْرُ،",uz:"Badr,"},{ar:"جَاوَزْتَهُ كَثِيرًا.",uz:"juda oshding."}],full_uz:"Haddingdan oshding, Badr, juda oshding.",note:"جَاوَزَ الْحَدَّ — haddidan oshmoq, chegaradan o‘tmoq."},
{num:161,time:"00:11:46,799 --> 00:11:49,559",arabic:"فَأَبُو عَبْدِ اللَّهِ لَمْ يَقْصِدْ لَكَ إِلَّا النُّصْحَ،",segs:[{ar:"فَأَبُو عَبْدِ اللَّهِ لَمْ يَقْصِدْ لَكَ",uz:"Abu Abdulloh senga niyat qilmagan"},{ar:"إِلَّا النُّصْحَ،",uz:"faqat nasihatdan boshqasini,"}],full_uz:"Abu Abdulloh senga faqat nasihat qilishni niyat qilgan edi,",note:"لَمْ ... إِلَّا — faqat ...qildi, boshqa narsani qilmadi."},
{num:162,time:"00:11:49,559 --> 00:11:53,879",arabic:"وَلَمْ يَدْفَعْهُ إِلَى ذَلِكَ إِلَّا الْحُبُّ لَكَ وَالْحِرْصُ عَلَيْكَ.",segs:[{ar:"وَلَمْ يَدْفَعْهُ إِلَى ذَلِكَ",uz:"Uni bunga undagan emas"},{ar:"إِلَّا الْحُبُّ لَكَ",uz:"senga bo‘lgan muhabbatdan boshqa narsa"},{ar:"وَالْحِرْصُ عَلَيْكَ.",uz:"va senga g‘amxo‘rlikdan."}],full_uz:"Uni bunga faqat senga bo‘lgan muhabbat va g‘amxo‘rlik undagan.",note:"دَفَعَهُ إِلَى — uni biror ishga undadi. الْحِرْصُ عَلَيْكَ — sening yaxshiligingni astoydil istash."},
{num:163,time:"00:11:53,879 --> 00:11:57,120",arabic:"أَمَّا مَا قُلْتَهُ عَنِ الْمُعْتَزِلَةِ أَنَّ فِيهِمْ خِيَرَةَ الرِّجَالِ،",segs:[{ar:"أَمَّا مَا قُلْتَهُ عَنِ الْمُعْتَزِلَةِ",uz:"Mu’tazilalar haqida aytganingga kelsak"},{ar:"أَنَّ فِيهِمْ خِيَرَةَ الرِّجَالِ،",uz:"ular orasida eng yaxshi kishilar bor deb,"}],full_uz:"Mu’tazilalar orasida eng yaxshi kishilar bor degan gapingga kelsak,",note:null},
{num:164,time:"00:11:57,120 --> 00:12:00,139",arabic:"فَلَا أَظُنُّ أَنَّكَ أَصَبْتَ كَبِدَ الْحَقِيقَةِ فِي هَذَا.",segs:[{ar:"فَلَا أَظُنُّ أَنَّكَ",uz:"O‘ylamaymanki, sen"},{ar:"أَصَبْتَ كَبِدَ الْحَقِيقَةِ",uz:"haqiqatning aynan o‘zini topding"},{ar:"فِي هَذَا.",uz:"bu masalada."}],full_uz:"Bu masalada aynan haqiqatni aytding deb o‘ylamayman.",note:"أَصَابَ كَبِدَ الْحَقِيقَةِ — haqiqatning aynan o‘zini topmoq, gapning to‘g‘risini aytmoq."},
{num:165,time:"00:12:00,139 --> 00:12:04,459",arabic:"فَلَا أَعْرِفُ مِنْهُمْ رَجُلًا وَاحِدًا يُعْتَدُّ بِهِ وَيُعَوَّلُ عَلَيْهِ.",segs:[{ar:"فَلَا أَعْرِفُ مِنْهُمْ رَجُلًا وَاحِدًا",uz:"Ular orasidan biror kishini bilmayman"},{ar:"يُعْتَدُّ بِهِ",uz:"e’tiborga olinadigan"},{ar:"وَيُعَوَّلُ عَلَيْهِ.",uz:"va unga tayaniladigan."}],full_uz:"Ular orasida e’tiborga olinadigan va tayanish mumkin bo‘lgan biror kishini bilmayman.",note:"يُعْتَدُّ بِهِ — e’tiborga olinadi; يُعَوَّلُ عَلَيْهِ — unga tayaniladi. Ikkalasi ham majhul nisbat."},
{num:166,time:"00:12:04,459 --> 00:12:11,599",arabic:"أَلَسْتَ أَنْتَ يَا ابْنَ نُوحٍ مَنْ قَالَ إِنَّ ابْنَ أَبِي دُؤَادٍ عَلَى اطِّلَاعٍ وَاسِعٍ يَسْتَحِقُّ الثَّنَاءَ؟",segs:[{ar:"أَلَسْتَ أَنْتَ يَا ابْنَ نُوحٍ",uz:"Siz emasmidingiz, Ibn Nuh"},{ar:"مَنْ قَالَ",uz:"aytgan kishi"},{ar:"إِنَّ ابْنَ أَبِي دُؤَادٍ عَلَى اطِّلَاعٍ وَاسِعٍ",uz:"Ibn Abu Duod keng bilimga ega deb"},{ar:"يَسْتَحِقُّ الثَّنَاءَ؟",uz:"maqtovga loyiq deb?"}],full_uz:"Ibn Nuh, Ibn Abu Duod keng bilimga ega va maqtovga loyiq degan o‘zingiz emasmidingiz?",note:"عَلَى اطِّلَاعٍ وَاسِعٍ — ko‘p narsadan xabardor, keng bilimga ega."},
{num:167,time:"00:12:11,599 --> 00:12:13,299",arabic:"كَأَنَّكَ تُنَاقِضُ نَفْسَكَ الْآنَ.",segs:[{ar:"كَأَنَّكَ تُنَاقِضُ نَفْسَكَ",uz:"O‘zingizga qarshi gapirayotganga o‘xshaysiz"},{ar:"الْآنَ.",uz:"hozir."}],full_uz:"Hozir o‘z gapingizga o‘zingiz qarshi chiqayotganga o‘xshaysiz.",note:"نَاقَضَ نَفْسَهُ — o‘z gapiga o‘zi zid gapirmoq."},
{num:168,time:"00:12:13,299 --> 00:12:16,599",arabic:"وَمَا شَأْنُ ابْنِ أَبِي دُؤَادٍ بِحَدِيثِنَا؟",segs:[{ar:"وَمَا شَأْنُ ابْنِ أَبِي دُؤَادٍ",uz:"Ibn Abu Duodning nima aloqasi bor"},{ar:"بِحَدِيثِنَا؟",uz:"suhbatimizga?"}],full_uz:"Ibn Abu Duodning suhbatimizga nima aloqasi bor?",note:"مَا شَأْنُ... بِـ؟ — ...ning bunga nima aloqasi bor?"},
{num:169,time:"00:12:16,799 --> 00:12:29,179",arabic:"مَنْ ابْنُ أَبِي دُؤَادٍ هَذَا؟",segs:null,full_uz:"Bu Ibn Abu Duod kim?",note:null},
{num:170,time:"00:12:30,099 --> 00:12:32,799",arabic:"هُوَ رَجُلٌ اسْتَأْجَرَ دَارِي مُنْذُ مُدَّةٍ.",segs:[{ar:"هُوَ رَجُلٌ اسْتَأْجَرَ دَارِي",uz:"U uyimni ijaraga olgan kishi"},{ar:"مُنْذُ مُدَّةٍ.",uz:"bir muddat oldin."}],full_uz:"U bir muddat oldin uyimni ijaraga olgan kishi.",note:"اسْتَأْجَرَ — ijaraga olmoq; أَجَّرَ — ijaraga bermoq."},
{num:171,time:"00:12:32,799 --> 00:12:35,039",arabic:"وَكُنْتُ قَدْ عَرَّفْتُهُ عَلَى بَدْرٍ.",segs:null,full_uz:"Uni Badr bilan tanishtirgan edim.",note:"عَرَّفَهُ عَلَى فُلَانٍ — uni falonchi bilan tanishtirmoq."},
{num:172,time:"00:12:35,039 --> 00:12:39,519",arabic:"وَلَكِنَّهُ كَانَ يَقْصِدُ أَنَّ هَذَا الرَّجُلَ مِنَ الْمُعْتَزِلَةِ، أَلَمْ تَرَ؟",segs:[{ar:"وَلَكِنَّهُ كَانَ يَقْصِدُ",uz:"Lekin u nazarda tutayotgan edi"},{ar:"أَنَّ هَذَا الرَّجُلَ مِنَ الْمُعْتَزِلَةِ،",uz:"bu kishi mu’tazilalardan ekanini,"},{ar:"أَلَمْ تَرَ؟",uz:"payqamadingizmi?"}],full_uz:"Lekin u bu kishining mu’tazilalardan ekanini nazarda tutayotgan edi, payqamadingizmi?",note:"أَلَمْ تَرَ؟ — ko‘rmadingizmi?; bu yerda anglamadingizmi, payqamadingizmi ma’nosida."},
{num:173,time:"00:12:39,519 --> 00:12:43,139",arabic:"فَهِمْتُ مَا كَانَ يَقْصِدُ يَا ابْنَ حَنْبَلٍ.",segs:[{ar:"فَهِمْتُ مَا كَانَ يَقْصِدُ",uz:"U nimani nazarda tutganini tushundim"},{ar:"يَا ابْنَ حَنْبَلٍ.",uz:"Ibn Hanbal."}],full_uz:"U nimani nazarda tutganini tushundim, Ibn Hanbal.",note:null},
{num:174,time:"00:12:43,139 --> 00:12:44,939",arabic:"فَهِمْتُ مَا كَانَ يَقْصِدُ.",segs:[{ar:"فَهِمْتُ",uz:"Tushundim"},{ar:"مَا كَانَ يَقْصِدُ.",uz:"u nimani nazarda tutganini."}],full_uz:"U nimani nazarda tutganini tushundim.",note:null},
{num:175,time:"00:12:44,940 --> 00:13:00,280",arabic:"تَفَضَّلِي.",segs:null,full_uz:"Marhamat.",note:"تَفَضَّلِي — ayol kishiga murojaat; erkakka تَفَضَّلْ deyiladi."},
{num:176,time:"00:13:00,280 --> 00:13:08,140",arabic:"أَتُرِيدِينَ شَيْئًا آخَرَ يَا أُخْتِي؟",segs:[{ar:"أَتُرِيدِينَ شَيْئًا آخَرَ",uz:"Yana biror narsa xohlaysizmi"},{ar:"يَا أُخْتِي؟",uz:"opa-singlim?"}],full_uz:"Yana biror narsa xohlaysizmi, opa-singlim?",note:"أُخْتِي — mening opam yoki singlim; so‘zning o‘zi yosh farqini bildirmaydi."},
{num:177,time:"00:13:09,780 --> 00:13:13,600",arabic:"مُنْذُ أَنْ حَدَّثْتَنِي عَنْ تِلْكَ الْجَارِيَةِ،",segs:[{ar:"مُنْذُ أَنْ حَدَّثْتَنِي",uz:"Menga gapirib berganingdan beri"},{ar:"عَنْ تِلْكَ الْجَارِيَةِ،",uz:"o‘sha joriya haqida,"}],full_uz:"Menga o‘sha joriya haqida gapirib berganingdan beri,",note:"مُنْذُ أَنْ — ...ganidan beri."},
{num:178,time:"00:13:14,940 --> 00:13:16,320",arabic:"وَأَنْتَ عَلَى هَذِهِ الْحَالِ.",segs:null,full_uz:"Shu ahvoldasan.",note:"عَلَى هَذِهِ الْحَالِ — shu holatda, shu ahvolda."},
{num:179,time:"00:13:16,320 --> 00:13:19,000",arabic:"مَا خَطْبُكَ؟",segs:null,full_uz:"Senga nima bo‘ldi?",note:"مَا خَطْبُكَ؟ — nima bo‘ldi, seni nima bezovta qilyapti?"},
{num:180,time:"00:13:19,000 --> 00:13:20,400",arabic:"لَا شَيْءَ.",segs:null,full_uz:"Hech narsa.",note:null},
{num:181,time:"00:13:20,400 --> 00:13:22,960",arabic:"غَايَةُ مَا فِي الْأَمْرِ أَنِّي لَمَسْتُ فِي كَلَامِهَا صِدْقًا،",segs:[{ar:"غَايَةُ مَا فِي الْأَمْرِ",uz:"Bor gap shuki"},{ar:"أَنِّي لَمَسْتُ فِي كَلَامِهَا",uz:"uning gaplarida sezdim"},{ar:"صِدْقًا،",uz:"rostlikni,"}],full_uz:"Bor gap shuki, uning gaplarida rostlikni sezdim,",note:"لَمَسَ — tegmoq; bu yerda sezmoq, payqamoq. غَايَةُ مَا فِي الْأَمْرِ — bor gap shuki."},
{num:182,time:"00:13:22,960 --> 00:13:25,080",arabic:"وَظُلْمًا أَيْضًا.",segs:null,full_uz:"Zulmni ham.",note:"Oldingi gapga bog‘lanib, unga zulm qilinganini ham sezganini bildiradi."},
{num:183,time:"00:13:25,080 --> 00:13:27,340",arabic:"وَرُبَّمَا تَعَاطَفْتُ مَعَهَا حِينَهَا.",segs:[{ar:"وَرُبَّمَا تَعَاطَفْتُ مَعَهَا",uz:"Balki unga hamdard bo‘lgandirman"},{ar:"حِينَهَا.",uz:"o‘shanda."}],full_uz:"Balki o‘shanda unga hamdard bo‘lgandirman.",note:"تَعَاطَفَ مَعَ — birovga hamdard bo‘lmoq."},
{num:184,time:"00:13:27,340 --> 00:13:28,920",arabic:"هَذَا كُلُّ مَا فِي الْأَمْرِ.",segs:null,full_uz:"Bor gap shu.",note:"هَذَا كُلُّ مَا فِي الْأَمْرِ — hamma gap shu, boshqa hech narsa yo‘q."},
{num:185,time:"00:13:28,920 --> 00:13:34,020",arabic:"وَلَكِنَّ لِسَانَ حَالِكَ يَقُولُ غَيْرَ ذَلِكَ.",segs:[{ar:"وَلَكِنَّ لِسَانَ حَالِكَ",uz:"Lekin sening holating"},{ar:"يَقُولُ غَيْرَ ذَلِكَ.",uz:"boshqa narsani aytyapti."}],full_uz:"Lekin holating boshqa narsani aytyapti.",note:"لِسَانُ الْحَالِ — holat tili; kishining gapirmasdan ham holati orqali bildirayotgan ma’nosi."},
{num:186,time:"00:13:34,020 --> 00:13:39,120",arabic:"أَنَا إِنْ كُنْتُ أُرِيدُهَا أَنْ تَأْتِيَ إِلَى هَذَا الْبَيْتِ فَلِأَجْلِكِ فَحَسْبُ،",segs:[{ar:"أَنَا إِنْ كُنْتُ أُرِيدُهَا",uz:"Agar men uning istayotgan bo‘lsam"},{ar:"أَنْ تَأْتِيَ إِلَى هَذَا الْبَيْتِ",uz:"bu uyga kelishini"},{ar:"فَلِأَجْلِكِ فَحَسْبُ،",uz:"faqat siz uchun,"}],full_uz:"Agar uning bu uyga kelishini istayotgan bo‘lsam, bu faqat siz uchun,",note:"فَحَسْبُ — xolos, faqat shuning o‘zi."},
{num:187,time:"00:13:39,120 --> 00:13:40,940",arabic:"لِتَقُومَ عَلَى خِدْمَتِكِ.",segs:null,full_uz:"Sizning xizmatingizni qilishi uchun.",note:"قَامَ عَلَى خِدْمَتِهِ — uning xizmati va parvarishini zimmasiga oldi."},
{num:188,time:"00:13:41,760 --> 00:13:44,180",arabic:"وَمَا دُمْتِ لَا تُرِيدِينَهَا فَالْأَمْرُ قَدِ انْتَهَى.",segs:[{ar:"وَمَا دُمْتِ لَا تُرِيدِينَهَا",uz:"Modomiki uni istamas ekansiz"},{ar:"فَالْأَمْرُ قَدِ انْتَهَى.",uz:"masala tugadi."}],full_uz:"Modomiki uni istamas ekansiz, masala tugadi.",note:"مَا دُمْتِ — modomiki sen; ayol kishiga murojaat shakli."},
{num:189,time:"00:13:44,940 --> 00:13:45,660",arabic:"أَبْحَثُ عَنْ غَيْرِهَا.",segs:null,full_uz:"Boshqasini izlayman.",note:"غَيْرِهَا — undan boshqasini; ayol kishiga ishora qiladi."},
{num:190,time:"00:13:45,660 --> 00:13:48,760",arabic:"أَنَا لَمْ أَقُلْ لَكَ إِنِّي لَا أُرِيدُهَا.",segs:[{ar:"أَنَا لَمْ أَقُلْ لَكَ",uz:"Men senga aytmadim"},{ar:"إِنِّي لَا أُرِيدُهَا.",uz:"uni istamayman deb."}],full_uz:"Men senga uni istamayman demadim.",note:"لَمْ أَقُلْ — aytmadim; jazmda أَقُولُ fe’lining o‘rtasidagi و tushadi."},
{num:191,time:"00:13:48,760 --> 00:13:54,120",arabic:"وَلَكِنِّي أَشْعُرُ أَنَّ وَرَاءَ هَذِهِ الْفَتَاةِ مَا وَرَاءَهَا،",segs:[{ar:"وَلَكِنِّي أَشْعُرُ",uz:"Lekin sezyapmanki"},{ar:"أَنَّ وَرَاءَ هَذِهِ الْفَتَاةِ",uz:"bu qizning ortida"},{ar:"مَا وَرَاءَهَا،",uz:"qandaydir yashirin gaplar bor,"}],full_uz:"Lekin bu qizning ortida qandaydir yashirin gaplar borligini sezyapman,",note:"وَرَاءَهَا مَا وَرَاءَهَا — ortida aytilmagan voqealar yoki sirlar borligini bildiruvchi ifoda."},
{num:192,time:"00:13:54,120 --> 00:13:56,940",arabic:"وَقَدْ تَجُرُّ عَلَيْنَا مَا نَكْرَهُ،",segs:[{ar:"وَقَدْ تَجُرُّ عَلَيْنَا",uz:"Boshimizga olib kelishi mumkin"},{ar:"مَا نَكْرَهُ،",uz:"biz yoqtirmaydigan narsani,"}],full_uz:"U boshimizga ko‘ngilsizliklar olib kelishi mumkin,",note:"جَرَّ عَلَيْهِ — boshiga biror oqibat yoki tashvish keltirmoq."},
{num:193,time:"00:13:56,940 --> 00:13:59,380",arabic:"وَمَا لَا تُحْمَدُ عَاقِبَتُهُ.",segs:null,full_uz:"Va oqibati yaxshi bo‘lmagan ishlarni.",note:"لَا تُحْمَدُ عَاقِبَتُهُ — oqibati maqtovga loyiq emas, yomon tugaydi."},
{num:194,time:"00:13:59,380 --> 00:14:03,620",arabic:"الْحَقُّ فِيمَا قُلْتِ يَا ابْنَةَ أَبِي.",segs:[{ar:"الْحَقُّ فِيمَا قُلْتِ",uz:"Aytganingiz to‘g‘ri"},{ar:"يَا ابْنَةَ أَبِي.",uz:"ey otamning qizi."}],full_uz:"Aytganingiz to‘g‘ri, ey otamning qizi.",note:"يَا ابْنَةَ أَبِي — opa-singilga qarindoshlikni ta’kidlab qilingan murojaat."},
{num:195,time:"00:14:03,620 --> 00:14:07,120",arabic:"الْأَوْلَى أَنْ نَقْطَعَ عَلَى الْمُشْكِلَاتِ طَرِيقَهَا إِلَى دَارِنَا.",segs:[{ar:"الْأَوْلَى أَنْ نَقْطَعَ",uz:"Yaxshisi, to‘sishimiz kerak"},{ar:"عَلَى الْمُشْكِلَاتِ طَرِيقَهَا",uz:"muammolarning yo‘lini"},{ar:"إِلَى دَارِنَا.",uz:"uyimizga keladigan."}],full_uz:"Yaxshisi, muammolarning uyimizga kelish yo‘lini to‘saylik.",note:"قَطَعَ عَلَيْهِ الطَّرِيقَ — uning yo‘lini to‘smoq. الْأَوْلَى — ma’qulrog‘i, yaxshirog‘i."},
{num:196,time:"00:14:07,120 --> 00:14:10,580",arabic:"جَزَاكَ اللَّهُ خَيْرًا يَا أَخِي.",segs:[{ar:"جَزَاكَ اللَّهُ خَيْرًا",uz:"Alloh seni yaxshilik bilan mukofotlasin"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Alloh seni yaxshilik bilan mukofotlasin, birodarim.",note:null},
{num:197,time:"00:14:14,940 --> 00:14:23,620",arabic:"أَعُوذُ بِاللَّهِ مِنْ مَقْتِ اللَّهِ.",segs:[{ar:"أَعُوذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنْ مَقْتِ اللَّهِ.",uz:"Allohning qattiq g‘azabidan."}],full_uz:"Allohning qattiq g‘azabidan Allohning O‘zidan panoh so‘rayman.",note:"مَقْتٌ — kuchli nafrat, qattiq g‘azab."},
{num:198,time:"00:14:23,620 --> 00:14:27,220",arabic:"كَيْفَ عَرَفْتَ ذَلِكَ؟",segs:null,full_uz:"Buni qanday bildingiz?",note:null},
{num:199,time:"00:14:27,220 --> 00:14:29,820",arabic:"كُنَّا نُحَدِّثُ وَاحِدًا مِنَ الَّذِينَ أَغْوَاهُمُ الْمُعْتَزِلَةُ،",segs:[{ar:"كُنَّا نُحَدِّثُ وَاحِدًا",uz:"Bir kishi bilan gaplashayotgan edik"},{ar:"مِنَ الَّذِينَ أَغْوَاهُمُ الْمُعْتَزِلَةُ،",uz:"mu’tazilalar yo‘ldan ozdirganlardan,"}],full_uz:"Mu’tazilalar yo‘ldan ozdirgan kishilardan biri bilan gaplashayotgan edik,",note:"أَغْوَى — yo‘ldan ozdirmoq. كُنَّا نُحَدِّثُ — gaplashayotgan edik."},
{num:200,time:"00:14:29,820 --> 00:14:33,660",arabic:"فَأَخَذَهُ الْغَضَبُ مِنْ نُصْحِنَا وَأَشَارَ أَنَّهُ مُعْتَزِلِيٌّ.",segs:[{ar:"فَأَخَذَهُ الْغَضَبُ مِنْ نُصْحِنَا",uz:"Nasihatimizdan g‘azablandi"},{ar:"وَأَشَارَ أَنَّهُ مُعْتَزِلِيٌّ.",uz:"va uning mu’taziliy ekaniga ishora qildi."}],full_uz:"Nasihatimizdan g‘azablanib, uning mu’taziliy ekaniga ishora qildi.",note:"أَخَذَهُ الْغَضَبُ — uni g‘azab qamrab oldi. أَنَّهُ bu yerda gap ketayotgan uchinchi kishiga ishora qiladi."},
{num:201,time:"00:14:33,660 --> 00:14:36,020",arabic:"أَشَارَ إِلَيْكَ؟",segs:null,full_uz:"Sizga ishora qildimi?",note:"أَشَارَ إِلَى — ...ga ishora qilmoq."},
{num:202,time:"00:14:38,020 --> 00:14:41,260",arabic:"أَنَا أَرَى أَلَّا تَتَسَرَّعَ فِي طَرْدِ الرَّجُلِ،",segs:[{ar:"أَنَا أَرَى أَلَّا تَتَسَرَّعَ",uz:"Men shoshilmasligingizni ma’qul ko‘raman"},{ar:"فِي طَرْدِ الرَّجُلِ،",uz:"u kishini haydashda,"}],full_uz:"Menimcha, u kishini haydashga shoshilmang,",note:"تَسَرَّعَ فِي — bir ishda shoshqaloqlik qilmoq. طَرْدٌ — haydash."},
{num:203,time:"00:14:41,260 --> 00:14:43,920",arabic:"مَا لَمْ يَعْتَرِفْ بِنَفْسِهِ.",segs:null,full_uz:"O‘zi tan olmagunicha.",note:"مَا لَمْ — ...magunicha. بِنَفْسِهِ — uning o‘zi, shaxsan."},
{num:204,time:"00:14:43,919 --> 00:14:49,039",arabic:"لَا تَتَّهِمْهُ بِكَلِمَةٍ قَالَهَا رَجُلٌ فِي سَاعَةِ غَضَبٍ لِتَأْلِيبِكَ عَلَيْهِ.",segs:[{ar:"لَا تَتَّهِمْهُ بِكَلِمَةٍ",uz:"Uni bir gap bilan ayblamang"},{ar:"قَالَهَا رَجُلٌ",uz:"bir kishi aytgan"},{ar:"فِي سَاعَةِ غَضَبٍ",uz:"g‘azablangan paytida"},{ar:"لِتَأْلِيبِكَ عَلَيْهِ.",uz:"sizni unga qarshi qayrash uchun."}],full_uz:"Bir kishi g‘azab ustida sizni unga qarshi qayrash uchun aytgan gap bilan uni ayblamang.",note:"تَأْلِيبُ فُلَانٍ عَلَى فُلَانٍ — bir kishini boshqasiga qarshi qayrash."},
{num:205,time:"00:14:49,039 --> 00:14:51,240",arabic:"اسْتَعِذْ بِاللَّهِ مِنَ الشَّيْطَانِ.",segs:[{ar:"اسْتَعِذْ بِاللَّهِ",uz:"Allohdan panoh so‘rang"},{ar:"مِنَ الشَّيْطَانِ.",uz:"shaytondan."}],full_uz:"Shaytondan Allohning panohini so‘rang.",note:"اسْتَعِذْ — اسْتَعَاذَ يَسْتَعِيذُ fe’lining buyruq shakli."},
{num:206,time:"00:14:51,240 --> 00:14:57,240",arabic:"وَلَا تَرْكُضْ خَلْفَ الشُّبُهَاتِ حَتَّى تُقِيمَ الْبَيِّنَةَ وَتَأْتِيَ بِالدَّلِيلِ.",segs:[{ar:"وَلَا تَرْكُضْ خَلْفَ الشُّبُهَاتِ",uz:"Shubhalar ortidan yugurmang"},{ar:"حَتَّى تُقِيمَ الْبَيِّنَةَ",uz:"aniq isbotni keltirmaguningizcha"},{ar:"وَتَأْتِيَ بِالدَّلِيلِ.",uz:"va dalil olib kelmaguningizcha."}],full_uz:"Aniq isbot va dalil keltirmaguningizcha shubhalar ortidan yugurmang.",note:"أَقَامَ الْبَيِّنَةَ — isbot keltirdi. شُبُهَاتٌ — shubhali holatlar."},
{num:207,time:"00:14:57,240 --> 00:14:59,899",arabic:"أَنَا مُتَأَكِّدٌ مِنْ أَنَّهُ مِنَ الْمُعْتَزِلَةِ.",segs:[{ar:"أَنَا مُتَأَكِّدٌ",uz:"Ishonchim komil"},{ar:"مِنْ أَنَّهُ مِنَ الْمُعْتَزِلَةِ.",uz:"uning mu’tazilalardan ekaniga."}],full_uz:"Uning mu’tazilalardan ekaniga ishonchim komil.",note:"مُتَأَكِّدٌ مِنْ — ...ga ishonchi komil."},
{num:208,time:"00:14:59,899 --> 00:15:03,500",arabic:"وَلَنْ يَبْقَى فِي بَيْتِي مَنْ فَسَدَتْ عَقِيدَتُهُ وَزَاغَتْ أَفْكَارُهُ.",segs:[{ar:"وَلَنْ يَبْقَى فِي بَيْتِي",uz:"Uyimda qolmaydi"},{ar:"مَنْ فَسَدَتْ عَقِيدَتُهُ",uz:"aqidasi buzilgan kishi"},{ar:"وَزَاغَتْ أَفْكَارُهُ.",uz:"va fikrlari og‘ishgan."}],full_uz:"Aqidasi buzilgan, fikrlari og‘ishgan kishi uyimda qolmaydi.",note:"زَاغَ — og‘moq, to‘g‘ri yo‘ldan chetga chiqmoq."},
{num:209,time:"00:15:03,500 --> 00:15:08,360",arabic:"إِنْ كُنْتَ تَظُنُّ أَنَّ الرَّجُلَ مُعْتَزِلِيٌّ فَدَعْكَ مِنْهُ،",segs:[{ar:"إِنْ كُنْتَ تَظُنُّ",uz:"Agar o‘ylayotgan bo‘lsangiz"},{ar:"أَنَّ الرَّجُلَ مُعْتَزِلِيٌّ",uz:"u kishini mu’taziliy deb"},{ar:"فَدَعْكَ مِنْهُ،",uz:"uni o‘z holiga qo‘ying,"}],full_uz:"Agar u kishini mu’taziliy deb o‘ylayotgan bo‘lsangiz, uni o‘z holiga qo‘ying,",note:"دَعْكَ مِنْهُ — uni qo‘y, u bilan mashg‘ul bo‘lma."},
{num:210,time:"00:15:08,360 --> 00:15:12,699",arabic:"طَالَمَا أَنَّهُ لَمْ يُجَاهِرْ بِبِدْعَتِهِ وَلَمْ يَدْعُ النَّاسَ إِلَيْهَا.",segs:[{ar:"طَالَمَا أَنَّهُ لَمْ يُجَاهِرْ بِبِدْعَتِهِ",uz:"Modomiki bid’atini oshkor qilmagan ekan"},{ar:"وَلَمْ يَدْعُ النَّاسَ إِلَيْهَا.",uz:"va odamlarni unga da’vat qilmagan ekan."}],full_uz:"Modomiki u bid’atini oshkor qilmagan va odamlarni unga da’vat qilmagan ekan.",note:"لَمْ يَدْعُ — da’vat qilmadi; jazmda يَدْعُو fe’lining oxirgi و harfi tushadi."},
{num:211,time:"00:15:12,700 --> 00:15:16,820",arabic:"عَلَيْكَ بِهَجْرِهِ حَتَّى يَفْعَلَ اللَّهُ مَا يَشَاءُ،",segs:[{ar:"عَلَيْكَ بِهَجْرِهِ",uz:"Undan chetda turing"},{ar:"حَتَّى يَفْعَلَ اللَّهُ مَا يَشَاءُ،",uz:"Alloh O‘zi istaganini qilgunicha,"}],full_uz:"Alloh O‘zi istaganini qilgunicha undan chetda turing,",note:"عَلَيْكَ بِـ — ...ni tut, ...ga amal qil. هَجْرٌ — aloqani uzish, chetlashish."},
{num:212,time:"00:15:16,820 --> 00:15:19,300",arabic:"وَاسْتَبْرِئْ لِدِينِكَ.",segs:null,full_uz:"Diningizni shubhalardan asrang.",note:"اسْتَبْرَأَ لِدِينِهِ — dinini shubhali narsalardan saqlashga intildi."},
{num:213,time:"00:15:19,300 --> 00:15:25,700",arabic:"مَا رَأْيُكَ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"مَا رَأْيُكَ",uz:"Fikringiz qanday"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"Abu Abdulloh?"}],full_uz:"Fikringiz qanday, Abu Abdulloh?",note:null},
{num:214,time:"00:15:26,860 --> 00:15:29,560",arabic:"أَنَا مَعَ مَا قَالَهُ ابْنُ مَعِينٍ.",segs:[{ar:"أَنَا مَعَ",uz:"Men qo‘shilaman"},{ar:"مَا قَالَهُ ابْنُ مَعِينٍ.",uz:"Ibn Ma’in aytgan gapga."}],full_uz:"Men Ibn Ma’inning gapiga qo‘shilaman.",note:"أَنَا مَعَ... — men ...tomondaman, ...fikriga qo‘shilaman."},
{num:215,time:"00:15:29,560 --> 00:15:34,020",arabic:"الشَّكُّ لَا يَزُولُ إِلَّا بِالْيَقِينِ.",segs:[{ar:"الشَّكُّ لَا يَزُولُ",uz:"Shubha yo‘qolmaydi"},{ar:"إِلَّا بِالْيَقِينِ.",uz:"faqat aniq ishonch bilangina."}],full_uz:"Shubha faqat aniq ishonch bilangina yo‘qoladi.",note:"زَالَ يَزُولُ — yo‘qolmoq, ketmoq. يَقِينٌ — qat’iy ishonch."},
{num:216,time:"00:15:36,460 --> 00:15:40,360",arabic:"لَا تَلِيقُ مَسَائِلُ عِلْمِ الْكَلَامِ بِهَذَا الْمَكَانِ.",segs:[{ar:"لَا تَلِيقُ مَسَائِلُ عِلْمِ الْكَلَامِ",uz:"Kalom ilmi masalalari mos emas"},{ar:"بِهَذَا الْمَكَانِ.",uz:"bu joyga."}],full_uz:"Kalom ilmi masalalarini muhokama qilish bu joyga mos emas.",note:"لَاقَ بِـ — ...ga munosib yoki mos bo‘lmoq."},
{num:217,time:"00:15:40,360 --> 00:15:44,639",arabic:"مَنْ كَانَ لَدَيْهِ سُؤَالٌ فِي شُؤُونِ حَيَاتِهِ فَلْيَسْأَلْ،",segs:[{ar:"مَنْ كَانَ لَدَيْهِ سُؤَالٌ",uz:"Kimning savoli bo‘lsa"},{ar:"فِي شُؤُونِ حَيَاتِهِ",uz:"hayotidagi ishlar haqida"},{ar:"فَلْيَسْأَلْ،",uz:"so‘rasin,"}],full_uz:"Kimning hayotidagi ishlar haqida savoli bo‘lsa, so‘rasin,",note:"فَلْيَسْأَلْ — so‘rasin; buyruq bildiruvchi لْ fe’lni jazm qiladi."},
{num:218,time:"00:15:44,639 --> 00:15:50,820",arabic:"وَلْيَتْرُكِ الْخَوْضَ فِي مَسَائِلِ الْقَدَرِيَّةِ وَالْجَبْرِيَّةِ وَالْمُعْتَزِلَةِ وَبِدَعِهِمْ.",segs:[{ar:"وَلْيَتْرُكِ الْخَوْضَ",uz:"Muhokamaga kirishishni tark etsin"},{ar:"فِي مَسَائِلِ الْقَدَرِيَّةِ وَالْجَبْرِيَّةِ",uz:"qadariya va jabariya masalalariga"},{ar:"وَالْمُعْتَزِلَةِ وَبِدَعِهِمْ.",uz:"mu’tazila va ularning bid’atlariga."}],full_uz:"Qadariya, jabariya, mu’tazila masalalari va ularning bid’atlarini muhokama qilishni tark etsin.",note:"الْخَوْضُ فِي — biror masala muhokamasiga kirishish."},
{num:219,time:"00:15:50,820 --> 00:15:54,060",arabic:"فَهَذِهِ لَهَا مَكَانُهَا الَّذِي تَسْتَحِقُّهُ.",segs:[{ar:"فَهَذِهِ لَهَا مَكَانُهَا",uz:"Bularning o‘z joyi bor"},{ar:"الَّذِي تَسْتَحِقُّهُ.",uz:"o‘zlariga munosib bo‘lgan."}],full_uz:"Bularning o‘zlariga munosib joyi bor.",note:"تَسْتَحِقُّهُ — unga loyiq, uni munosib ko‘radi."},
{num:220,time:"00:15:54,060 --> 00:15:57,800",arabic:"وَلَكِنَّهُمْ يَقُولُونَ إِنَّ الْقُرْآنَ مَخْلُوقٌ يَا شَيْخُ،",segs:[{ar:"وَلَكِنَّهُمْ يَقُولُونَ",uz:"Lekin ular aytishyapti"},{ar:"إِنَّ الْقُرْآنَ مَخْلُوقٌ",uz:"Qur’on yaratilgan deb"},{ar:"يَا شَيْخُ،",uz:"shayx,"}],full_uz:"Lekin ular Qur’on yaratilgan deyishyapti, shayx,",note:null},
{num:221,time:"00:15:57,800 --> 00:15:59,360",arabic:"فَبِمَاذَا تَرُدُّ عَلَيْهِمْ؟",segs:null,full_uz:"Ularga qanday javob berasiz?",note:"رَدَّ عَلَيْهِ — unga javob berdi, fikriga raddiya bildirdi."},
{num:222,time:"00:16:01,300 --> 00:16:03,340",arabic:"قُلْتُ: لَا جِدَالَ فِي هَذَا الْمَكَانِ.",segs:[{ar:"قُلْتُ:",uz:"Aytdim:"},{ar:"لَا جِدَالَ فِي هَذَا الْمَكَانِ.",uz:"bu joyda bahs yo‘q."}],full_uz:"Aytdim: bu joyda bahslashilmaydi.",note:"لَا جِدَالَ — bahs yo‘q; bu yerda bahsni taqiqlash ma’nosida."},
{num:223,time:"00:16:03,340 --> 00:16:08,639",arabic:"وَهَذَا السُّؤَالُ لَا يُطْرَحُ عَلَى الْمَلَإِ وَوَسَطَ الْعَامَّةِ يَا أَخِي،",segs:[{ar:"وَهَذَا السُّؤَالُ لَا يُطْرَحُ",uz:"Bu savol berilmaydi"},{ar:"عَلَى الْمَلَإِ",uz:"ko‘pchilik oldida"},{ar:"وَوَسَطَ الْعَامَّةِ",uz:"va oddiy odamlar orasida"},{ar:"يَا أَخِي،",uz:"birodarim,"}],full_uz:"Bu savol ko‘pchilik oldida, oddiy odamlar orasida berilmaydi, birodarim,",note:"عَلَى الْمَلَإِ — ko‘pchilik oldida, oshkora. يُطْرَحُ — ko‘tariladi, qo‘yiladi."},
{num:224,time:"00:16:08,639 --> 00:16:12,799",arabic:"لِأَنَّهُ سُؤَالٌ مُلْبِسٌ فِي ذَاتِهِ،",segs:[{ar:"لِأَنَّهُ سُؤَالٌ مُلْبِسٌ",uz:"Chunki u chalkashtiradigan savol"},{ar:"فِي ذَاتِهِ،",uz:"o‘z-o‘zicha,"}],full_uz:"Chunki bu savolning o‘zi chalkashlik tug‘diradi,",note:"مُلْبِسٌ — chalkashlik tug‘diruvchi, aniq anglashga xalaqit beruvchi."},
{num:225,time:"00:16:12,799 --> 00:16:15,319",arabic:"وَالْجَوَابُ عَلَيْهِ مُلْبِسٌ عَلَى النَّاسِ.",segs:[{ar:"وَالْجَوَابُ عَلَيْهِ",uz:"Unga beriladigan javob ham"},{ar:"مُلْبِسٌ عَلَى النَّاسِ.",uz:"odamlarni chalkashtiradi."}],full_uz:"Unga beriladigan javob ham odamlarni chalkashtiradi.",note:null},
{num:226,time:"00:16:15,319 --> 00:16:21,399",arabic:"وَلَكِنْ أُجِيبُ قَوْلًا وَاحِدًا:",segs:[{ar:"وَلَكِنْ أُجِيبُ",uz:"Lekin javob beraman"},{ar:"قَوْلًا وَاحِدًا:",uz:"birgina gap bilan:"}],full_uz:"Lekin birgina gap bilan javob beraman:",note:"أُجِيبُ — javob beraman; أَجَابَ يُجِيبُ fe’lidan."},
{num:227,time:"00:16:21,399 --> 00:16:23,460",arabic:"مَنْ قَالَ إِنَّ الْقُرْآنَ مَخْلُوقٌ،",segs:[{ar:"مَنْ قَالَ",uz:"Kim aytsa"},{ar:"إِنَّ الْقُرْآنَ مَخْلُوقٌ،",uz:"Qur’on yaratilgan deb,"}],full_uz:"Kim Qur’on yaratilgan desa,",note:"مَنْ — bu yerda shart bildiradi: kim ...qilsa."},
{num:228,time:"00:16:23,460 --> 00:16:27,299",arabic:"فَقَدْ كَفَرَ بِآيَاتِ اللَّهِ، وَاللَّهُ أَعْلَمُ.",segs:[{ar:"فَقَدْ كَفَرَ بِآيَاتِ اللَّهِ،",uz:"Allohning oyatlarini inkor qilgan bo‘ladi,"},{ar:"وَاللَّهُ أَعْلَمُ.",uz:"Alloh yaxshiroq biladi."}],full_uz:"Allohning oyatlarini inkor qilgan bo‘ladi. Alloh yaxshiroq biladi.",note:"كَفَرَ بِـ — ...ni inkor qilmoq, unga kufr keltirmoq."},
{num:229,time:"00:16:27,299 --> 00:16:31,519",arabic:"فَمَتَى نَحْظَى بِشَرَفِ مُجَالَسَتِكَ لِنَعْرِفَ أَكْثَرَ،",segs:[{ar:"فَمَتَى نَحْظَى بِشَرَفِ مُجَالَسَتِكَ",uz:"Qachon siz bilan suhbatlashish sharafiga erishamiz"},{ar:"لِنَعْرِفَ أَكْثَرَ،",uz:"ko‘proq bilish uchun,"}],full_uz:"Ko‘proq bilish uchun qachon siz bilan suhbatlashish sharafiga erishamiz,",note:"حَظِيَ بِـ — ...ga erishmoq, sazovor bo‘lmoq."},
{num:230,time:"00:16:31,519 --> 00:16:35,419",arabic:"عَمَّا تَقُولُ فِيمَنْ يَقُولُونَ إِنَّ الْقُرْآنَ مَخْلُوقٌ؟",segs:[{ar:"عَمَّا تَقُولُ",uz:"aytayotgan fikringiz haqida"},{ar:"فِيمَنْ يَقُولُونَ",uz:"shunday deydiganlar to‘g‘risida"},{ar:"إِنَّ الْقُرْآنَ مَخْلُوقٌ؟",uz:"Qur’on yaratilgan deb?"}],full_uz:"Qur’on yaratilgan deydiganlar haqidagi fikringizni?",note:"فِيمَنْ — فِي va مَنْ birikmasi: ...kishilar haqida."},
{num:231,time:"00:16:35,419 --> 00:16:39,639",arabic:"دَارِي مَفْتُوحَةٌ لِمَنْ أَرَادَ عِلْمًا لَا جِدَالًا.",segs:[{ar:"دَارِي مَفْتُوحَةٌ",uz:"Uyim ochiq"},{ar:"لِمَنْ أَرَادَ عِلْمًا",uz:"ilm istagan kishiga"},{ar:"لَا جِدَالًا.",uz:"bahsni emas."}],full_uz:"Uyim bahs emas, ilm istagan kishiga ochiq.",note:"دَارٌ muannas bo‘lgani uchun مَفْتُوحَةٌ ham muannas shaklda kelgan."},
{num:232,time:"00:16:39,639 --> 00:16:41,899",arabic:"اسْأَلُوا عَنْ بَيْتِ الشَّافِعِيِّ،",segs:null,full_uz:"Shofe’iyning uyini so‘ranglar,",note:"اسْأَلُوا عَنْ — ...haqida so‘ranglar, bu yerda manzilini surishtiringlar."},
{num:233,time:"00:16:41,899 --> 00:16:44,279",arabic:"وَعَلَى الرَّحْبِ وَالسَّعَةِ،",segs:null,full_uz:"Bajonidil kutib olaman,",note:"عَلَى الرَّحْبِ وَالسَّعَةِ — bajonidil, marhamat mazmunidagi turg‘un ibora."},
{num:234,time:"00:16:44,279 --> 00:16:50,639",arabic:"لِمَنْ جَاءَ مُتَعَلِّمًا مُعَلِّمًا لَا مُجَادِلًا.",segs:[{ar:"لِمَنْ جَاءَ",uz:"kelgan kishini"},{ar:"مُتَعَلِّمًا مُعَلِّمًا",uz:"o‘rganib, o‘rgatish uchun"},{ar:"لَا مُجَادِلًا.",uz:"tortishish uchun emas."}],full_uz:"O‘rganish va o‘rgatish uchun kelgan kishini, tortishish uchun kelganni emas.",note:"مُتَعَلِّمٌ — o‘rganuvchi; مُعَلِّمٌ — o‘rgatuvchi; مُجَادِلٌ — bahslashuvchi."},
{num:235,time:"00:16:50,639 --> 00:16:53,319",arabic:"بَارَكَ اللَّهُ فِيكَ أَيُّهَا الشَّافِعِيُّ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"أَيُّهَا الشَّافِعِيُّ.",uz:"ey Shofe’iy."}],full_uz:"Alloh sizga baraka bersin, Shofe’iy.",note:null},
{num:236,time:"00:16:53,319 --> 00:16:59,779",arabic:"وَلَكِنْ هَلَّا تَكَرَّمْتَ عَلَيْنَا وَشَرَّفْتَنَا بِزِيَارَتِكَ،",segs:[{ar:"وَلَكِنْ هَلَّا تَكَرَّمْتَ عَلَيْنَا",uz:"Lekin bizga marhamat qilsangiz"},{ar:"وَشَرَّفْتَنَا بِزِيَارَتِكَ،",uz:"va tashrifingiz bilan sharaflasangiz,"}],full_uz:"Lekin bizga marhamat qilib, tashrifingiz bilan sharaflasangiz,",note:"هَلَّا — iltimos yoki undashni bildiradi: ...qilsangiz, ...qilmaysizmi?"},
{num:237,time:"00:16:59,779 --> 00:17:03,099",arabic:"لِتَتَبَارَكَ دُورُنَا بِكَ،",segs:null,full_uz:"Uylarimiz siz bilan baraka topsin,",note:"دُورٌ — دَارٌ so‘zining ko‘pligi: uylar."},
{num:238,time:"00:17:03,100 --> 00:17:06,900",arabic:"وَيَسْتَمِعَ إِلَيْكَ إِخْوَةٌ آخَرُونَ لَنَا.",segs:[{ar:"وَيَسْتَمِعَ إِلَيْكَ",uz:"va sizni tinglasin"},{ar:"إِخْوَةٌ آخَرُونَ لَنَا.",uz:"boshqa birodarlarimiz ham."}],full_uz:"Boshqa birodarlarimiz ham sizni tinglasin.",note:"اسْتَمَعَ إِلَى — diqqat bilan tinglamoq."},
{num:239,time:"00:17:06,900 --> 00:17:08,980",arabic:"فَفِي دَارِكَ يَا شَيْخُ،",segs:[{ar:"فَفِي دَارِكَ",uz:"Chunki uyingizda"},{ar:"يَا شَيْخُ،",uz:"shayx,"}],full_uz:"Chunki uyingizda, shayx,",note:null},
{num:240,time:"00:17:08,980 --> 00:17:12,420",arabic:"لَنْ نَعْدَمَ زَائِرًا أَوْ مُقَاطِعًا،",segs:[{ar:"لَنْ نَعْدَمَ زَائِرًا",uz:"tashrif buyuruvchi topilmay qolmaydi"},{ar:"أَوْ مُقَاطِعًا،",uz:"yoki suhbatni bo‘luvchi,"}],full_uz:"Tashrif buyuradigan yoki suhbatni bo‘ladigan kishi topilib turadi,",note:"لَنْ نَعْدَمَ — topilmay qolmaydi, albatta bo‘ladi. مُقَاطِعٌ — gapni yoki ishni bo‘luvchi."},
{num:241,time:"00:17:12,420 --> 00:17:16,299",arabic:"وَبِهَذَا لَنْ نَحْظَى بِتَفَرُّغِكَ لَنَا.",segs:[{ar:"وَبِهَذَا لَنْ نَحْظَى",uz:"Shu sabab erisha olmaymiz"},{ar:"بِتَفَرُّغِكَ لَنَا.",uz:"bizga to‘liq vaqt ajratishingizga."}],full_uz:"Shu sabab bizga to‘liq vaqt ajratishingizga erisha olmaymiz.",note:"تَفَرَّغَ لِـ — boshqa ishlardan bo‘shab, vaqtini ...ga ajratmoq."},
{num:242,time:"00:17:16,299 --> 00:17:22,039",arabic:"قَبِلْتُ إِلْحَاحَكَ عَلَى دَعْوَتِكَ أَيُّهَا الرَّجُلُ.",segs:[{ar:"قَبِلْتُ إِلْحَاحَكَ عَلَى دَعْوَتِكَ",uz:"Qat’iy taklifingizga ko‘ndim"},{ar:"أَيُّهَا الرَّجُلُ.",uz:"birodar."}],full_uz:"Qat’iy taklifingizga ko‘ndim, birodar.",note:"إِلْحَاحٌ — qayta-qayta qat’iy iltimos qilish."},
{num:243,time:"00:17:22,039 --> 00:17:24,039",arabic:"مَتَى شِئْتَ.",segs:null,full_uz:"Qachon istasangiz.",note:"مَتَى شِئْتَ — istagan paytingizda."},
{num:244,time:"00:17:24,039 --> 00:17:26,319",arabic:"إِذَا شِئْتَ يَا شَيْخُ ذَهَبْنَا الْآنَ.",segs:[{ar:"إِذَا شِئْتَ يَا شَيْخُ",uz:"Istasangiz, shayx"},{ar:"ذَهَبْنَا الْآنَ.",uz:"hozir boramiz."}],full_uz:"Istasangiz, shayx, hozir boramiz.",note:"ذَهَبْنَا shaklan o‘tgan zamon bo‘lsa ham, shart javobida kelajakdagi ishni bildiradi."},
{num:245,time:"00:17:26,319 --> 00:17:28,940",arabic:"لِمَ لَا؟ تَفَضَّلْ.",segs:[{ar:"لِمَ لَا؟",uz:"Nega bo‘lmasin?"},{ar:"تَفَضَّلْ.",uz:"Marhamat."}],full_uz:"Nega bo‘lmasin? Marhamat.",note:null},
{num:246,time:"00:17:28,940 --> 00:17:30,279",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:247,time:"00:17:31,539 --> 00:17:51,559",arabic:"مُنْذُ مَتَى يَحْدُثُ هَذَا يَا ابْنَ الرَّبِيعِ؟",segs:[{ar:"مُنْذُ مَتَى يَحْدُثُ هَذَا",uz:"Bu qachondan beri sodir bo‘lyapti"},{ar:"يَا ابْنَ الرَّبِيعِ؟",uz:"Ibn Rabi’?"}],full_uz:"Bu qachondan beri sodir bo‘lyapti, Ibn Rabi’?",note:"مُنْذُ مَتَى — qachondan beri?"},
{num:248,time:"00:17:51,559 --> 00:17:55,420",arabic:"يَبْدُو مِنَ التَّوَارِيخِ يَا مَوْلَايَ أَنَّ ذَلِكَ يَحْدُثُ مُنْذُ زَمَنٍ.",segs:[{ar:"يَبْدُو مِنَ التَّوَارِيخِ",uz:"Sanalardan ko‘rinadiki"},{ar:"يَا مَوْلَايَ",uz:"hazratim"},{ar:"أَنَّ ذَلِكَ يَحْدُثُ مُنْذُ زَمَنٍ.",uz:"bu ancha vaqtdan beri sodir bo‘lmoqda."}],full_uz:"Sanalardan ko‘rinishicha, bu ancha vaqtdan beri sodir bo‘lmoqda, hazratim.",note:"تَوَارِيخُ — تَارِيخٌ so‘zining ko‘pligi; bu yerda hujjatlardagi sanalar."},
{num:249,time:"00:17:55,420 --> 00:17:59,799",arabic:"مُنْذُ زَمَنٍ؟ وَأَيْنَ كُنْتَ نَائِمًا عَنْ ذَلِكَ؟",segs:[{ar:"مُنْذُ زَمَنٍ؟",uz:"Ancha vaqtdan beri?"},{ar:"وَأَيْنَ كُنْتَ نَائِمًا عَنْ ذَلِكَ؟",uz:"Sen esa qayerda bundan bexabar uxlab yurgan eding?"}],full_uz:"Ancha vaqtdan beri? Sen esa qayerda bundan bexabar uxlab yurgan eding?",note:"نَائِمٌ عَنْ... — ko‘chma ma’noda ...dan bexabar, unga beparvo."},
{num:250,time:"00:17:59,799 --> 00:18:03,119",arabic:"لَمْ أَكُنْ نَائِمًا يَا أَمِيرَ الْمُؤْمِنِينَ، وَلَكِنَّكَ تَعْرِفُ...",segs:[{ar:"لَمْ أَكُنْ نَائِمًا",uz:"Uxlab yurganim yo‘q edi"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ،",uz:"mo‘minlar amiri,"},{ar:"وَلَكِنَّكَ تَعْرِفُ...",uz:"lekin o‘zingiz bilasiz..."}],full_uz:"Uxlab yurganim yo‘q edi, mo‘minlar amiri, lekin o‘zingiz bilasiz...",note:null},
{num:251,time:"00:18:03,119 --> 00:18:04,579",arabic:"أَعْرِفُ مَاذَا؟",segs:null,full_uz:"Nimani bilaman?",note:null},
{num:252,time:"00:18:04,579 --> 00:18:08,859",arabic:"أَعْرِفُ مَاذَا وَأَنَا لَا أَعْرِفُ مَا بَيْنَ يَدَيَّ؟",segs:[{ar:"أَعْرِفُ مَاذَا",uz:"Nimani bilaman"},{ar:"وَأَنَا لَا أَعْرِفُ",uz:"axir bilmayman-ku"},{ar:"مَا بَيْنَ يَدَيَّ؟",uz:"oldimda nima bo‘layotganini?"}],full_uz:"Nimani bilaman? Axir oldimda nima bo‘layotganini ham bilmayman-ku!",note:"بَيْنَ يَدَيَّ — so‘zma-so‘z ikki qo‘lim orasida; oldimda, qo‘lim ostida ma’nolarida ishlatiladi."},
{num:253,time:"00:18:08,859 --> 00:18:12,559",arabic:"أَعْرِفُ مَاذَا وَأَنَا أَمِيرُ الْمُؤْمِنِينَ؟",segs:[{ar:"أَعْرِفُ مَاذَا",uz:"Nimani bilaman"},{ar:"وَأَنَا أَمِيرُ الْمُؤْمِنِينَ؟",uz:"men mo‘minlar amiri bo‘la turib?"}],full_uz:"Men mo‘minlar amiri bo‘la turib, nimani bilaman?",note:"وَأَنَا... — hol jumlasi: men ...bo‘lgan holda."},
{num:254,time:"00:18:12,559 --> 00:18:21,980",arabic:"تَعْرِفُ يَا مَوْلَايَ أَنَّ ابْنَ الرَّبِيعِ لَا يَكَادُ يَجْرُؤُ عَلَى مُفَاتَحَتِكَ فِي أَيِّ شَأْنٍ يَخُصُّ أَبْنَاءَ يَحْيَى الْبَرْمَكِيِّ،",segs:[{ar:"تَعْرِفُ يَا مَوْلَايَ",uz:"Bilasiz, hazratim"},{ar:"أَنَّ ابْنَ الرَّبِيعِ لَا يَكَادُ يَجْرُؤُ",uz:"Ibn Rabi’ deyarli jur’at eta olmaydi"},{ar:"عَلَى مُفَاتَحَتِكَ",uz:"sizga gap ochishga"},{ar:"فِي أَيِّ شَأْنٍ",uz:"biror masalada"},{ar:"يَخُصُّ أَبْنَاءَ يَحْيَى الْبَرْمَكِيِّ،",uz:"Yahyo Barmakiyning o‘g‘illariga tegishli,"}],full_uz:"Hazratim, bilasizki, Ibn Rabi’ Yahyo Barmakiyning o‘g‘illariga tegishli biror masalada sizga gap ochishga deyarli jur’at eta olmaydi,",note:"مُفَاتَحَةٌ — biror mavzuda suhbat ochish. لَا يَكَادُ — deyarli ...maydi."},
{num:255,time:"00:18:21,980 --> 00:18:26,200",arabic:"حَتَّى تَرْدَعَهُ عَنْ ذَلِكَ وَتُوقِفَهُ عِنْدَ حَدِّهِ.",segs:[{ar:"حَتَّى تَرْدَعَهُ عَنْ ذَلِكَ",uz:"darhol uni bundan qaytarasiz"},{ar:"وَتُوقِفَهُ عِنْدَ حَدِّهِ.",uz:"va haddini bildirib qo‘yasiz."}],full_uz:"Chunki darhol uni bundan qaytarib, haddini bildirib qo‘yasiz.",note:"أَوْقَفَهُ عِنْدَ حَدِّهِ — uning haddini bildirmoq, chegaradan o‘tishiga yo‘l qo‘ymaslik."},
{num:256,time:"00:18:26,200 --> 00:18:31,580",arabic:"وَكُلَّمَا أَرَدْتُ مُفَاتَحَتَكَ فِي شَأْنٍ يَخُصُّهُمْ غَضِبْتَ وَمَنَعْتَنِي،",segs:[{ar:"وَكُلَّمَا أَرَدْتُ مُفَاتَحَتَكَ",uz:"Har safar sizga gap ochmoqchi bo‘lsam"},{ar:"فِي شَأْنٍ يَخُصُّهُمْ",uz:"ularga tegishli bir masalada"},{ar:"غَضِبْتَ وَمَنَعْتَنِي،",uz:"g‘azablanib, meni to‘xtatardingiz,"}],full_uz:"Har safar ularga tegishli bir masalada sizga gap ochmoqchi bo‘lsam, g‘azablanib, meni to‘xtatardingiz,",note:"كُلَّمَا — har safar ...ganda; takrorlanadigan holatni bildiradi."},
{num:257,time:"00:18:31,580 --> 00:18:38,420",arabic:"فَلَمْ أَجْرُؤْ عَلَى طَرْحِ الْأَمْرِ عَلَيْكَ حَتَّى تَكُونَ فِي يَدِيَ الْحُجَجُ وَالْأَدِلَّةُ،",segs:[{ar:"فَلَمْ أَجْرُؤْ",uz:"Shuning uchun jur’at etmadim"},{ar:"عَلَى طَرْحِ الْأَمْرِ عَلَيْكَ",uz:"sizga bu masalani aytishga"},{ar:"حَتَّى تَكُونَ فِي يَدِيَ",uz:"qo‘limda bo‘lmagunicha"},{ar:"الْحُجَجُ وَالْأَدِلَّةُ،",uz:"hujjatlar va dalillar,"}],full_uz:"Shuning uchun qo‘limda hujjatlar va dalillar bo‘lmagunicha bu masalani sizga aytishga jur’at etmadim,",note:"جَرُؤَ عَلَى — ...ga jur’at etmoq. طَرْحُ الْأَمْرِ — masalani o‘rtaga tashlash."},
{num:258,time:"00:18:38,420 --> 00:18:43,779",arabic:"الَّتِي تَشْهَدُ عَلَى سَرِقَاتِ الدَّوَاوِينِ تَحْتَ حُجَجٍ وَاهِيَةٍ وَادِّعَاءَاتٍ كَاذِبَةٍ.",segs:[{ar:"الَّتِي تَشْهَدُ عَلَى سَرِقَاتِ الدَّوَاوِينِ",uz:"devonlardagi o‘g‘riliklarga guvohlik beradigan"},{ar:"تَحْتَ حُجَجٍ وَاهِيَةٍ",uz:"asossiz bahonalar ostida"},{ar:"وَادِّعَاءَاتٍ كَاذِبَةٍ.",uz:"va yolg‘on da’volar bilan."}],full_uz:"Asossiz bahonalar va yolg‘on da’volar bilan devonlarda qilingan o‘g‘riliklarni ko‘rsatuvchi hujjatlar va dalillar.",note:"وَاهِيَةٌ — zaif, asossiz. الدَّوَاوِينُ — davlatning hisob-kitob va boshqaruv idoralari."},
{num:259,time:"00:18:43,779 --> 00:18:48,160",arabic:"وَهَا هِيَ الْوَثَائِقُ أَمَامَكَ يَا أَمِيرَ الْمُؤْمِنِينَ،",segs:[{ar:"وَهَا هِيَ الْوَثَائِقُ أَمَامَكَ",uz:"Mana, hujjatlar oldingizda"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ،",uz:"mo‘minlar amiri,"}],full_uz:"Mana, hujjatlar oldingizda, mo‘minlar amiri,",note:"وَثَائِقُ — وَثِيقَةٌ so‘zining ko‘pligi: hujjatlar."},
{num:260,time:"00:18:48,160 --> 00:18:56,380",arabic:"تُثْبِتُ بِالدَّلِيلِ الْقَاطِعِ أَنَّ الْبَرَامِكَةَ أَوْشَكُوا عَلَى تَرْكِ خَزِينَةِ الدَّوْلَةِ خَاوِيَةً يَا مَوْلَايَ.",segs:[{ar:"تُثْبِتُ بِالدَّلِيلِ الْقَاطِعِ",uz:"qat’iy dalil bilan isbotlaydi"},{ar:"أَنَّ الْبَرَامِكَةَ أَوْشَكُوا",uz:"barmakiylar yaqin qolganini"},{ar:"عَلَى تَرْكِ خَزِينَةِ الدَّوْلَةِ خَاوِيَةً",uz:"davlat xazinasini bo‘sh qoldirishga"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Barmakiylar davlat xazinasini bo‘shatib qo‘yishiga oz qolganini qat’iy dalil bilan isbotlaydi, hazratim.",note:"خَاوِيَةٌ — bo‘sh, ichida hech narsa qolmagan. أَوْشَكَ عَلَى — ...ga oz qoldi."},
{num:261,time:"00:18:56,380 --> 00:19:00,420",arabic:"وَمَا حَاجَتُهُمْ إِلَى ذَلِكَ؟",segs:null,full_uz:"Ularga buning nima keragi bor?",note:"مَا حَاجَتُهُمْ إِلَى...؟ — ularga ...ning nima zarurati bor?"},
{num:262,time:"00:19:00,420 --> 00:19:06,759",arabic:"إِنَّهُمْ يَأْخُذُونَ مِنْ بَيْتِ مَالِ الْمُسْلِمِينَ مَا يَكْفِي لِإِطْعَامِ مَدِينَةٍ بِكَامِلِهَا.",segs:[{ar:"إِنَّهُمْ يَأْخُذُونَ",uz:"Ular oladilar"},{ar:"مِنْ بَيْتِ مَالِ الْمُسْلِمِينَ",uz:"musulmonlar xazinasidan"},{ar:"مَا يَكْفِي لِإِطْعَامِ مَدِينَةٍ",uz:"bir shaharni boqishga yetadigan mablag‘ni"},{ar:"بِكَامِلِهَا.",uz:"butunlay."}],full_uz:"Ular musulmonlar xazinasidan butun bir shaharni boqishga yetadigan mablag‘ oladilar.",note:"بِكَامِلِهَا — to‘lig‘icha, butunicha. إِطْعَامٌ — ovqatlantirish, boqish."},
{num:263,time:"00:19:08,820 --> 00:19:15,519",arabic:"مَا أَعْرِفُهُ يَا مَوْلَايَ أَنَّ هُنَاكَ عَلَاقَةً مُرِيبَةً بَيْنَ جَعْفَرٍ الْبَرْمَكِيِّ وَيَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ.",segs:[{ar:"مَا أَعْرِفُهُ يَا مَوْلَايَ",uz:"Bilganim shuki, hazratim"},{ar:"أَنَّ هُنَاكَ عَلَاقَةً مُرِيبَةً",uz:"shubhali aloqa bor"},{ar:"بَيْنَ جَعْفَرٍ الْبَرْمَكِيِّ",uz:"Ja’far Barmakiy"},{ar:"وَيَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ.",uz:"va Yahyo ibn Abdulloh Tolibiy o‘rtasida."}],full_uz:"Bilganim shuki, hazratim, Ja’far Barmakiy bilan Yahyo ibn Abdulloh Tolibiy o‘rtasida shubhali aloqa bor.",note:"مُرِيبَةٌ — shubha uyg‘otadigan. عَلَاقَةٌ — aloqa, munosabat."},
{num:264,time:"00:19:15,519 --> 00:19:19,920",arabic:"أَيُّ عَلَاقَةٍ بَيْنَ جَعْفَرٍ الْبَرْمَكِيِّ وَذَلِكَ الطَّالِبِيِّ؟",segs:[{ar:"أَيُّ عَلَاقَةٍ",uz:"Qanday aloqa"},{ar:"بَيْنَ جَعْفَرٍ الْبَرْمَكِيِّ",uz:"Ja’far Barmakiy"},{ar:"وَذَلِكَ الطَّالِبِيِّ؟",uz:"va o‘sha Tolibiy o‘rtasida?"}],full_uz:"Ja’far Barmakiy bilan o‘sha Tolibiy o‘rtasida qanday aloqa bor?",note:null},
{num:265,time:"00:19:19,920 --> 00:19:22,379",arabic:"أَلَمْ يَكُنْ يَحْيَى سَجِينًا عِنْدَهُ؟",segs:[{ar:"أَلَمْ يَكُنْ يَحْيَى سَجِينًا",uz:"Yahyo mahbus emasmidi"},{ar:"عِنْدَهُ؟",uz:"uning qo‘lida?"}],full_uz:"Yahyo uning qo‘lida mahbus emasmidi?",note:"أَلَمْ يَكُنْ...؟ — ...emasmidi?; oldindan ma’lum holatni tasdiqlatish uchun so‘raladi."},
{num:266,time:"00:19:22,379 --> 00:19:23,259",arabic:"بَلَى يَا مَوْلَايَ.",segs:null,full_uz:"Ha, shunday edi, hazratim.",note:"بَلَى inkor shaklidagi savolga tasdiq javobidir: aksincha, shunday."},
{num:267,time:"00:19:23,259 --> 00:19:30,079",arabic:"وَلَكِنْ أَظُنُّ أَنَّ ثَمَّ أَمْرًا يُحَاكُ فِي السِّرِّ بَيْنَ الطَّالِبِيِّ وَالْبَرْمَكِيِّ.",segs:[{ar:"وَلَكِنْ أَظُنُّ",uz:"Lekin o‘ylaymanki"},{ar:"أَنَّ ثَمَّ أَمْرًا يُحَاكُ",uz:"qandaydir ish uyushtirilmoqda"},{ar:"فِي السِّرِّ",uz:"yashirincha"},{ar:"بَيْنَ الطَّالِبِيِّ وَالْبَرْمَكِيِّ.",uz:"Tolibiy va Barmakiy o‘rtasida."}],full_uz:"Lekin, o‘ylashimcha, Tolibiy bilan Barmakiy o‘rtasida yashirincha qandaydir ish uyushtirilmoqda.",note:"ثَمَّ — u yerda, mavjud. يُحَاكُ — aslida to‘qilmoqda; bu yerda yashirin reja tuzilmoqda."},
{num:268,time:"00:19:30,079 --> 00:19:45,359",arabic:"تَبْدَأُ أَنْتَ،",segs:null,full_uz:"Siz boshlaysizmi,",note:"أَنْتَ olmoshi kim boshlashiga urg‘u bermoqda."},
{num:269,time:"00:19:45,359 --> 00:19:47,699",arabic:"أَمْ نَبْدَأُ نَحْنُ أَيُّهَا الشَّافِعِيُّ؟",segs:[{ar:"أَمْ نَبْدَأُ نَحْنُ",uz:"yoki biz boshlaymizmi"},{ar:"أَيُّهَا الشَّافِعِيُّ؟",uz:"ey Shofe’iy?"}],full_uz:"Yoki biz boshlaymizmi, Shofe’iy?",note:"أَمْ oldingi savoldagi ikkinchi tanlovni kiritmoqda."},
{num:270,time:"00:19:47,699 --> 00:19:50,359",arabic:"أَنْتُمْ وَمَا تَخْتَارُونَ.",segs:null,full_uz:"Ixtiyor sizlarda.",note:"أَنْتُمْ وَمَا تَخْتَارُونَ — qanday tanlasangiz, shunday bo‘lsin mazmunidagi ifoda."},
{num:271,time:"00:19:50,359 --> 00:19:54,359",arabic:"إِنْ شِئْتُمْ بَدَأْتُ أَنَا أَوْ أَنْتُمْ، لَا يَهُمُّ.",segs:[{ar:"إِنْ شِئْتُمْ بَدَأْتُ أَنَا",uz:"Istasangiz, men boshlayman"},{ar:"أَوْ أَنْتُمْ،",uz:"yoki sizlar,"},{ar:"لَا يَهُمُّ.",uz:"farqi yo‘q."}],full_uz:"Istasangiz, men boshlayman yoki sizlar boshlanglar, farqi yo‘q.",note:"أَوْ أَنْتُمْ dan keyin boshlaysizlar fe’li aytilmagan, ammo mazmundan anglashiladi."},
{num:272,time:"00:19:54,359 --> 00:19:57,359",arabic:"نَبْدَأُ نَحْنُ.",segs:null,full_uz:"Biz boshlaymiz.",note:null},
{num:273,time:"00:19:57,359 --> 00:20:02,839",arabic:"إِنَّ مِنْ أَعْظَمِ الِافْتِرَاءِ عَلَى اللَّهِ مُسَاوَاتَهُ بِخَلْقِهِ،",segs:[{ar:"إِنَّ مِنْ أَعْظَمِ الِافْتِرَاءِ عَلَى اللَّهِ",uz:"Allohga qilingan eng katta tuhmatlardan biri"},{ar:"مُسَاوَاتَهُ بِخَلْقِهِ،",uz:"Uni yaratganlariga tenglashtirishdir,"}],full_uz:"Allohga qilingan eng katta tuhmatlardan biri Uni yaratganlariga tenglashtirishdir,",note:"افْتِرَاءٌ — uydirma, tuhmat. مُسَاوَاةٌ — tenglashtirish."},
{num:274,time:"00:20:02,839 --> 00:20:08,099",arabic:"وَإِثْبَاتَ صِفَاتٍ كَالسَّمْعِ وَالْبَصَرِ وَالْيَدِ وَالسَّاقِ لِلَّهِ،",segs:[{ar:"وَإِثْبَاتَ صِفَاتٍ",uz:"va sifatlarni tasdiqlash"},{ar:"كَالسَّمْعِ وَالْبَصَرِ",uz:"eshitish va ko‘rish kabi"},{ar:"وَالْيَدِ وَالسَّاقِ",uz:"qo‘l va boldir kabi"},{ar:"لِلَّهِ،",uz:"Alloh uchun,"}],full_uz:"Va Alloh uchun eshitish, ko‘rish, qo‘l va boldir kabi sifatlarni tasdiqlashdir,",note:"كَـ — kabi, o‘xshash. إِثْبَاتٌ — borligini tasdiqlash."},
{num:275,time:"00:20:08,099 --> 00:20:11,719",arabic:"وَهَذَا فِيهِ تَشْبِيهٌ لِلَّهِ بِخَلْقِهِ.",segs:[{ar:"وَهَذَا فِيهِ تَشْبِيهٌ لِلَّهِ",uz:"Bunda Allohni o‘xshatish bor"},{ar:"بِخَلْقِهِ.",uz:"U yaratganlarga."}],full_uz:"Bunda Allohni U yaratganlarga o‘xshatish bor.",note:"تَشْبِيهٌ — bir narsani boshqasiga o‘xshatish."},
{num:276,time:"00:20:11,719 --> 00:20:16,719",arabic:"وَقَدْ جَاءَ فِي الْقُرْآنِ: لَيْسَ كَمِثْلِهِ شَيْءٌ.",segs:[{ar:"وَقَدْ جَاءَ فِي الْقُرْآنِ:",uz:"Qur’onda kelgan:"},{ar:"لَيْسَ كَمِثْلِهِ شَيْءٌ.",uz:"Unga o‘xshash hech narsa yo‘q."}],full_uz:"Qur’onda: «Unga o‘xshash hech narsa yo‘q», deb kelgan.",note:"لَيْسَ ... شَيْءٌ — hech narsa ...emas; bu yerda har qanday o‘xshashlik inkor qilinmoqda."},
{num:277,time:"00:20:16,719 --> 00:20:18,819",arabic:"هَذِهِ وَاحِدَةٌ.",segs:null,full_uz:"Bu birinchisi.",note:"وَاحِدَةٌ ayol jinsidagi masala yoki nuqta ma’nosida ishlatilgan."},
{num:278,time:"00:20:18,819 --> 00:20:22,719",arabic:"وَالثَّانِيَةُ؟",segs:null,full_uz:"Ikkinchisi-chi?",note:null},
{num:279,time:"00:20:22,720 --> 00:20:27,420",arabic:"الثَّانِيَةُ: إِنَّ مِنْ أَعْظَمِ الْكَذِبِ عَلَى اللَّهِ،",segs:[{ar:"الثَّانِيَةُ:",uz:"Ikkinchisi:"},{ar:"إِنَّ مِنْ أَعْظَمِ الْكَذِبِ عَلَى اللَّهِ،",uz:"Alloh haqida aytilgan eng katta yolg‘onlardan biri,"}],full_uz:"Ikkinchisi: Alloh haqida aytilgan eng katta yolg‘onlardan biri —",note:"الْكَذِبُ عَلَى فُلَانٍ — bir kishi haqida yoki uning nomidan yolg‘on aytish."},
{num:280,time:"00:20:27,420 --> 00:20:32,519",arabic:"ادِّعَاءُ أَنَّ الْقُرْآنَ لَيْسَ بِمَخْلُوقٍ وَأَنَّهُ كَلَامُ اللَّهِ،",segs:[{ar:"ادِّعَاءُ أَنَّ الْقُرْآنَ لَيْسَ بِمَخْلُوقٍ",uz:"Qur’on yaratilmagan deb da’vo qilish"},{ar:"وَأَنَّهُ كَلَامُ اللَّهِ،",uz:"va uni Allohning kalomi deyish,"}],full_uz:"Qur’on yaratilmagan va u Allohning kalomi deb da’vo qilishdir,",note:"ادِّعَاءٌ — da’vo qilish. لَيْسَ بِمَخْلُوقٍ dagi بِ inkorni kuchaytiradi."},
{num:281,time:"00:20:32,519 --> 00:20:37,000",arabic:"وَبِهَذَا تَزْعُمُونَ أَنَّ اللَّهَ يَتَكَلَّمُ كَالنَّاسِ،",segs:[{ar:"وَبِهَذَا تَزْعُمُونَ",uz:"Bu bilan sizlar da’vo qilasizlar"},{ar:"أَنَّ اللَّهَ يَتَكَلَّمُ كَالنَّاسِ،",uz:"Alloh odamlardek gapiradi deb,"}],full_uz:"Bu bilan sizlar Alloh odamlardek gapiradi deb da’vo qilasizlar,",note:"زَعَمَ — da’vo qilmoq; ko‘pincha gapiruvchi qo‘shilmaydigan fikrni keltirishda ishlatiladi."},
{num:282,time:"00:20:37,000 --> 00:20:40,140",arabic:"وَفِي هَذَا تَشْبِيهٌ لِلَّهِ بِخَلْقِهِ.",segs:[{ar:"وَفِي هَذَا تَشْبِيهٌ لِلَّهِ",uz:"Bunda Allohni o‘xshatish bor"},{ar:"بِخَلْقِهِ.",uz:"U yaratganlarga."}],full_uz:"Bunda Allohni U yaratganlarga o‘xshatish bor.",note:null},
{num:283,time:"00:20:40,140 --> 00:20:42,579",arabic:"وَقَدْ جَاءَ فِي الْقُرْآنِ الْكَرِيمِ:",segs:null,full_uz:"Qur’oni karimda kelgan:",note:null},
{num:284,time:"00:20:42,579 --> 00:20:45,880",arabic:"إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا.",segs:[{ar:"إِنَّا جَعَلْنَاهُ",uz:"Albatta, Biz uni qildik"},{ar:"قُرْآنًا عَرَبِيًّا.",uz:"arabcha Qur’on."}],full_uz:"Albatta, Biz uni arabcha Qur’on qildik.",note:"جَعَلْنَاهُ — Biz uni qildik; ـنَا ega, ـهُ esa to‘ldiruvchini bildiradi."},
{num:285,time:"00:20:45,880 --> 00:20:48,579",arabic:"وَالْجَعْلُ يَعْنِي الْخَلْقَ.",segs:null,full_uz:"«Ja’l» esa yaratish deganidir.",note:"الْجَعْلُ — جَعَلَ fe’lining masdari; uning ma’nosi gapdagi qo‘llanishiga qarab o‘zgaradi."},
{num:286,time:"00:20:48,579 --> 00:20:55,980",arabic:"وَجَاءَ فِي الْقُرْآنِ أَيْضًا: اللَّهُ خَالِقُ كُلِّ شَيْءٍ، وَالْقُرْآنُ شَيْءٌ.",segs:[{ar:"وَجَاءَ فِي الْقُرْآنِ أَيْضًا:",uz:"Qur’onda yana kelgan:"},{ar:"اللَّهُ خَالِقُ كُلِّ شَيْءٍ،",uz:"Alloh har bir narsaning yaratuvchisidir,"},{ar:"وَالْقُرْآنُ شَيْءٌ.",uz:"Qur’on ham bir narsadir."}],full_uz:"Qur’onda yana: «Alloh har bir narsaning yaratuvchisidir», deb kelgan. Qur’on ham bir narsadir.",note:"خَالِقٌ — yaratuvchi; خَلَقَ fe’lining ism foil shakli."},
{num:287,time:"00:20:55,980 --> 00:20:58,879",arabic:"فَمَاذَا تَقُولُ فِي هَذَا أَيُّهَا الشَّافِعِيُّ؟",segs:[{ar:"فَمَاذَا تَقُولُ فِي هَذَا",uz:"Bunga nima deysiz"},{ar:"أَيُّهَا الشَّافِعِيُّ؟",uz:"ey Shofe’iy?"}],full_uz:"Bunga nima deysiz, Shofe’iy?",note:null},
{num:288,time:"00:20:58,879 --> 00:21:04,619",arabic:"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ، أَمَّا بَعْدُ:",segs:[{ar:"الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ،",uz:"Olamlarning Rabbi Allohga hamd bo‘lsin,"},{ar:"وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ،",uz:"Uning Rasuliga salavot va salom bo‘lsin,"},{ar:"أَمَّا بَعْدُ:",uz:"endi asosiy gapga o‘tsak:"}],full_uz:"Olamlarning Rabbi Allohga hamd, Uning Rasuliga salavot va salom bo‘lsin. Endi asosiy gapga o‘tsak:",note:"أَمَّا بَعْدُ — nutqning kirishidan asosiy qismiga o‘tishda ishlatiladigan ibora."},
{num:289,time:"00:21:04,619 --> 00:21:11,319",arabic:"فَأَمَّا تَشْبِيهُ اللَّهِ بِخَلْقِهِ فَهَذَا أَمْرٌ لَا يَصْدُرُ عَنْ مُسْلِمٍ.",segs:[{ar:"فَأَمَّا تَشْبِيهُ اللَّهِ بِخَلْقِهِ",uz:"Allohni yaratganlariga o‘xshatishga kelsak"},{ar:"فَهَذَا أَمْرٌ",uz:"bu shunday ishki"},{ar:"لَا يَصْدُرُ عَنْ مُسْلِمٍ.",uz:"musulmondan chiqmaydi."}],full_uz:"Allohni yaratganlariga o‘xshatishga kelsak, bunday ish musulmondan chiqmaydi.",note:"صَدَرَ عَنْ — ...dan chiqmoq, ...tomonidan sodir bo‘lmoq."},
{num:290,time:"00:21:11,319 --> 00:21:17,879",arabic:"وَأَمَّا اسْتِدْلَالُكَ بِقَوْلِهِ تَعَالَى: لَيْسَ كَمِثْلِهِ شَيْءٌ،",segs:[{ar:"وَأَمَّا اسْتِدْلَالُكَ",uz:"Dalil keltirishingizga kelsak"},{ar:"بِقَوْلِهِ تَعَالَى:",uz:"Alloh taoloning so‘zini:"},{ar:"لَيْسَ كَمِثْلِهِ شَيْءٌ،",uz:"Unga o‘xshash hech narsa yo‘q,"}],full_uz:"Alloh taoloning «Unga o‘xshash hech narsa yo‘q» degan so‘zini dalil keltirishingizga kelsak,",note:"اسْتِدْلَالٌ بِـ — biror narsani dalil sifatida keltirish."},
{num:291,time:"00:21:18,579 --> 00:21:20,559",arabic:"فَهُوَ اسْتِدْلَالٌ نَاقِصٌ.",segs:null,full_uz:"Bu to‘liq bo‘lmagan dalillashdir.",note:"نَاقِصٌ — kam, to‘liq bo‘lmagan."},
{num:292,time:"00:21:20,559 --> 00:21:25,039",arabic:"فَلَوْ أَكْمَلْتَ الْآيَةَ الْكَرِيمَةَ لَوَجَدْتَ اللَّهَ تَعَالَى يَقُولُ:",segs:[{ar:"فَلَوْ أَكْمَلْتَ الْآيَةَ الْكَرِيمَةَ",uz:"Agar oyati karimani oxirigacha o‘qiganingizda"},{ar:"لَوَجَدْتَ اللَّهَ تَعَالَى يَقُولُ:",uz:"Alloh taolo shunday deyishini ko‘rgan bo‘lardingiz:"}],full_uz:"Agar oyati karimani oxirigacha o‘qiganingizda, Alloh taolo shunday deyishini ko‘rgan bo‘lardingiz:",note:"لَوْ ... لَـ — ...ganingizda, ...gan bo‘lardingiz; shart va uning natijasini bildiradi."},
{num:293,time:"00:21:25,039 --> 00:21:29,099",arabic:"لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ.",segs:[{ar:"لَيْسَ كَمِثْلِهِ شَيْءٌ",uz:"Unga o‘xshash hech narsa yo‘q"},{ar:"وَهُوَ السَّمِيعُ الْبَصِيرُ.",uz:"U eshituvchi va ko‘ruvchidir."}],full_uz:"Unga o‘xshash hech narsa yo‘q. U eshituvchi va ko‘ruvchidir.",note:"السَّمِيعُ va الْبَصِيرُ — eshituvchi va ko‘ruvchi sifatlarini bildiradi."},
{num:294,time:"00:21:29,099 --> 00:21:36,639",arabic:"فَاللَّهُ عَزَّ وَجَلَّ قَدْ أَثْبَتَ لِنَفْسِهِ صِفَةَ السَّمْعِ وَصِفَةَ الْبَصَرِ،",segs:[{ar:"فَاللَّهُ عَزَّ وَجَلَّ",uz:"Qudratli va ulug‘ Alloh"},{ar:"قَدْ أَثْبَتَ لِنَفْسِهِ",uz:"O‘zi uchun tasdiqlagan"},{ar:"صِفَةَ السَّمْعِ وَصِفَةَ الْبَصَرِ،",uz:"eshitish va ko‘rish sifatlarini,"}],full_uz:"Qudratli va ulug‘ Alloh O‘zi uchun eshitish va ko‘rish sifatlarini tasdiqlagan,",note:"أَثْبَتَ لِنَفْسِهِ — o‘zi uchun borligini tasdiqladi."},
{num:295,time:"00:21:36,639 --> 00:21:39,759",arabic:"فِي حِينِ أَنَّكُمْ تَقُولُونَ إِنَّ اللَّهَ لَا يَسْمَعُ وَلَا يُبْصِرُ،",segs:[{ar:"فِي حِينِ أَنَّكُمْ تَقُولُونَ",uz:"Sizlar esa aytasizlar"},{ar:"إِنَّ اللَّهَ لَا يَسْمَعُ وَلَا يُبْصِرُ،",uz:"Alloh eshitmaydi va ko‘rmaydi deb,"}],full_uz:"Sizlar esa Alloh eshitmaydi va ko‘rmaydi deysizlar,",note:"فِي حِينِ أَنَّ — holbuki, ...esa; ikki holatni qarama-qarshi qo‘yadi."},
{num:296,time:"00:21:39,759 --> 00:21:42,960",arabic:"فَمَنْ يَفْتَرِي عَلَى اللَّهِ الْكَذِبَ؟",segs:null,full_uz:"Unda kim Alloh haqida yolg‘on to‘qiyapti?",note:"افْتَرَى الْكَذِبَ عَلَى — ...haqida yolg‘on to‘qimoq."},
{num:297,time:"00:21:42,960 --> 00:21:45,439",arabic:"إِنَّ إِثْبَاتَ السَّمْعِ وَالْبَصَرِ لِلَّهِ،",segs:[{ar:"إِنَّ إِثْبَاتَ السَّمْعِ وَالْبَصَرِ",uz:"Eshitish va ko‘rishni tasdiqlash"},{ar:"لِلَّهِ،",uz:"Alloh uchun,"}],full_uz:"Alloh uchun eshitish va ko‘rishni tasdiqlashda",note:"إِثْبَاتٌ — borligini tasdiqlash; gapning xabari keyingi parchada."},
{num:298,time:"00:21:45,440 --> 00:21:48,880",arabic:"فِيهِ تَشْبِيهٌ وَمُعَارَضَةٌ لِلْعَقْلِ،",segs:[{ar:"فِيهِ تَشْبِيهٌ",uz:"o‘xshatish bor"},{ar:"وَمُعَارَضَةٌ لِلْعَقْلِ،",uz:"va aqlga zidlik,"}],full_uz:"O‘xshatish va aqlga zidlik bor,",note:"مُعَارَضَةٌ لِـ — ...ga qarshilik, zidlik."},
{num:299,time:"00:21:48,880 --> 00:21:51,039",arabic:"وَقَدِ اشْتَبَهَ عَلَيْنَا.",segs:null,full_uz:"Bu bizga tushunarsiz bo‘lib qoldi.",note:"اشْتَبَهَ عَلَيْهِ — unga noaniq, chalkash bo‘lib ko‘rindi."},
{num:300,time:"00:21:51,039 --> 00:21:57,240",arabic:"ثُمَّ مَنْ قَالَ إِنَّ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ يَقُولُونَ:",segs:[{ar:"ثُمَّ مَنْ قَالَ",uz:"Qolaversa, kim aytdi"},{ar:"إِنَّ الْفُقَهَاءَ وَأَهْلَ الْحَدِيثِ يَقُولُونَ:",uz:"faqihlar va hadis ahli shunday deydi deb:"}],full_uz:"Qolaversa, faqihlar va hadis ahli shunday deydi deb kim aytdi:",note:"ثُمَّ — keyin; bu yerda navbatdagi dalil yoki e’tirozga o‘tishni bildiradi."},
{num:301,time:"00:21:57,240 --> 00:22:00,039",arabic:"إِنَّ اللَّهَ يَتَكَلَّمُ كَمَا يَتَكَلَّمُ النَّاسُ؟",segs:[{ar:"إِنَّ اللَّهَ يَتَكَلَّمُ",uz:"Alloh gapiradi"},{ar:"كَمَا يَتَكَلَّمُ النَّاسُ؟",uz:"odamlar gapirganidek?"}],full_uz:"Alloh odamlar gapirganidek gapiradi, deb?",note:"كَمَا — ...ganidek; ikki harakat usulini qiyoslaydi."},
{num:302,time:"00:22:00,039 --> 00:22:05,120",arabic:"بَلْ نَقُولُ: اللَّهُ يَتَكَلَّمُ مَتَى شَاءَ،",segs:[{ar:"بَلْ نَقُولُ:",uz:"Aksincha, biz deymiz:"},{ar:"اللَّهُ يَتَكَلَّمُ",uz:"Alloh gapiradi"},{ar:"مَتَى شَاءَ،",uz:"qachon istasa,"}],full_uz:"Aksincha, biz Alloh qachon istasa, gapiradi deymiz,",note:"مَتَى شَاءَ — qachon istasa."},
{num:303,time:"00:22:05,120 --> 00:22:06,840",arabic:"كَيْفَ شَاءَ،",segs:null,full_uz:"Qanday istasa,",note:"كَيْفَ شَاءَ — o‘zi istagan tarzda."},
{num:304,time:"00:22:06,840 --> 00:22:09,440",arabic:"لَيْسَ كَمِثْلِهِ شَيْءٌ.",segs:null,full_uz:"Unga o‘xshash hech narsa yo‘q.",note:null},
{num:305,time:"00:22:10,000 --> 00:22:11,799",arabic:"وَأَمَّا قَوْلُهُ تَعَالَى:",segs:null,full_uz:"Alloh taoloning quyidagi so‘ziga kelsak:",note:"أَمَّا — ...ga kelsak; muhokama qilinadigan mavzuni ajratib ko‘rsatadi."},
{num:306,time:"00:22:14,259 --> 00:22:17,640",arabic:"وَقَوْلُكَ إِنَّ الْجَعْلَ بِمَعْنَى الْخَلْقِ،",segs:[{ar:"وَقَوْلُكَ",uz:"va sizning gapingiz"},{ar:"إِنَّ الْجَعْلَ بِمَعْنَى الْخَلْقِ،",uz:"ja’l yaratish ma’nosida degan,"}],full_uz:"Va ja’l yaratish ma’nosida degan gapingizga kelsak,",note:"بِمَعْنَى — ...ma’nosida."},
{num:307,time:"00:22:17,640 --> 00:22:22,440",arabic:"فَهَذَا مَرْدُودٌ عَلَيْهِ بِنَصِّ الْقُرْآنِ.",segs:[{ar:"فَهَذَا مَرْدُودٌ عَلَيْهِ",uz:"bunga raddiya beriladi"},{ar:"بِنَصِّ الْقُرْآنِ.",uz:"Qur’on matni bilan."}],full_uz:"Bunga Qur’on matni bilan raddiya beriladi.",note:"مَرْدُودٌ عَلَيْهِ — unga javob yoki raddiya berilgan."},
{num:308,time:"00:22:22,440 --> 00:22:27,000",arabic:"فَإِنَّ الْجَعْلَ قَدْ يَأْتِي بِمَعْنَى الْخَلْقِ،",segs:[{ar:"فَإِنَّ الْجَعْلَ قَدْ يَأْتِي",uz:"Ja’l kelishi mumkin"},{ar:"بِمَعْنَى الْخَلْقِ،",uz:"yaratish ma’nosida,"}],full_uz:"Ja’l yaratish ma’nosida kelishi mumkin,",note:"قَدْ يَأْتِي — kelishi mumkin, ba’zan keladi."},
{num:309,time:"00:22:27,000 --> 00:22:29,740",arabic:"وَقَدْ يَأْتِي بِمَعْنَى التَّصْيِيرِ،",segs:[{ar:"وَقَدْ يَأْتِي",uz:"yana kelishi mumkin"},{ar:"بِمَعْنَى التَّصْيِيرِ،",uz:"bir holatga aylantirish ma’nosida,"}],full_uz:"Bir holatga aylantirish ma’nosida ham kelishi mumkin,",note:"التَّصْيِيرُ — bir narsani ma’lum holatga keltirish yoki aylantirish."},
{num:310,time:"00:22:29,740 --> 00:22:33,799",arabic:"كَمَا فِي قَوْلِهِ تَعَالَى عَنْ قَوْمِ إِبْرَاهِيمَ:",segs:[{ar:"كَمَا فِي قَوْلِهِ تَعَالَى",uz:"Alloh taoloning so‘zidagi kabi"},{ar:"عَنْ قَوْمِ إِبْرَاهِيمَ:",uz:"Ibrohim qavmi haqida:"}],full_uz:"Alloh taoloning Ibrohim qavmi haqidagi so‘zida bo‘lgani kabi:",note:null},
{num:311,time:"00:22:33,799 --> 00:22:36,779",arabic:"فَأَرَادُوا بِهِ كَيْدًا،",segs:null,full_uz:"Unga qarshi hiyla qilmoqchi bo‘ldilar,",note:"كَيْدٌ — hiyla, yashirin zarar yetkazish rejasi."},
{num:312,time:"00:22:36,779 --> 00:22:39,480",arabic:"فَجَعَلْنَاهُمُ الْأَسْفَلِينَ.",segs:null,full_uz:"Bas, Biz ularni eng tubanlar qildik.",note:"الْأَسْفَلِينَ — eng pastdagilar; bu yerda mag‘lub va xor bo‘lganlar mazmunida."},
{num:313,time:"00:22:39,480 --> 00:22:41,900",arabic:"أَيْ صَيَّرْنَاهُمْ أَسْفَلِينَ.",segs:null,full_uz:"Ya’ni ularni tuban holga tushirdik.",note:"أَيْ — ya’ni; oldingi iborani izohlash uchun ishlatiladi."},
{num:314,time:"00:22:41,900 --> 00:22:45,680",arabic:"فَمَعْلُومٌ أَنَّهُ لَمْ يَخْلُقْهُمْ وَهُمْ أَسْفَلُونَ.",segs:[{ar:"فَمَعْلُومٌ أَنَّهُ لَمْ يَخْلُقْهُمْ",uz:"Ma’lumki, U ularni yaratmagan"},{ar:"وَهُمْ أَسْفَلُونَ.",uz:"tuban bo‘lgan hollarida."}],full_uz:"Ma’lumki, U ularni boshidanoq tuban holda yaratmagan.",note:"وَهُمْ أَسْفَلُونَ — hol jumlasi: ular tuban bo‘lgan holda."},
{num:315,time:"00:22:45,680 --> 00:22:49,680",arabic:"وَعَلَى هَذَا يَكُونُ مَعْنَى قَوْلِهِ تَعَالَى:",segs:[{ar:"وَعَلَى هَذَا",uz:"Shunga ko‘ra"},{ar:"يَكُونُ مَعْنَى قَوْلِهِ تَعَالَى:",uz:"Alloh taoloning so‘zi ma’nosi shunday bo‘ladi:"}],full_uz:"Shunga ko‘ra, Alloh taoloning quyidagi so‘zining ma’nosi:",note:"عَلَى هَذَا — shunga asoslanib, shunga ko‘ra."},
{num:316,time:"00:22:52,880 --> 00:22:56,420",arabic:"أَيْ صَيَّرْنَاهُ قُرْآنًا عَرَبِيًّا.",segs:[{ar:"أَيْ صَيَّرْنَاهُ",uz:"ya’ni Biz uni qildik"},{ar:"قُرْآنًا عَرَبِيًّا.",uz:"arabcha Qur’on holida."}],full_uz:"Ya’ni Biz uni arabcha Qur’on holida qildik.",note:"صَيَّرَ — ma’lum holatga keltirdi; ikki to‘ldiruvchi olishi mumkin."},
{num:317,time:"00:22:56,420 --> 00:22:59,460",arabic:"وَمَاذَا تَفْعَلُ بِقَوْلِهِ تَعَالَى:",segs:[{ar:"وَمَاذَا تَفْعَلُ",uz:"Nima qilasiz"},{ar:"بِقَوْلِهِ تَعَالَى:",uz:"Alloh taoloning bu so‘zini:"}],full_uz:"Alloh taoloning quyidagi so‘zini qanday izohlaysiz:",note:"مَاذَا تَفْعَلُ بِـ؟ — buni nima qilasiz?; bu yerda dalilga qanday javob berasiz ma’nosida."},
{num:318,time:"00:22:59,460 --> 00:23:02,380",arabic:"اللَّهُ خَالِقُ كُلِّ شَيْءٍ.",segs:null,full_uz:"Alloh har bir narsaning yaratuvchisidir.",note:null},
{num:319,time:"00:23:02,380 --> 00:23:04,080",arabic:"وَالْقُرْآنُ شَيْءٌ،",segs:null,full_uz:"Qur’on esa bir narsadir,",note:null},
{num:320,time:"00:23:04,080 --> 00:23:06,100",arabic:"إِذَنْ الْقُرْآنُ مَخْلُوقٌ.",segs:null,full_uz:"Demak, Qur’on yaratilgan.",note:"إِذَنْ — demak; oldingi fikrlardan xulosa chiqarishni bildiradi."},
{num:321,time:"00:23:06,100 --> 00:23:08,900",arabic:"أَقُولُ:",segs:null,full_uz:"Aytamanki:",note:null},
{num:322,time:"00:23:08,900 --> 00:23:12,440",arabic:"إِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ:",segs:null,full_uz:"Qudratli va ulug‘ Alloh aytgan:",note:null},
{num:323,time:"00:23:12,440 --> 00:23:16,560",arabic:"قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً؟",segs:[{ar:"قُلْ",uz:"Ayting"},{ar:"أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً؟",uz:"qaysi narsa guvohlikda eng ulug‘?"}],full_uz:"Ayting: «Qaysi narsa guvohlikda eng ulug‘?»",note:"شَهَادَةً — tamyiz: qaysi jihatdan ulug‘ ekanini aniqlashtiradi."},
{num:324,time:"00:23:16,560 --> 00:23:19,600",arabic:"قُلِ اللَّهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ.",segs:[{ar:"قُلِ اللَّهُ شَهِيدٌ",uz:"Ayting: Alloh guvohdir"},{ar:"بَيْنِي وَبَيْنَكُمْ.",uz:"men bilan sizlarning orangizda."}],full_uz:"Ayting: «Alloh men bilan sizlarning orangizda guvohdir».",note:"شَهِيدٌ — bu yerda guvoh ma’nosida."},
{num:325,time:"00:23:19,600 --> 00:23:25,940",arabic:"فَاللَّهُ عَزَّ وَجَلَّ يَصِفُ نَفْسَهُ بِأَنَّهُ شَيْءٌ،",segs:[{ar:"فَاللَّهُ عَزَّ وَجَلَّ",uz:"Qudratli va ulug‘ Alloh"},{ar:"يَصِفُ نَفْسَهُ",uz:"O‘zini tavsiflaydi"},{ar:"بِأَنَّهُ شَيْءٌ،",uz:"narsa deb,"}],full_uz:"Qudratli va ulug‘ Alloh O‘zini narsa deb tavsiflaydi,",note:"وَصَفَ نَفْسَهُ بِـ — o‘zini ...deb tavsifladi."},
{num:326,time:"00:23:25,940 --> 00:23:31,000",arabic:"فَهَلْ هَذَا يَعْنِي أَنَّ اللَّهَ سُبْحَانَهُ وَتَعَالَى مَخْلُوقٌ؟",segs:[{ar:"فَهَلْ هَذَا يَعْنِي",uz:"Bu anglatadimi"},{ar:"أَنَّ اللَّهَ سُبْحَانَهُ وَتَعَالَى مَخْلُوقٌ؟",uz:"Alloh subhanahu va taolo yaratilgan deganini?"}],full_uz:"Bu Alloh subhanahu va taolo yaratilgan degan ma’noni anglatadimi?",note:"هَلْ هَذَا يَعْنِي أَنَّ...؟ — bu ...degan ma’noni anglatadimi?"},
{num:327,time:"00:23:31,000 --> 00:23:36,300",arabic:"وَعَلَى هَذَا لَا يَلْزَمُ مِنْ قَوْلِهِ تَعَالَى:",segs:[{ar:"وَعَلَى هَذَا لَا يَلْزَمُ",uz:"Shunga ko‘ra, kelib chiqmaydi"},{ar:"مِنْ قَوْلِهِ تَعَالَى:",uz:"Alloh taoloning so‘zidan:"}],full_uz:"Shunga ko‘ra, Alloh taoloning quyidagi so‘zidan kelib chiqmaydi:",note:"لَا يَلْزَمُ مِنْ... — ...dan bunday xulosa zaruriy ravishda kelib chiqmaydi."},
{num:328,time:"00:23:38,559 --> 00:23:40,019",arabic:"أَنَّ الْقُرْآنَ مَخْلُوقٌ،",segs:null,full_uz:"Qur’on yaratilgan degan xulosa,",note:"Bu parcha oldingi لَا يَلْزَمُ — kelib chiqmaydi fe’liga bog‘langan."},
{num:329,time:"00:23:40,019 --> 00:23:43,460",arabic:"أَوْ أَنَّ اللَّهَ جَلَّ وَعَلَا مَخْلُوقٌ،",segs:null,full_uz:"Yoki ulug‘ va yuksak Alloh yaratilgan degan xulosa,",note:"جَلَّ وَعَلَا — U ulug‘ va yuksakdir; Allohni ulug‘lash iborasi."},
{num:330,time:"00:23:43,460 --> 00:23:46,579",arabic:"كَمَا لَا يَلْزَمُ مِنْ قَوْلِهِ تَعَالَى:",segs:[{ar:"كَمَا لَا يَلْزَمُ",uz:"Xuddi kelib chiqmaganidek"},{ar:"مِنْ قَوْلِهِ تَعَالَى:",uz:"Alloh taoloning so‘zidan:"}],full_uz:"Xuddi Alloh taoloning quyidagi so‘zidan kelib chiqmaganidek:",note:null},
{num:331,time:"00:23:46,579 --> 00:23:48,659",arabic:"كُلُّ نَفْسٍ ذَائِقَةُ الْمَوْتِ.",segs:[{ar:"كُلُّ نَفْسٍ",uz:"Har bir jon"},{ar:"ذَائِقَةُ الْمَوْتِ.",uz:"o‘limni totuvchidir."}],full_uz:"Har bir jon o‘limni totuvchidir.",note:"ذَائِقَةٌ — totuvchi; ذَاقَ يَذُوقُ fe’lidan."},
{num:332,time:"00:23:48,659 --> 00:23:51,960",arabic:"أَنَّ اللَّهَ سُبْحَانَهُ وَتَعَالَى سَيَمُوتُ،",segs:null,full_uz:"Alloh subhanahu va taolo o‘ladi degan xulosa.",note:"Bu gap oldingi لَا يَلْزَمُ iborasi bilan inkor qilinayotgan xulosani bildiradi."},
{num:333,time:"00:23:51,960 --> 00:23:54,859",arabic:"بَلِ الْمُرَادُ مِنْ ذَلِكَ،",segs:null,full_uz:"Balki bundan ko‘zlangan ma’no —",note:"الْمُرَادُ مِنْ ذَلِكَ — bundan ko‘zlangan ma’no yoki maqsad."},
{num:334,time:"00:23:54,859 --> 00:23:59,339",arabic:"أَنَّ أَنْفُسَ الْمَخْلُوقَاتِ سَتَذُوقُ الْمَوْتَ لَا مَحَالَةَ.",segs:[{ar:"أَنَّ أَنْفُسَ الْمَخْلُوقَاتِ",uz:"yaratilganlarning jonlari"},{ar:"سَتَذُوقُ الْمَوْتَ",uz:"o‘limni totadi"},{ar:"لَا مَحَالَةَ.",uz:"muqarrar ravishda."}],full_uz:"Yaratilganlarning jonlari muqarrar ravishda o‘limni totishidir.",note:"لَا مَحَالَةَ — albatta, muqarrar ravishda."},
{num:335,time:"00:23:59,339 --> 00:24:01,619",arabic:"أَمَّا نَفْسُ الْخَالِقِ،",segs:null,full_uz:"Yaratuvchining O‘ziga kelsak,",note:"نَفْسٌ bu yerda zot, o‘zi ma’nosida."},
{num:336,time:"00:24:01,619 --> 00:24:04,599",arabic:"فَلَا يَتَطَرَّقُ لَهَا هَذَا.",segs:null,full_uz:"Bu Unga taalluqli bo‘lmaydi.",note:"تَطَرَّقَ إِلَى — kirib bormoq, daxldor bo‘lmoq; bu yerda hukmning tatbiq qilinishi nazarda tutilgan."},
{num:337,time:"00:24:06,299 --> 00:24:10,299",arabic:"بِمَاذَا تَرُدُّونَ؟",segs:null,full_uz:"Qanday javob berasizlar?",note:null},
{num:338,time:"00:24:28,299 --> 00:24:32,779",arabic:"مَنْ كَانَ يَبْحَثُ عَنِ الْحَقِّ فَأَحْرَى بِهِ أَنْ يَتَّبِعَهُ،",segs:[{ar:"مَنْ كَانَ يَبْحَثُ عَنِ الْحَقِّ",uz:"Kim haqni izlayotgan bo‘lsa"},{ar:"فَأَحْرَى بِهِ أَنْ يَتَّبِعَهُ،",uz:"unga ergashishi munosibroqdir,"}],full_uz:"Haqni izlayotgan kishi unga ergashishi munosibdir,",note:"أَحْرَى بِهِ أَنْ... — uning ...qilishi munosibroq, lozimroq."},
{num:339,time:"00:24:32,779 --> 00:24:35,899",arabic:"دُونَ أَنْ يَلْتَفِتَ إِلَى مَنْ قَالَ.",segs:[{ar:"دُونَ أَنْ يَلْتَفِتَ",uz:"e’tibor bermasdan"},{ar:"إِلَى مَنْ قَالَ.",uz:"uni kim aytganiga."}],full_uz:"Uni kim aytganiga e’tibor bermasdan.",note:"الْتَفَتَ إِلَى — yuzlanmoq; ko‘chma ma’noda e’tibor bermoq."},
{num:340,time:"00:24:35,900 --> 00:24:39,900",arabic:"فَقَدْ قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ:",segs:[{ar:"فَقَدْ قَالَ عَلِيٌّ",uz:"Ali aytganlar"},{ar:"رَضِيَ اللَّهُ عَنْهُ:",uz:"Alloh u kishidan rozi bo‘lsin:"}],full_uz:"Ali roziyallohu anhu aytganlar:",note:"رَضِيَ اللَّهُ عَنْهُ — Alloh undan rozi bo‘lsin mazmunidagi duo."},
{num:341,time:"00:24:39,900 --> 00:24:42,740",arabic:"تُعْرَفُ الرِّجَالُ بِالْحَقِّ،",segs:null,full_uz:"Kishilar haq bilan taniladi,",note:"تُعْرَفُ — taniladi, majhul nisbat."},
{num:342,time:"00:24:42,740 --> 00:24:45,620",arabic:"وَلَا تَعْرِفِ الْحَقَّ بِالرِّجَالِ.",segs:null,full_uz:"Haqni kishilar bilan tanima.",note:"لَا تَعْرِفْ — tanima; taqiq. So‘zlar ulanib o‘qilganda oxirgi ف kasra olgan."},
{num:343,time:"00:24:45,620 --> 00:24:49,280",arabic:"أَمَّا مَنْ لَجَّ فِي الْعِنَادِ،",segs:null,full_uz:"Qaysarlikda o‘jarlik qilgan kishiga kelsak,",note:"لَجَّ فِي — bir ishda o‘jarlik bilan davom etmoq. الْعِنَادُ — qaysarlik."},
{num:344,time:"00:24:49,280 --> 00:24:53,860",arabic:"فَيُوشِكُ أَنْ يُلْقِيَ بِيَدِهِ فِي التَّهْلُكَةِ،",segs:[{ar:"فَيُوشِكُ أَنْ يُلْقِيَ بِيَدِهِ",uz:"u o‘z qo‘li bilan tashlashiga oz qoladi"},{ar:"فِي التَّهْلُكَةِ،",uz:"o‘zini halokatga,"}],full_uz:"U o‘zini o‘z qo‘li bilan halokatga tashlashiga oz qoladi,",note:"أَلْقَى بِيَدِهِ فِي التَّهْلُكَةِ — o‘zini halokatga tashlamoq."},
{num:345,time:"00:24:53,860 --> 00:24:56,480",arabic:"فَيَخْسَرَ دُنْيَاهُ وَآخِرَتَهُ.",segs:null,full_uz:"Natijada dunyosini ham, oxiratini ham boy beradi.",note:"خَسِرَ — yutqazmoq, boy bermoq."},
{num:346,time:"00:24:56,480 --> 00:25:02,460",arabic:"أَسْتَوْدِعُكُمُ اللَّهَ.",segs:null,full_uz:"Sizlarni Allohga omonat topshiraman.",note:"Xayrlashishda aytiladigan Allohga omonat bo‘linglar mazmunidagi ibora."},
{num:347,time:"00:25:05,900 --> 00:25:16,900",arabic:"نَصَحْتُكَ يَا ابْنَ الْأَشْرَسِ بِأَلَّا نُنَاظِرَهُ،",segs:[{ar:"نَصَحْتُكَ يَا ابْنَ الْأَشْرَسِ",uz:"Sizga maslahat bergandim, Ibn Ashras"},{ar:"بِأَلَّا نُنَاظِرَهُ،",uz:"u bilan munozara qilmaslikni,"}],full_uz:"U bilan munozara qilmaylik deb sizga maslahat bergandim, Ibn Ashras,",note:"نَاظَرَ — dalillar bilan bahslashmoq, munozara qilmoq."},
{num:348,time:"00:25:16,900 --> 00:25:19,060",arabic:"وَلَمْ تَسْمَعِ النَّصِيحَةَ.",segs:null,full_uz:"Maslahatga quloq solmadingiz.",note:"سَمِعَ النَّصِيحَةَ — maslahatni eshitmoq; bu yerda unga amal qilish ma’nosida."},
{num:349,time:"00:25:19,060 --> 00:25:21,060",arabic:"هَلْ أَنْتَ رَاضٍ الْآنَ؟",segs:null,full_uz:"Endi ko‘nglingiz to‘ldimi?",note:"رَاضٍ — rozi, mamnun; noaniq bosh kelishikda oxirgi ي tushadi."},
{num:350,time:"00:25:35,900 --> 00:25:41,240",arabic:"السَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"السَّلَامُ عَلَى مَوْلَايَ",uz:"Hazratimga salom bo‘lsin"},{ar:"أَمِيرِ الْمُؤْمِنِينَ.",uz:"mo‘minlar amiriga."}],full_uz:"Hazratim, mo‘minlar amiriga salom bo‘lsin.",note:null},
{num:351,time:"00:25:41,240 --> 00:25:46,240",arabic:"وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"وَعَلَيْكَ السَّلَامُ",uz:"Senga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"Allohning rahmati va barakalari bo‘lsin"},{ar:"يَا أَبَا الْعَبَّاسِ.",uz:"Abu Abbos."}],full_uz:"Va alaykassalom va rahmatullohi va barakatuh, Abu Abbos.",note:"عَلَيْكَ — bir erkakka; عَلَيْكُمْ — ko‘pchilikka murojaat."},
{num:352,time:"00:25:46,240 --> 00:25:47,240",arabic:"اجْلِسْ.",segs:null,full_uz:"O‘tir.",note:null},
{num:353,time:"00:25:47,240 --> 00:25:53,900",arabic:"مَا الَّذِي يَشْغَلُ بَالَ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"مَا الَّذِي يَشْغَلُ بَالَ",uz:"Nima xayolini band qilmoqda"},{ar:"أَمِيرِ الْمُؤْمِنِينَ؟",uz:"mo‘minlar amirining?"}],full_uz:"Mo‘minlar amirining xayolini nima band qilmoqda?",note:"شَغَلَ بَالَهُ — xayolini band qilmoq, tashvishga solmoq."},
{num:354,time:"00:25:55,900 --> 00:25:59,900",arabic:"قُلْ: مَا الَّذِي لَا يَشْغَلُ بَالَ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"قُلْ:",uz:"Shunday de:"},{ar:"مَا الَّذِي لَا يَشْغَلُ بَالَ",uz:"nima xayolini band qilmayapti"},{ar:"أَمِيرِ الْمُؤْمِنِينَ؟",uz:"mo‘minlar amirining?"}],full_uz:"Mo‘minlar amirining xayolini nima band qilmayapti, deb so‘ra.",note:"Savoldagi لَا inkori hamma narsa tashvish tug‘dirayotganini ta’kidlaydi."},
{num:355,time:"00:26:02,900 --> 00:26:10,420",arabic:"لَيْسَ النَّاسُ كُلُّهُمْ كَالْبَرَامِكَةِ يَا مَوْلَايَ.",segs:[{ar:"لَيْسَ النَّاسُ كُلُّهُمْ كَالْبَرَامِكَةِ",uz:"Hamma odamlar barmakiylardek emas"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Hamma odamlar barmakiylardek emas, hazratim.",note:"كُلُّهُمْ — ularning barchasi; النَّاسُ so‘zini ta’kidlamoqda."},
{num:356,time:"00:26:10,420 --> 00:26:14,460",arabic:"أَنَا لَمْ أَقْصِدْ أَنَّ النَّاسَ كُلَّهُمْ كَالْبَرَامِكَةِ،",segs:[{ar:"أَنَا لَمْ أَقْصِدْ",uz:"Men nazarda tutmadim"},{ar:"أَنَّ النَّاسَ كُلَّهُمْ كَالْبَرَامِكَةِ،",uz:"hamma odamlar barmakiylardek deb,"}],full_uz:"Men hamma odamlar barmakiylardek demoqchi emas edim,",note:null},
{num:357,time:"00:26:14,460 --> 00:26:18,460",arabic:"إِنَّمَا قَصَدْتُ أَنَّ الْبَرَامِكَةَ كَكُلِّ النَّاسِ.",segs:[{ar:"إِنَّمَا قَصَدْتُ",uz:"Faqat nazarda tutdim"},{ar:"أَنَّ الْبَرَامِكَةَ كَكُلِّ النَّاسِ.",uz:"barmakiylar ham hamma odamlar kabi ekanini."}],full_uz:"Barmakiylar ham hamma odamlar kabi demoqchi edim.",note:"إِنَّمَا — fikrni cheklab, faqat shu nazarda tutilganini bildiradi."},
{num:358,time:"00:26:18,460 --> 00:26:21,740",arabic:"فَإِذَا أَتَى أَمِيرُ الْمُؤْمِنِينَ عَلَى ذِكْرِهِمْ،",segs:[{ar:"فَإِذَا أَتَى أَمِيرُ الْمُؤْمِنِينَ",uz:"Mo‘minlar amiri to‘xtalgan ekanlar"},{ar:"عَلَى ذِكْرِهِمْ،",uz:"ularning zikriga,"}],full_uz:"Mo‘minlar amiri ular haqida gap ochgan ekanlar,",note:"أَتَى عَلَى ذِكْرِهِ — uni tilga oldi, u haqida gap ochdi."},
{num:359,time:"00:26:21,740 --> 00:26:24,660",arabic:"فَثَمَّ سُؤَالٌ يُحَيِّرُنِي.",segs:null,full_uz:"Meni o‘ylantirayotgan bir savol bor.",note:"ثَمَّ — u yerda, mavjud; يُحَيِّرُنِي — meni hayron qoldiradi, o‘ylantiradi."},
{num:360,time:"00:26:24,660 --> 00:26:29,360",arabic:"تُرِيدُ أَنْ تَسْأَلَ لِمَاذَا يَعْذِرُ أَمِيرُ الْمُؤْمِنِينَ الْبَرَامِكَةَ،",segs:[{ar:"تُرِيدُ أَنْ تَسْأَلَ",uz:"So‘ramoqchisan"},{ar:"لِمَاذَا يَعْذِرُ أَمِيرُ الْمُؤْمِنِينَ الْبَرَامِكَةَ،",uz:"nega mo‘minlar amiri barmakiylarni uzrli deb bilishini,"}],full_uz:"Nega mo‘minlar amiri barmakiylarni uzrli deb biladi, deb so‘ramoqchisan,",note:"عَذَرَهُ — uni uzrli deb bilmoq, aybini kechirmoq."},
{num:361,time:"00:26:29,360 --> 00:26:32,100",arabic:"حَتَّى لَجُّوا فِي طُغْيَانِهِمْ وَمَكَائِدِهِمْ،",segs:[{ar:"حَتَّى لَجُّوا",uz:"hatto o‘jarlik bilan davom etdilar"},{ar:"فِي طُغْيَانِهِمْ وَمَكَائِدِهِمْ،",uz:"tug‘yonlari va hiylalarida,"}],full_uz:"Hatto ular tug‘yon va hiylalarini o‘jarlik bilan davom ettirdilar,",note:"مَكَائِدُ — مَكِيدَةٌ so‘zining ko‘pligi: hiylalar, fitnalar."},
{num:362,time:"00:26:32,099 --> 00:26:35,639",arabic:"وَتَمَكَّنُوا فِي ظِلِّ دَوْلَةِ الْخِلَافَةِ كُلَّ هَذَا التَّمَكُّنِ.",segs:[{ar:"وَتَمَكَّنُوا",uz:"va mustahkam o‘rnashib oldilar"},{ar:"فِي ظِلِّ دَوْلَةِ الْخِلَافَةِ",uz:"xalifalik davlati soyasida"},{ar:"كُلَّ هَذَا التَّمَكُّنِ.",uz:"bu qadar kuchli."}],full_uz:"Xalifalik davlati soyasida bu qadar mustahkam o‘rnashib oldilar.",note:"تَمَكَّنَ — mustahkam o‘rnashmoq, kuch va imkoniyatga ega bo‘lmoq."},
{num:363,time:"00:26:35,639 --> 00:26:38,339",arabic:"فَلْيَعْذُرْنِي مَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ،",segs:[{ar:"فَلْيَعْذُرْنِي",uz:"Meni kechirsinlar"},{ar:"مَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ،",uz:"hazratim, mo‘minlar amiri,"}],full_uz:"Hazratim, mo‘minlar amiri meni kechirsinlar,",note:"فَلْيَعْذُرْنِي — meni kechirsin; hurmat bilan iltimos qilish shakli."},
{num:364,time:"00:26:38,339 --> 00:26:42,319",arabic:"وَلَكِنَّ الشُّبْهَةَ الَّتِي حَامَتْ حَوْلَ الْبَرَامِكَةِ،",segs:[{ar:"وَلَكِنَّ الشُّبْهَةَ",uz:"Lekin shubha"},{ar:"الَّتِي حَامَتْ حَوْلَ الْبَرَامِكَةِ،",uz:"barmakiylar atrofida paydo bo‘lgan,"}],full_uz:"Lekin barmakiylar atrofida paydo bo‘lgan shubha,",note:"حَامَتْ حَوْلَهُ الشُّبْهَةُ — uning atrofida shubha paydo bo‘ldi, u gumon ostida qoldi."},
{num:365,time:"00:26:42,319 --> 00:26:45,839",arabic:"لَوْ أَنَّهَا دَارَتْ حَوْلَ فَرْدٍ مِنْ أَفْرَادِ الْبَيْتِ الْعَبَّاسِيِّ،",segs:[{ar:"لَوْ أَنَّهَا دَارَتْ حَوْلَ فَرْدٍ",uz:"agar bir kishi atrofida paydo bo‘lganida"},{ar:"مِنْ أَفْرَادِ الْبَيْتِ الْعَبَّاسِيِّ،",uz:"Abbosiylar xonadoni a’zolaridan,"}],full_uz:"Abbosiylar xonadonining biror a’zosi atrofida paydo bo‘lganida,",note:"الْبَيْتُ — bu yerda xonadon, sulola."},
{num:366,time:"00:26:45,839 --> 00:26:48,319",arabic:"لَمَا كَانَ جَزَاؤُهُ مِنْكَ إِلَّا الْمَوْتَ،",segs:[{ar:"لَمَا كَانَ جَزَاؤُهُ مِنْكَ",uz:"sizdan unga jazo bo‘lmas edi"},{ar:"إِلَّا الْمَوْتَ،",uz:"o‘limdan boshqa,"}],full_uz:"Siz unga faqat o‘lim jazosini bergan bo‘lardingiz,",note:"لَمَا bu yerda لَ ta’kidi va مَا inkoridan tuzilgan; oldingi لَوْ shartining javobi."},
{num:367,time:"00:26:48,319 --> 00:26:54,379",arabic:"وَلَكِنَّكَ يَا مَوْلَايَ لَا تَفْتَأُ تَغْفِرُ لِأَبْنَاءِ بَرْمَكٍ دَسَائِسَهُمْ،",segs:[{ar:"وَلَكِنَّكَ يَا مَوْلَايَ",uz:"Lekin siz, hazratim"},{ar:"لَا تَفْتَأُ تَغْفِرُ",uz:"kechirishdan to‘xtamaysiz"},{ar:"لِأَبْنَاءِ بَرْمَكٍ دَسَائِسَهُمْ،",uz:"Barmak avlodining fitnalarini,"}],full_uz:"Lekin siz, hazratim, Barmak avlodining fitnalarini kechiraverasiz,",note:"لَا تَفْتَأُ — hamon davom etasiz, to‘xtamaysiz. دَسَائِسُ — yashirin fitnalar."},
{num:368,time:"00:26:54,379 --> 00:26:56,179",arabic:"وَتَسْتُرُ عَلَيْهِمْ شَنَائِعَهُمْ.",segs:null,full_uz:"Va ularning qabih ishlarini yashirasiz.",note:"شَنَائِعُ — o‘ta yomon, qabih ishlar; birlik shakli شَنِيعَةٌ."},
{num:369,time:"00:26:56,180 --> 00:27:03,600",arabic:"إِنَّمَا شَأْنِي وَشَأْنُهُمْ يَا أَبَا الْعَبَّاسِ،",segs:[{ar:"إِنَّمَا شَأْنِي وَشَأْنُهُمْ",uz:"Men bilan ularning holi"},{ar:"يَا أَبَا الْعَبَّاسِ،",uz:"Abu Abbos,"}],full_uz:"Abu Abbos, men bilan ularning holi",note:"شَأْنِي وَشَأْنُهُمْ — mening va ularning o‘zaro holatimiz, munosabatimiz."},
{num:370,time:"00:27:03,600 --> 00:27:07,320",arabic:"كَمَا قَالَ الْمُثَقِّبُ الْعَبْدِيُّ:",segs:null,full_uz:"Musaqqib Abdiy aytganidek:",note:null},
{num:371,time:"00:27:07,320 --> 00:27:12,220",arabic:"فَإِمَّا أَنْ تَكُونَ أَخِي بِحَقٍّ،",segs:[{ar:"فَإِمَّا أَنْ تَكُونَ أَخِي",uz:"Yo mening birodarim bo‘l"},{ar:"بِحَقٍّ،",uz:"chinakamiga,"}],full_uz:"Yo chinakamiga mening birodarim bo‘l,",note:"إِمَّا — yo, yoki; muqobil holatlarni sanashni boshlaydi."},
{num:372,time:"00:27:12,220 --> 00:27:16,060",arabic:"فَأَعْرِفَ مِنْكَ غَثِّي مِنْ سَمِينِي،",segs:[{ar:"فَأَعْرِفَ مِنْكَ",uz:"toki sendan bilay"},{ar:"غَثِّي مِنْ سَمِينِي،",uz:"yomonimni yaxshimdan ajratib,"}],full_uz:"Toki sen orqali yomonimni yaxshimdan ajratib bilay,",note:"الْغَثُّ وَالسَّمِينُ — aslida oriq va semiz; ko‘chma ma’noda yomon va yaxshi, arzimas va qimmatli."},
{num:373,time:"00:27:16,060 --> 00:27:18,860",arabic:"وَإِلَّا فَاطَّرِحْنِي وَاتَّخِذْنِي،",segs:[{ar:"وَإِلَّا فَاطَّرِحْنِي",uz:"Aks holda, meni tashla"},{ar:"وَاتَّخِذْنِي،",uz:"va meni deb bil,"}],full_uz:"Aks holda, meni tashla va meni",note:"اطَّرَحَ — tashlab yubormoq, yuz o‘girmoq. اتَّخِذْنِي ning ikkinchi to‘ldiruvchisi keyingi parchada."},
{num:374,time:"00:27:18,860 --> 00:27:22,240",arabic:"عَدُوًّا أَتَّقِيكَ وَتَتَّقِينِي.",segs:[{ar:"عَدُوًّا",uz:"dushman deb bil"},{ar:"أَتَّقِيكَ",uz:"men sendan ehtiyot bo‘lay"},{ar:"وَتَتَّقِينِي.",uz:"sen mendan ehtiyot bo‘l."}],full_uz:"Dushman deb bil: men sendan, sen mendan ehtiyot bo‘laylik.",note:"اتَّقَى فُلَانًا — birovdan ehtiyot bo‘lmoq, uning zararidan saqlanmoq."},
{num:375,time:"00:27:39,380 --> 00:27:44,440",arabic:"السَّلَامُ عَلَيْكُمْ يَا أَخِي.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"Assalomu alaykum"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Assalomu alaykum, birodarim.",note:null},
{num:376,time:"00:27:44,440 --> 00:27:47,560",arabic:"عَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"عَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",uz:"Allohning rahmati va barakalari bo‘lsin."}],full_uz:"Va alaykum assalom va rahmatullohi va barakatuh.",note:null},
{num:377,time:"00:27:47,560 --> 00:27:50,220",arabic:"أَيْنَ أَنْتَ؟ مُنْذُ مُدَّةٍ وَأَنْتَ غَائِبٌ.",segs:[{ar:"أَيْنَ أَنْتَ؟",uz:"Qayerlarda yuribsiz?"},{ar:"مُنْذُ مُدَّةٍ وَأَنْتَ غَائِبٌ.",uz:"Anchadan beri ko‘rinmaysiz."}],full_uz:"Qayerlarda yuribsiz? Anchadan beri ko‘rinmaysiz.",note:"مُنْذُ مُدَّةٍ — bir muddatdan beri, anchadan beri."},
{num:378,time:"00:27:50,220 --> 00:27:52,180",arabic:"عَسَى أَنْ يَكُونَ الْمَانِعُ خَيْرًا.",segs:null,full_uz:"Kelishingizga to‘sqinlik qilgan sabab yaxshilik bo‘lsin.",note:"عَسَى أَنْ يَكُونَ الْمَانِعُ خَيْرًا — ko‘rinmay qolgan kishidan hol so‘rashda ishlatiladigan tilak."},
{num:379,time:"00:27:52,180 --> 00:27:55,180",arabic:"هُمُومُ الْحَيَاةِ وَالدُّنْيَا يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"هُمُومُ الْحَيَاةِ وَالدُّنْيَا",uz:"Hayot va dunyo tashvishlari"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ.",uz:"Ibn Abu Duod."}],full_uz:"Hayot va dunyo tashvishlari, Ibn Abu Duod.",note:"هُمُومٌ — هَمٌّ so‘zining ko‘pligi: tashvishlar."},
{num:380,time:"00:27:55,180 --> 00:27:58,140",arabic:"هُمُومُ الْحَيَاةِ لَا تَنْتَهِي يَا أَخِي.",segs:[{ar:"هُمُومُ الْحَيَاةِ لَا تَنْتَهِي",uz:"Hayot tashvishlari tugamaydi"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Hayot tashvishlari tugamaydi, birodarim.",note:"انْتَهَى يَنْتَهِي — tugamoq."},
{num:381,time:"00:27:58,140 --> 00:28:00,420",arabic:"هَلُمَّ بِنَا إِلَى الْبَيْتِ لِنُكْمِلَ حَدِيثَنَا.",segs:[{ar:"هَلُمَّ بِنَا إِلَى الْبَيْتِ",uz:"Yuring, uyga boraylik"},{ar:"لِنُكْمِلَ حَدِيثَنَا.",uz:"suhbatimizni davom ettirish uchun."}],full_uz:"Yuring, suhbatimizni davom ettirish uchun uyga boraylik.",note:"هَلُمَّ بِنَا — qani, birga boraylik."},
{num:382,time:"00:28:00,420 --> 00:28:02,259",arabic:"مَعْذِرَةً، فَأَنَا الْيَوْمَ مَشْغُولٌ.",segs:[{ar:"مَعْذِرَةً،",uz:"Uzr,"},{ar:"فَأَنَا الْيَوْمَ مَشْغُولٌ.",uz:"bugun bandman."}],full_uz:"Uzr, bugun bandman.",note:null},
{num:383,time:"00:28:02,259 --> 00:28:05,420",arabic:"كَأَنَّكَ تَتَحَاشَى الْحَدِيثَ مَعِي يَا ابْنَ نُوحٍ.",segs:[{ar:"كَأَنَّكَ تَتَحَاشَى",uz:"O‘zingizni olib qochayotganga o‘xshaysiz"},{ar:"الْحَدِيثَ مَعِي",uz:"men bilan gaplashishdan"},{ar:"يَا ابْنَ نُوحٍ.",uz:"Ibn Nuh."}],full_uz:"Men bilan gaplashishdan o‘zingizni olib qochayotganga o‘xshaysiz, Ibn Nuh.",note:"تَحَاشَى — chetlashmoq, o‘zini olib qochmoq."},
{num:384,time:"00:28:05,420 --> 00:28:10,360",arabic:"اصْدُقْنِي الْقَوْلَ، وَمَا عَهِدْتُكَ إِلَّا صَادِقًا.",segs:[{ar:"اصْدُقْنِي الْقَوْلَ،",uz:"Menga rostini ayting,"},{ar:"وَمَا عَهِدْتُكَ إِلَّا صَادِقًا.",uz:"sizni doim rostgo‘y deb bilganman."}],full_uz:"Menga rostini ayting. Sizni doim rostgo‘y deb bilganman.",note:"عَهِدْتُكَ — sizni shunday deb bilganman, shunday holatda taniganman."},
{num:385,time:"00:28:10,360 --> 00:28:13,799",arabic:"أَنَقَلَ الْوُشَاةُ شَيْئًا لَكَ عَنِّي أَغْضَبَكَ؟",segs:[{ar:"أَنَقَلَ الْوُشَاةُ شَيْئًا لَكَ عَنِّي",uz:"Gap tashuvchilar sizga men haqimda biror narsa yetkazdilarmi"},{ar:"أَغْضَبَكَ؟",uz:"sizni g‘azablantirgan?"}],full_uz:"Gap tashuvchilar sizga men haqimda g‘azabingizni keltiradigan biror narsa aytdilarmi?",note:"الْوُشَاةُ — gap tashuvchilar, chaqimchilar; birlik shakli وَاشٍ."},
{num:386,time:"00:28:13,799 --> 00:28:17,759",arabic:"كَأَنَّكَ تُخْفِي شَيْئًا عَنِّي.",segs:[{ar:"كَأَنَّكَ تُخْفِي شَيْئًا",uz:"Biror narsani yashirayotganga o‘xshaysiz"},{ar:"عَنِّي.",uz:"mendan."}],full_uz:"Mendan biror narsani yashirayotganga o‘xshaysiz.",note:"أَخْفَى عَنْ — ...dan yashirmoq."},
{num:387,time:"00:28:17,759 --> 00:28:21,440",arabic:"مَنْ؟ مَنِ الَّذِي يُخْفِي شَيْئًا يَا ابْنَ أَبِي دُؤَادٍ؟",segs:[{ar:"مَنْ؟",uz:"Kim?"},{ar:"مَنِ الَّذِي يُخْفِي شَيْئًا",uz:"Kim biror narsani yashiryapti"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ؟",uz:"Ibn Abu Duod?"}],full_uz:"Kim? Kim biror narsani yashiryapti, Ibn Abu Duod?",note:null},
{num:388,time:"00:28:21,440 --> 00:28:26,960",arabic:"لَمْ أَفْهَمْ مَا تَقْصِدُ يَا أَخِي.",segs:[{ar:"لَمْ أَفْهَمْ مَا تَقْصِدُ",uz:"Nimani nazarda tutayotganingizni tushunmadim"},{ar:"يَا أَخِي.",uz:"birodarim."}],full_uz:"Nimani nazarda tutayotganingizni tushunmadim, birodarim.",note:null},
{num:389,time:"00:28:26,960 --> 00:28:30,220",arabic:"كَفَاكَ مُرَاوَغَةً، فَأَنْتَ تَفْهَمُ مَا أَقْصِدُ.",segs:[{ar:"كَفَاكَ مُرَاوَغَةً،",uz:"Gapni aylantirishni bas qiling,"},{ar:"فَأَنْتَ تَفْهَمُ مَا أَقْصِدُ.",uz:"nimani nazarda tutayotganimni tushunyapsiz."}],full_uz:"Gapni aylantirishni bas qiling, nimani nazarda tutayotganimni tushunyapsiz.",note:"مُرَاوَغَةٌ — gapni aylantirish, to‘g‘ri javobdan qochish."},
{num:390,time:"00:28:30,220 --> 00:28:34,900",arabic:"لِمَاذَا تُخْفِي حَقِيقَةَ اعْتِقَادِكَ إِنْ كُنْتَ مُؤْمِنًا بِمَا تَعْتَقِدُ؟",segs:[{ar:"لِمَاذَا تُخْفِي حَقِيقَةَ اعْتِقَادِكَ",uz:"Nega asl e’tiqodingizni yashirasiz"},{ar:"إِنْ كُنْتَ مُؤْمِنًا",uz:"agar ishonadigan bo‘lsangiz"},{ar:"بِمَا تَعْتَقِدُ؟",uz:"o‘z e’tiqodingizga?"}],full_uz:"Agar o‘z e’tiqodingizga ishonsangiz, nega uni yashirasiz?",note:"حَقِيقَةُ اعْتِقَادِكَ — e’tiqodingizning asl mohiyati."},
{num:391,time:"00:28:34,900 --> 00:28:38,660",arabic:"مَهْلًا، مَهْلًا، مَهْلًا يَا أَخِي، مَهْلًا.",segs:[{ar:"مَهْلًا، مَهْلًا، مَهْلًا",uz:"Shoshmang, shoshmang, shoshmang"},{ar:"يَا أَخِي،",uz:"birodarim,"},{ar:"مَهْلًا.",uz:"shoshmang."}],full_uz:"Shoshmang, shoshmang, shoshmang, birodarim, shoshmang.",note:"مَهْلًا — shoshma, sekinroq; suhbatda tinchlanishga undash uchun ham ishlatiladi."},
{num:392,time:"00:28:38,660 --> 00:28:45,200",arabic:"مَا رَأْيُكَ أَنْ نُكْمِلَ حَدِيثَنَا فِي الْبَيْتِ وَيَسْمَعَ كُلٌّ مِنَ الْآخَرِ حُجَجَهُ؟",segs:[{ar:"مَا رَأْيُكَ",uz:"Nima deysiz"},{ar:"أَنْ نُكْمِلَ حَدِيثَنَا فِي الْبَيْتِ",uz:"suhbatimizni uyda davom ettirsak"},{ar:"وَيَسْمَعَ كُلٌّ مِنَ الْآخَرِ حُجَجَهُ؟",uz:"va har birimiz boshqasining dalillarini eshitsa?"}],full_uz:"Suhbatimizni uyda davom ettirib, bir-birimizning dalillarimizni eshitsak, nima deysiz?",note:"كُلٌّ مِنَ الْآخَرِ — har biri boshqasidan; كُلٌّ bu yerda har birimiz ma’nosida."},
{num:393,time:"00:28:45,200 --> 00:28:49,700",arabic:"لَا يَا ابْنَ أَبِي دُؤَادٍ، هَذَا فِرَاقٌ بَيْنِي وَبَيْنَكَ.",segs:[{ar:"لَا يَا ابْنَ أَبِي دُؤَادٍ،",uz:"Yo‘q, Ibn Abu Duod,"},{ar:"هَذَا فِرَاقٌ",uz:"bu ayriliqdir"},{ar:"بَيْنِي وَبَيْنَكَ.",uz:"men bilan sizning orangizdagi."}],full_uz:"Yo‘q, Ibn Abu Duod, shu bilan yo‘llarimiz ayriladi.",note:"فِرَاقٌ — ayriliq, ajralish."},
{num:394,time:"00:28:49,700 --> 00:28:59,740",arabic:"قَدِ ارْتَقَيْتَ مُرْتَقًى صَعْبًا.",segs:null,full_uz:"Qiyin bir balandlikka ko‘tarildingiz.",note:"ارْتَقَى — ko‘tarilmoq; مُرْتَقًى — ko‘tarilish joyi yoki yo‘li. Ko‘chma ma’noda qiyin ishga qo‘l urish."},
{num:395,time:"00:28:59,740 --> 00:29:01,840",arabic:"يَا طُولَ بَلَائِي!",segs:null,full_uz:"Voy, baloyimning uzunligini!",note:"يَا طُولَ... — bir holatning uzoq davom etayotganidan nolish yoki hayratlanish ifodasi."},
{num:396,time:"00:29:15,759 --> 00:29:17,000",arabic:"هَاتِ مَا عِنْدَكَ.",segs:null,full_uz:"Bor gapingni ayt.",note:"هَاتِ مَا عِنْدَكَ — o‘zingdagi ma’lumotni yoki aytadigan gapingni keltir."},
{num:397,time:"00:29:17,000 --> 00:29:21,220",arabic:"أَنْتَ تَعْرِفُ يَحْيَى بْنَ عَبْدِ اللَّهِ الطَّالِبِيَّ؟",segs:[{ar:"أَنْتَ تَعْرِفُ",uz:"Siz taniysizmi"},{ar:"يَحْيَى بْنَ عَبْدِ اللَّهِ الطَّالِبِيَّ؟",uz:"Yahyo ibn Abdulloh Tolibiyni?"}],full_uz:"Yahyo ibn Abdulloh Tolibiyni taniysizmi?",note:null},
{num:398,time:"00:29:21,220 --> 00:29:22,640",arabic:"مَا بِهِ؟",segs:null,full_uz:"Unga nima bo‘libdi?",note:null},
{num:399,time:"00:29:22,640 --> 00:29:25,279",arabic:"أَلَيْسَ حَبِيسًا فِي سِجْنِ جَعْفَرٍ الْبَرْمَكِيِّ؟",segs:[{ar:"أَلَيْسَ حَبِيسًا",uz:"U mahbus emasmi"},{ar:"فِي سِجْنِ جَعْفَرٍ الْبَرْمَكِيِّ؟",uz:"Ja’far Barmakiyning qamoqxonasida?"}],full_uz:"U Ja’far Barmakiyning qamoqxonasida mahbus emasmi?",note:"حَبِيسٌ — qamalgan, tutqun."},
{num:400,time:"00:29:25,279 --> 00:29:29,660",arabic:"يَبْدُو أَنَّ جَعْفَرًا الْبَرْمَكِيَّ وَيَحْيَى بْنَ عَبْدِ اللَّهِ الطَّالِبِيَّ،",segs:[{ar:"يَبْدُو أَنَّ جَعْفَرًا الْبَرْمَكِيَّ",uz:"Aftidan, Ja’far Barmakiy"},{ar:"وَيَحْيَى بْنَ عَبْدِ اللَّهِ الطَّالِبِيَّ،",uz:"va Yahyo ibn Abdulloh Tolibiy,"}],full_uz:"Aftidan, Ja’far Barmakiy bilan Yahyo ibn Abdulloh Tolibiy",note:"يَبْدُو أَنَّ — aftidan, ...ga o‘xshaydi. Fikr keyingi parchada tugallanadi."},
{num:401,time:"00:29:29,660 --> 00:29:32,140",arabic:"بَيْنَهُمَا صِلَةٌ وَثِيقَةٌ.",segs:null,full_uz:"O‘rtasida mustahkam aloqa bor.",note:"صِلَةٌ وَثِيقَةٌ — yaqin, mustahkam aloqa."},
{num:402,time:"00:29:44,140 --> 00:29:46,980",arabic:"كَيْفَ عَرَفْتَ ذَلِكَ؟ وَمَا دَلِيلُكَ عَلَيْهِ؟",segs:[{ar:"كَيْفَ عَرَفْتَ ذَلِكَ؟",uz:"Buni qanday bilding?"},{ar:"وَمَا دَلِيلُكَ عَلَيْهِ؟",uz:"Bunga qanday daliling bor?"}],full_uz:"Buni qanday bilding? Bunga qanday daliling bor?",note:null},
{num:403,time:"00:29:46,980 --> 00:29:54,700",arabic:"إِنَّ يَحْيَى وَإِنْ كَانَ فِي السِّجْنِ إِلَّا أَنَّ جَعْفَرًا حِينَ يَتَأَكَّدُ مِنْ مُغَادَرَةِ سُمَّارِهِ يَأْمُرُ بِإِحْضَارِ يَحْيَى.",segs:[{ar:"إِنَّ يَحْيَى وَإِنْ كَانَ فِي السِّجْنِ",uz:"Yahyo qamoqda bo‘lsa-da"},{ar:"إِلَّا أَنَّ جَعْفَرًا",uz:"Ja’far"},{ar:"حِينَ يَتَأَكَّدُ مِنْ مُغَادَرَةِ سُمَّارِهِ",uz:"tungi suhbatdoshlari ketganiga ishonch hosil qilgach"},{ar:"يَأْمُرُ بِإِحْضَارِ يَحْيَى.",uz:"Yahyoni olib kelishni buyuradi."}],full_uz:"Yahyo qamoqda bo‘lsa-da, Ja’far tungi suhbatdoshlari ketganiga ishonch hosil qilgach, uni olib kelishni buyuradi.",note:"سُمَّارٌ — kechasi suhbatlashib o‘tiradigan kishilar; birlik shakli سَامِرٌ."},
{num:404,time:"00:29:54,700 --> 00:29:59,980",arabic:"هَذَا فِي جَوٍّ شَدِيدِ التَّكَتُّمِ، وَيَظَلَّانِ سَاهِرَيْنِ حَتَّى صَلَاةِ الْفَجْرِ.",segs:[{ar:"هَذَا فِي جَوٍّ شَدِيدِ التَّكَتُّمِ،",uz:"Bu o‘ta maxfiy sharoitda bo‘ladi,"},{ar:"وَيَظَلَّانِ سَاهِرَيْنِ",uz:"ikkovlari bedor qoladilar"},{ar:"حَتَّى صَلَاةِ الْفَجْرِ.",uz:"bomdod namozigacha."}],full_uz:"Bu o‘ta maxfiy sharoitda bo‘ladi. Ikkovlari bomdod namozigacha bedor qoladilar.",note:"يَظَلَّانِ — ikkovlari davom etadilar; سَاهِرَيْنِ — ikkovi bedor holatda."},
{num:405,time:"00:30:00,579 --> 00:30:04,279",arabic:"ثُمَّ يُعِيدُهُ إِلَى مَا يَجِبُ أَنْ يَكُونَ فِيهِ، مَحْبَسِهِ.",segs:[{ar:"ثُمَّ يُعِيدُهُ",uz:"So‘ng uni qaytaradi"},{ar:"إِلَى مَا يَجِبُ أَنْ يَكُونَ فِيهِ،",uz:"bo‘lishi kerak bo‘lgan joyiga,"},{ar:"مَحْبَسِهِ.",uz:"qamoqxonasiga."}],full_uz:"So‘ng uni bo‘lishi kerak bo‘lgan joyiga — qamoqxonasiga qaytaradi.",note:"مَحْبَسٌ — qamoq joyi. أَعَادَ — qaytarmoq."},
{num:406,time:"00:30:04,279 --> 00:30:07,140",arabic:"أَوَاثِقٌ أَنْتَ مِنْ ذَلِكَ؟",segs:null,full_uz:"Bunga ishonching komilmi?",note:"وَاثِقٌ مِنْ — ...ga ishonchi komil."},
{num:407,time:"00:30:07,140 --> 00:30:09,039",arabic:"كَثِقَتِي فِي وُجُودِي أَمَامَكَ.",segs:[{ar:"كَثِقَتِي",uz:"Ishonchim kabi"},{ar:"فِي وُجُودِي أَمَامَكَ.",uz:"oldingizda turganimga."}],full_uz:"Oldingizda turganimga ishonganimdek.",note:"ثِقَةٌ — ishonch; كَـ — kabi."},
{num:408,time:"00:30:09,039 --> 00:30:10,980",arabic:"وَمَا الْحَدِيثُ الَّذِي يَدُورُ بَيْنَهُمَا؟",segs:[{ar:"وَمَا الْحَدِيثُ",uz:"Qanday suhbat"},{ar:"الَّذِي يَدُورُ بَيْنَهُمَا؟",uz:"ikkovining o‘rtasida bo‘ladi?"}],full_uz:"Ikkovi nima haqda gaplashadi?",note:"دَارَ بَيْنَهُمَا حَدِيثٌ — ular o‘rtasida suhbat bo‘ldi."},
{num:409,time:"00:30:10,980 --> 00:30:19,900",arabic:"لَا أَدْرِي، إِنَّ جَعْفَرًا لَا يَسْمَحُ لِأَحَدٍ مِنْ غِلْمَانِهِ أَوْ جَوَارِيهِ بِالدُّخُولِ إِلَيْهِ حِينَ يَكُونُ مَعَ يَحْيَى الطَّالِبِيِّ.",segs:[{ar:"لَا أَدْرِي،",uz:"Bilmayman,"},{ar:"إِنَّ جَعْفَرًا لَا يَسْمَحُ لِأَحَدٍ",uz:"Ja’far hech kimga ruxsat bermaydi"},{ar:"مِنْ غِلْمَانِهِ أَوْ جَوَارِيهِ",uz:"xizmatkor yigitlari yoki joriyalaridan"},{ar:"بِالدُّخُولِ إِلَيْهِ",uz:"oldiga kirishga"},{ar:"حِينَ يَكُونُ مَعَ يَحْيَى الطَّالِبِيِّ.",uz:"Yahyo Tolibiy bilan bo‘lganida."}],full_uz:"Bilmayman. Ja’far Yahyo Tolibiy bilan bo‘lganida xizmatkor yigitlari yoki joriyalaridan hech kimni oldiga kiritmaydi.",note:"سَمَحَ لِفُلَانٍ بِـ — bir kishiga ...ga ruxsat bermoq. غِلْمَانٌ — bu yerda xizmatkor yigitlar."},
{num:410,time:"00:30:19,900 --> 00:30:23,599",arabic:"وَهَلْ يَتَكَرَّرُ ذَلِكَ كَثِيرًا؟",segs:null,full_uz:"Bu tez-tez takrorlanadimi?",note:"تَكَرَّرَ — takrorlanmoq; كَرَّرَ — takrorlamoq."},
{num:411,time:"00:30:23,599 --> 00:30:24,960",arabic:"كُلَّ لَيْلَةٍ تَقْرِيبًا.",segs:null,full_uz:"Deyarli har kecha.",note:"تَقْرِيبًا — taxminan, bu yerda deyarli."},
{num:412,time:"00:30:24,960 --> 00:30:29,360",arabic:"أَلَيْسَ هُنَاكَ مِنْ حِيلَةٍ نَعْرِفُ بِهَا فَحْوَى مَا يَدُورُ بَيْنَهُمَا؟",segs:[{ar:"أَلَيْسَ هُنَاكَ مِنْ حِيلَةٍ",uz:"Biror chora yo‘qmi"},{ar:"نَعْرِفُ بِهَا",uz:"uning yordamida biladigan"},{ar:"فَحْوَى مَا يَدُورُ بَيْنَهُمَا؟",uz:"ikkovi o‘rtasidagi gapning mazmunini?"}],full_uz:"Ikkovi o‘rtasidagi gapning mazmunini bilishning biror chorasi yo‘qmi?",note:"فَحْوَى — mazmun, asosiy ma’no. حِيلَةٌ bu yerda chora, yo‘l ma’nosida."},
{num:413,time:"00:30:29,360 --> 00:30:39,299",arabic:"ذَلِكَ عَلَيْنَا مُحَالٌ، فَجَعْفَرٌ الْبَرْمَكِيُّ يُحِيطُ الْأَمْرَ بِسِيَاجٍ مِنَ التَّكَتُّمِ الشَّدِيدِ، وَقِلَّةٌ قَلِيلَةٌ مِنْ خَدَمِهِ يَدْرُونَ بِذَلِكَ.",segs:[{ar:"ذَلِكَ عَلَيْنَا مُحَالٌ،",uz:"Bu biz uchun imkonsiz,"},{ar:"فَجَعْفَرٌ الْبَرْمَكِيُّ يُحِيطُ الْأَمْرَ",uz:"chunki Ja’far Barmakiy bu ishni o‘rab olgan"},{ar:"بِسِيَاجٍ مِنَ التَّكَتُّمِ الشَّدِيدِ،",uz:"qat’iy maxfiylik devori bilan,"},{ar:"وَقِلَّةٌ قَلِيلَةٌ مِنْ خَدَمِهِ",uz:"xizmatkorlarining juda oz qismi"},{ar:"يَدْرُونَ بِذَلِكَ.",uz:"bundan xabardor."}],full_uz:"Bu biz uchun imkonsiz. Ja’far Barmakiy bu ishni qattiq sir tutadi. Xizmatkorlarining juda oz qismi bundan xabardor.",note:"سِيَاجٌ — to‘siq, devor; bu yerda sirni himoya qilish timsoli. قِلَّةٌ قَلِيلَةٌ — juda ozchilik."},
{num:414,time:"00:30:40,980 --> 00:30:52,799",arabic:"عَلَى الرَّغْمِ مِنْ كُلِّ هَذِهِ الْحِيطَةِ وَالْحَذَرِ،",segs:[{ar:"عَلَى الرَّغْمِ مِنْ",uz:"Qaramay"},{ar:"كُلِّ هَذِهِ الْحِيطَةِ وَالْحَذَرِ،",uz:"shuncha ehtiyotkorlik va hushyorlikka,"}],full_uz:"Shuncha ehtiyotkorlik va hushyorlikka qaramay,",note:"عَلَى الرَّغْمِ مِنْ — ...ga qaramay."},
{num:415,time:"00:30:52,799 --> 00:30:56,779",arabic:"أُرِيدُ مِنْكَ أَنْ تَعْرِفَ مَا يَدُورُ بَيْنَهُمَا بِدِقَّةٍ.",segs:[{ar:"أُرِيدُ مِنْكَ أَنْ تَعْرِفَ",uz:"Sendan bilib olishingni istayman"},{ar:"مَا يَدُورُ بَيْنَهُمَا",uz:"ular o‘rtasida nima bo‘layotganini"},{ar:"بِدِقَّةٍ.",uz:"aniq."}],full_uz:"Ular o‘rtasida nima bo‘layotganini aniq bilib olishingni istayman.",note:"بِدِقَّةٍ — aniq, puxtalik bilan."},
{num:416,time:"00:30:56,779 --> 00:30:58,980",arabic:"سَأَفْعَلُ ذَلِكَ يَا مَوْلَايَ.",segs:[{ar:"سَأَفْعَلُ ذَلِكَ",uz:"Buni qilaman"},{ar:"يَا مَوْلَايَ.",uz:"hazratim."}],full_uz:"Buni qilaman, hazratim.",note:null},
{num:417,time:"00:30:58,980 --> 00:31:09,860",arabic:"كَأَنَّكَ كُنْتَ تُرِيدُ أَنْ تُفْضِيَ إِلَيَّ بِشَيْءٍ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"كَأَنَّكَ كُنْتَ تُرِيدُ",uz:"Istayotgan edingiz shekilli"},{ar:"أَنْ تُفْضِيَ إِلَيَّ بِشَيْءٍ",uz:"menga biror gapni aytishni"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"Abu Abdulloh."}],full_uz:"Menga biror gapni aytmoqchi edingiz shekilli, Abu Abdulloh.",note:"أَفْضَى إِلَيْهِ بِـ — unga ichidagi gapini, sirini yoki fikrini aytmoq."},
{num:418,time:"00:31:09,859 --> 00:31:12,879",arabic:"أَجَلْ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:null,full_uz:"Ha, mo‘minlar amiri.",note:null},
{num:419,time:"00:31:12,879 --> 00:31:17,799",arabic:"كُنْتُ أُرِيدُ أَنْ أَسْتَأْذِنَكَ فِي الْعَوْدَةِ إِلَى أَهْلِي.",segs:[{ar:"كُنْتُ أُرِيدُ أَنْ أَسْتَأْذِنَكَ",uz:"Sizdan izn so‘ramoqchi edim"},{ar:"فِي الْعَوْدَةِ إِلَى أَهْلِي.",uz:"oilam oldiga qaytishga."}],full_uz:"Oilam oldiga qaytishga sizdan izn so‘ramoqchi edim.",note:"اسْتَأْذَنَهُ فِي — undan biror ish uchun ruxsat so‘ramoq."},
{num:420,time:"00:31:17,799 --> 00:31:21,199",arabic:"الْعَوْدَةِ إِلَى أَهْلِكَ؟",segs:null,full_uz:"Oilangiz oldiga qaytishga?",note:"Oldingi gapdagi فِي الْعَوْدَةِ birikmasi savol ohangida takrorlangan."},
{num:421,time:"00:31:21,199 --> 00:31:26,959",arabic:"وَهَلْ مَلِلْتَ الْبَقَاءَ مَعَنَا يَا أَبَا عَبْدِ اللَّهِ؟ مَلِلْتَ؟",segs:[{ar:"وَهَلْ مَلِلْتَ الْبَقَاءَ مَعَنَا",uz:"Biz bilan qolishdan zerikdingizmi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ؟",uz:"Abu Abdulloh?"},{ar:"مَلِلْتَ؟",uz:"Zerikdingizmi?"}],full_uz:"Biz bilan qolishdan zerikdingizmi, Abu Abdulloh? Zerikdingizmi?",note:"مَلَّ — zerikmoq; تَ qo‘shilganda shadda ochiladi: مَلِلْتَ."},
{num:422,time:"00:31:26,959 --> 00:31:32,959",arabic:"مَنْ ذَا يَمَلُّ الْبَقَاءَ فِي جِوَارِكُمْ وَصُحْبَتِكُمْ؟",segs:[{ar:"مَنْ ذَا يَمَلُّ الْبَقَاءَ",uz:"Kim ham qolishdan zerikadi"},{ar:"فِي جِوَارِكُمْ وَصُحْبَتِكُمْ؟",uz:"yoningizda va suhbatingizda?"}],full_uz:"Kim ham yoningizda va suhbatingizda bo‘lishdan zerikadi?",note:"مَنْ ذَا — kim ham?; savolni kuchaytiradi. صُحْبَةٌ — hamrohlik, birga bo‘lish."},
{num:423,time:"00:31:32,959 --> 00:31:35,439",arabic:"لَا يَا مَوْلَايَ، لَا، وَلَكِنْ...",segs:[{ar:"لَا يَا مَوْلَايَ،",uz:"Yo‘q, hazratim,"},{ar:"لَا، وَلَكِنْ...",uz:"yo‘q, lekin..."}],full_uz:"Yo‘q, hazratim, yo‘q, lekin...",note:null},
{num:424,time:"00:31:35,440 --> 00:31:39,960",arabic:"غَيْبَتِي طَالَتْ عَلَى أُمِّي وَزَوْجِي وَطِفْلِي،",segs:[{ar:"غَيْبَتِي طَالَتْ",uz:"Uzoqda bo‘lishim cho‘zildi"},{ar:"عَلَى أُمِّي وَزَوْجِي وَطِفْلِي،",uz:"onam, xotinim va bolam uchun,"}],full_uz:"Onam, xotinim va bolamdan uzoqda bo‘lishim cho‘zilib ketdi,",note:"غَيْبَةٌ — yo‘qlik, uzoqda bo‘lish; غِيبَةٌ esa g‘iybat degani. زَوْجٌ xotinga nisbatan ham ishlatiladi."},
{num:425,time:"00:31:39,960 --> 00:31:43,200",arabic:"وَاشْتَاقَتْ لِرُؤْيَتِهِمْ نَفْسِي.",segs:null,full_uz:"Ko‘nglim ularni ko‘rishni qo‘msadi.",note:"اشْتَاقَ لِـ — ...ni sog‘inmoq, qo‘msamoq. نَفْسِي gapning egasi."},
{num:426,time:"00:31:43,200 --> 00:31:45,900",arabic:"فَإِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ،",segs:null,full_uz:"Agar mo‘minlar amiri ma’qul ko‘rsalar,",note:"رَأَى bu yerda ma’qul ko‘rmoq, rozilik bildirmoq ma’nosida."},
{num:427,time:"00:31:45,900 --> 00:31:48,539",arabic:"خَرَجْتُ مِنَ الْغَدِ إِلَى مَكَّةَ الْمُكَرَّمَةِ.",segs:[{ar:"خَرَجْتُ مِنَ الْغَدِ",uz:"Ertagayoq yo‘lga chiqaman"},{ar:"إِلَى مَكَّةَ الْمُكَرَّمَةِ.",uz:"Makkai Mukarramaga."}],full_uz:"Ertagayoq Makkai Mukarramaga yo‘lga chiqaman.",note:"خَرَجْتُ shaklan o‘tgan zamon, lekin oldingi shartga javob bo‘lib, kelajakni bildiradi."},
{num:428,time:"00:31:48,539 --> 00:31:56,559",arabic:"أَمِيرُ الْمُؤْمِنِينَ سَيَقْمَعُ رَغْبَتَهُ فِي إِبْقَائِكَ إِلَى جَانِبِهِ نَاصِحًا وَأَمِينًا،",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ سَيَقْمَعُ رَغْبَتَهُ",uz:"Mo‘minlar amiri o‘z istagini tiyadi"},{ar:"فِي إِبْقَائِكَ إِلَى جَانِبِهِ",uz:"sizni yonida olib qolishdagi"},{ar:"نَاصِحًا وَأَمِينًا،",uz:"nasihatgo‘y va ishonchli kishi sifatida,"}],full_uz:"Mo‘minlar amiri sizni nasihatgo‘y va ishonchli kishi sifatida yonida olib qolish istagini tiyadi,",note:"قَمَعَ رَغْبَتَهُ — istagini bostirdi, o‘zini tiydi. إِبْقَاءٌ — olib qolish."},
{num:429,time:"00:31:56,559 --> 00:32:01,460",arabic:"وَابْنَ عَمٍّ يَمْلَأُ السَّمْعَ وَالْبَصَرَ فَضْلًا وَعِلْمًا.",segs:[{ar:"وَابْنَ عَمٍّ",uz:"va bir amakivachcha sifatida"},{ar:"يَمْلَأُ السَّمْعَ وَالْبَصَرَ",uz:"quloq va ko‘zni to‘ldiradigan"},{ar:"فَضْلًا وَعِلْمًا.",uz:"fazilat va ilm bilan."}],full_uz:"Va fazilati hamda ilmi bilan barchaning e’tiborini tortadigan qarindosh sifatida.",note:"يَمْلَأُ السَّمْعَ وَالْبَصَرَ — shuhrati va fazilatlari bilan barchaning e’tiborini tortadi. ابْنُ عَمٍّ uzoq nasab qarindoshiga ham aytiladi."},
{num:430,time:"00:32:01,460 --> 00:32:05,680",arabic:"لَنْ أَقِفَ بَيْنَكَ وَبَيْنَ مَا تُحِبُّ يَا مُحَمَّدُ.",segs:[{ar:"لَنْ أَقِفَ بَيْنَكَ وَبَيْنَ مَا تُحِبُّ",uz:"Siz bilan istagan narsangiz orasiga to‘siq bo‘lmayman"},{ar:"يَا مُحَمَّدُ.",uz:"Muhammad."}],full_uz:"Istagingizga to‘siq bo‘lmayman, Muhammad.",note:"وَقَفَ بَيْنَهُ وَبَيْنَ... — u bilan ...orasiga to‘siq bo‘lmoq."},
{num:431,time:"00:32:05,680 --> 00:32:09,539",arabic:"جَزَاكَ اللَّهُ كُلَّ خَيْرٍ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"جَزَاكَ اللَّهُ كُلَّ خَيْرٍ",uz:"Alloh sizni barcha yaxshiliklar bilan mukofotlasin"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ.",uz:"mo‘minlar amiri."}],full_uz:"Alloh sizni barcha yaxshiliklar bilan mukofotlasin, mo‘minlar amiri.",note:null},
{num:432,time:"00:32:09,539 --> 00:32:14,180",arabic:"وَأَنَا مَا زِلْتُ عِنْدَ رَغْبَتِي يَا أَبَا عَبْدِ اللَّهِ أَنْ تَلِيَ الْقَضَاءَ،",segs:[{ar:"وَأَنَا مَا زِلْتُ عِنْدَ رَغْبَتِي",uz:"Men esa hali ham istagimda turibman"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"Abu Abdulloh"},{ar:"أَنْ تَلِيَ الْقَضَاءَ،",uz:"qozilikni zimmanizga olishingizni,"}],full_uz:"Abu Abdulloh, qozilikni zimmanizga olishingizni hali ham istayman,",note:"وَلِيَ الْقَضَاءَ — qozilik vazifasini zimmasiga oldi. أَنْ تَلِيَ — zimmasiga olishi."},
{num:433,time:"00:32:14,180 --> 00:32:17,680",arabic:"إِنْ لَمْ يَكُنْ هُنَا فَفِي مَكَّةَ الْمُكَرَّمَةِ.",segs:[{ar:"إِنْ لَمْ يَكُنْ هُنَا",uz:"Bu yerda bo‘lmasa"},{ar:"فَفِي مَكَّةَ الْمُكَرَّمَةِ.",uz:"Makkai Mukarramada."}],full_uz:"Bu yerda bo‘lmasa, Makkai Mukarramada.",note:null},
{num:434,time:"00:32:17,680 --> 00:32:22,100",arabic:"وَأَنَا يَا أَمِيرَ الْمُؤْمِنِينَ مَا زِلْتُ عِنْدَ قَوْلِي،",segs:[{ar:"وَأَنَا يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"Men esa, mo‘minlar amiri"},{ar:"مَا زِلْتُ عِنْدَ قَوْلِي،",uz:"hali ham o‘z gapimda turibman,"}],full_uz:"Men esa, mo‘minlar amiri, hali ham o‘z gapimda turibman,",note:"مَا زِلْتُ عِنْدَ قَوْلِي — avvalgi fikrim o‘zgarmadi, gapimda turibman."},
{num:435,time:"00:32:22,100 --> 00:32:24,420",arabic:"الَّذِي قُلْتُ لَكَ مِنْ قَبْلُ،",segs:[{ar:"الَّذِي قُلْتُ لَكَ",uz:"sizga aytgan"},{ar:"مِنْ قَبْلُ،",uz:"ilgari,"}],full_uz:"Sizga ilgari aytgan gapimda,",note:"مِنْ قَبْلُ — ilgari; aniq vaqt aytilmagan."},
{num:436,time:"00:32:24,420 --> 00:32:26,860",arabic:"هَذَا إِذَا أَخَذْتَ بِقَوْلِي.",segs:[{ar:"هَذَا",uz:"Bu shunday bo‘ladi"},{ar:"إِذَا أَخَذْتَ بِقَوْلِي.",uz:"agar gapimni qabul qilsangiz."}],full_uz:"Albatta, agar gapimni qabul qilsangiz.",note:"أَخَذَ بِقَوْلِهِ — uning gapini qabul qildi, unga amal qildi."},
{num:437,time:"00:32:26,860 --> 00:32:30,840",arabic:"كَمَا تُحِبُّ وَتَرْضَى يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"كَمَا تُحِبُّ وَتَرْضَى",uz:"O‘zingiz istagan va rozi bo‘lganingizdek"},{ar:"يَا أَبَا عَبْدِ اللَّهِ.",uz:"Abu Abdulloh."}],full_uz:"O‘zingiz istagan va rozi bo‘lganingizdek bo‘lsin, Abu Abdulloh.",note:null},
{num:438,time:"00:32:30,839 --> 00:32:32,659",arabic:"كَمَا تُحِبُّ وَتَرْضَى.",segs:null,full_uz:"O‘zingiz istagan va rozi bo‘lganingizdek.",note:null},
{num:439,time:"00:32:32,659 --> 00:32:36,919",arabic:"وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ.",segs:[{ar:"وَلَوْ كُنْتَ فَظًّا",uz:"Agar qo‘pol bo‘lganingda"},{ar:"غَلِيظَ الْقَلْبِ",uz:"qattiqqo‘l, toshbag‘ir"},{ar:"لَانْفَضُّوا مِنْ حَوْلِكَ.",uz:"atrofingdan tarqalib ketgan bo‘lardilar."}],full_uz:"Agar qo‘pol va toshbag‘ir bo‘lganingda, atrofingdan tarqalib ketgan bo‘lardilar.",note:"فَظٌّ — qo‘pol; غَلِيظُ الْقَلْبِ — qattiq qalbli. انْفَضَّ — tarqalib ketmoq."},
{num:440,time:"00:32:36,919 --> 00:32:42,399",arabic:"لَيْتَكَ اكْتَفَيْتَ بِنُصْحِهِ وَلَمْ تَقْسُ عَلَيْهِ بِالْكَلَامِ يَا ابْنَ نُوحٍ.",segs:[{ar:"لَيْتَكَ اكْتَفَيْتَ بِنُصْحِهِ",uz:"Qaniydi unga nasihat qilish bilan kifoyalanganingizda"},{ar:"وَلَمْ تَقْسُ عَلَيْهِ بِالْكَلَامِ",uz:"va unga qattiq gapirmaganingizda"},{ar:"يَا ابْنَ نُوحٍ.",uz:"Ibn Nuh."}],full_uz:"Qaniydi nasihat qilish bilan kifoyalanib, unga qattiq gapirmaganingizda, Ibn Nuh.",note:"لَمْ تَقْسُ — qattiqqo‘llik qilmadingiz; تَقْسُو fe’lining oxirgi و harfi jazmda tushgan."},
{num:441,time:"00:32:42,399 --> 00:32:47,059",arabic:"رُبَّمَا أَعْمَاهُ غَضَبُهُ عَنْ مُرَاجَعَةِ نَفْسِهِ.",segs:[{ar:"رُبَّمَا أَعْمَاهُ غَضَبُهُ",uz:"Balki g‘azabi uning ko‘zini ko‘r qilgandir"},{ar:"عَنْ مُرَاجَعَةِ نَفْسِهِ.",uz:"o‘zini qayta ko‘rib chiqishdan."}],full_uz:"Balki g‘azabi uning o‘zini qayta ko‘rib chiqishiga to‘sqinlik qilgandir.",note:"أَعْمَاهُ عَنْ — biror narsani ko‘rish yoki anglashdan to‘sdi. مُرَاجَعَةُ النَّفْسِ — o‘zini tahlil qilish."},
{num:442,time:"00:32:47,059 --> 00:32:49,720",arabic:"إِنْ يَشَأِ اللَّهُ يَخْتِمْ عَلَى قَلْبِهِ.",segs:[{ar:"إِنْ يَشَأِ اللَّهُ",uz:"Alloh istasa"},{ar:"يَخْتِمْ عَلَى قَلْبِهِ.",uz:"uning qalbini muhrlaydi."}],full_uz:"Alloh istasa, uning qalbini muhrlaydi.",note:"إِنْ shartidan keyin يَشَأْ va uning javobi يَخْتِمْ jazmda keladi; ulab o‘qilganda يَشَأِ bo‘ladi."},
{num:443,time:"00:32:49,720 --> 00:32:53,699",arabic:"أَمَا رَأَيْتَ جَوَابَ صَاحِبِهِ بَدْرٍ وَلَمَّا يَتَوَغَّلْ فِي مَذْهَبِهِمْ بَعْدُ؟",segs:[{ar:"أَمَا رَأَيْتَ جَوَابَ صَاحِبِهِ بَدْرٍ",uz:"Uning do‘sti Badrning javobini ko‘rmadingizmi"},{ar:"وَلَمَّا يَتَوَغَّلْ فِي مَذْهَبِهِمْ بَعْدُ؟",uz:"hali ularning mazhabiga chuqur kirib bormagan bo‘lsa ham?"}],full_uz:"Hali ularning mazhabiga chuqur kirib bormagan do‘sti Badrning javobini ko‘rmadingizmi?",note:"لَمَّا ... بَعْدُ — hali ...gani yo‘q. تَوَغَّلَ فِي — ichkarilab, chuqur kirib bormoq."},
{num:444,time:"00:32:53,699 --> 00:32:58,459",arabic:"فَمَا ظَنُّكَ بِابْنِ أَبِي دُؤَادٍ وَهُوَ مَنْ هُوَ فِي الْعِلْمِ وَالِاعْتِدَادِ بِالنَّفْسِ؟",segs:[{ar:"فَمَا ظَنُّكَ بِابْنِ أَبِي دُؤَادٍ",uz:"Unda Ibn Abu Duod haqida nima deb o‘ylaysiz"},{ar:"وَهُوَ مَنْ هُوَ",uz:"uning qanchalik kuchli ekani ma’lum-ku"},{ar:"فِي الْعِلْمِ وَالِاعْتِدَادِ بِالنَّفْسِ؟",uz:"ilmda va o‘ziga bino qo‘yishda?"}],full_uz:"Ilmi va o‘ziga bino qo‘yishi ma’lum bo‘lgan Ibn Abu Duoddan esa nimani kutasiz?",note:"هُوَ مَنْ هُوَ — uning qandayligi ma’lum. الِاعْتِدَادُ بِالنَّفْسِ — o‘zini yuqori baholash, o‘ziga bino qo‘yish."},
{num:445,time:"00:32:58,460 --> 00:33:01,039",arabic:"إِنَّمَا جَاءَ بَلَاؤُهُمْ مِنْ هَذِهِ الْكُتُبِ،",segs:[{ar:"إِنَّمَا جَاءَ بَلَاؤُهُمْ",uz:"Ularning balosi kelgan"},{ar:"مِنْ هَذِهِ الْكُتُبِ،",uz:"aynan shu kitoblardan,"}],full_uz:"Ularning balosi aynan shu kitoblardan kelgan,",note:"بَلَاءٌ — balo, boshga tushgan sinov yoki kulfat."},
{num:446,time:"00:33:01,039 --> 00:33:03,160",arabic:"كُتُبِ فَلَاسِفَةِ الْيُونَانِ.",segs:null,full_uz:"Yunon faylasuflarining kitoblaridan.",note:"Bu parcha oldingi هَذِهِ الْكُتُبِ birikmasini izohlaydi."},
{num:447,time:"00:33:03,160 --> 00:33:07,160",arabic:"أَخَذُوهَا بِلَا نَظَرٍ وَطَبَّقُوا مَقَايِيسَهَا بِلَا وَعْيٍ،",segs:[{ar:"أَخَذُوهَا بِلَا نَظَرٍ",uz:"Ularni tekshirmasdan qabul qildilar"},{ar:"وَطَبَّقُوا مَقَايِيسَهَا",uz:"va ularning mezonlarini tatbiq etdilar"},{ar:"بِلَا وَعْيٍ،",uz:"anglamasdan,"}],full_uz:"Ularni tekshirmasdan qabul qilib, mezonlarini anglamasdan tatbiq etdilar,",note:"نَظَرٌ bu yerda tekshirish, mulohaza yuritish. وَعْيٌ — anglash."},
{num:448,time:"00:33:07,160 --> 00:33:10,059",arabic:"وَحَكَّمُوا عَلَى أُصُولِ الْعَقَائِدِ مَنَاهِجَ الْبَشَرِ.",segs:[{ar:"وَحَكَّمُوا",uz:"va hukm chiqaruvchi qildilar"},{ar:"عَلَى أُصُولِ الْعَقَائِدِ",uz:"aqida asoslari ustidan"},{ar:"مَنَاهِجَ الْبَشَرِ.",uz:"insonlarning usullarini."}],full_uz:"Aqida asoslari ustidan insonlarning usullarini hukm chiqaruvchi qildilar.",note:"حَكَّمَ — hakam yoki hukm mezoni qilib olmoq. مَنَاهِجُ — usullar, yo‘llar."},
{num:449,time:"00:33:10,059 --> 00:33:15,299",arabic:"وَلَوْ رَدُّوا أَمْرَهُمْ إِلَى آثَارِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ،",segs:[{ar:"وَلَوْ رَدُّوا أَمْرَهُمْ",uz:"Agar ishlarini qaytarganlarida"},{ar:"إِلَى آثَارِ رَسُولِ اللَّهِ",uz:"Allohning Rasulidan qolgan rivoyatlarga"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salavot va salom yo‘llasin"},{ar:"وَأَصْحَابِهِ،",uz:"va u zotning sahobalaridan,"}],full_uz:"Agar o‘z masalalarida Allohning Rasuli sollallohu alayhi vasallam va sahobalaridan qolgan rivoyatlarga murojaat qilganlarida,",note:"آثَارٌ — bu yerda oldingilardan qolgan rivoyatlar. رَدَّ أَمْرَهُ إِلَى — masalasini bir manbaga qaytarib hal qilmoq."},
{num:450,time:"00:33:15,299 --> 00:33:17,840",arabic:"لَكَانَ خَيْرًا لَهُمْ.",segs:null,full_uz:"O‘zlari uchun yaxshiroq bo‘lardi.",note:"لَكَانَ — oldingi لَوْ shartining javobi: bo‘lgan bo‘lardi."},
{num:451,time:"00:33:17,840 --> 00:33:21,500",arabic:"هَدَانَا اللَّهُ وَإِيَّاهُمْ إِلَى الْحَقِّ.",segs:[{ar:"هَدَانَا اللَّهُ وَإِيَّاهُمْ",uz:"Alloh bizni ham, ularni ham hidoyat qilsin"},{ar:"إِلَى الْحَقِّ.",uz:"haqqa."}],full_uz:"Alloh bizni ham, ularni ham haqqa hidoyat qilsin.",note:"إِيَّاهُمْ — ularni; ajratib aytiladigan tushum olmoshi."},
{num:452,time:"00:33:21,500 --> 00:33:23,340",arabic:"اللَّهُمَّ آمِينَ.",segs:null,full_uz:"Allohim, omin.",note:"آمِينَ — duoni qabul qilgin mazmunidagi so‘z."},
{num:453,time:"00:33:24,460 --> 00:33:28,860",arabic:"تَفَضَّلْ، أَهْلًا وَسَهْلًا.",segs:[{ar:"تَفَضَّلْ،",uz:"Marhamat,"},{ar:"أَهْلًا وَسَهْلًا.",uz:"xush kelibsiz."}],full_uz:"Marhamat, xush kelibsiz.",note:null},
{num:454,time:"00:33:28,860 --> 00:33:29,700",arabic:"تَفَضَّلْ.",segs:null,full_uz:"Marhamat.",note:null},
{num:455,time:"00:33:29,700 --> 00:33:37,200",arabic:"أَتَعْلَمُ يَا ابْنَ أَبِي دُؤَادٍ بِأَنَّنِي اسْتَغْرَبْتُ مُنْذُ الْبِدَايَةِ أَنَّ ابْنَ نُوحٍ يَخْتَلِفُ إِلَيْكَ؟",segs:[{ar:"أَتَعْلَمُ يَا ابْنَ أَبِي دُؤَادٍ",uz:"Bilasizmi, Ibn Abu Duod"},{ar:"بِأَنَّنِي اسْتَغْرَبْتُ مُنْذُ الْبِدَايَةِ",uz:"men boshidanoq hayron bo‘lgan edim"},{ar:"أَنَّ ابْنَ نُوحٍ يَخْتَلِفُ إِلَيْكَ؟",uz:"Ibn Nuhning siznikiga qatnashiga?"}],full_uz:"Ibn Abu Duod, Ibn Nuhning siznikiga qatnashiga boshidanoq hayron bo‘lganimni bilasizmi?",note:"اخْتَلَفَ إِلَيْهِ — uning oldiga qatnab turmoq."},
{num:456,time:"00:33:37,200 --> 00:33:40,579",arabic:"وَذَلِكَ لِعِلْمِي بِالْبَوْنِ الشَّاسِعِ بَيْنَكُمَا.",segs:[{ar:"وَذَلِكَ لِعِلْمِي",uz:"Bunga sabab bilishim edi"},{ar:"بِالْبَوْنِ الشَّاسِعِ بَيْنَكُمَا.",uz:"ikkovingiz o‘rtasidagi ulkan farqni."}],full_uz:"Bunga ikkovingiz o‘rtasidagi ulkan farqni bilishim sabab edi.",note:"الْبَوْنُ الشَّاسِعُ — juda katta farq, ulkan tafovut."},
{num:457,time:"00:33:40,579 --> 00:33:45,340",arabic:"صَاحِبُ الْمَنْهَجِ يَا بَدْرُ،",segs:[{ar:"صَاحِبُ الْمَنْهَجِ",uz:"Muayyan yo‘lni tutgan kishi"},{ar:"يَا بَدْرُ،",uz:"Badr,"}],full_uz:"Muayyan yo‘lni tutgan kishi, Badr,",note:"مَنْهَجٌ — yo‘l, usul, qarashlar tizimi."},
{num:458,time:"00:33:45,340 --> 00:33:48,440",arabic:"لَا يَحْرِمُ أَحَدًا مِنْ دَعْوَتِهِ،",segs:[{ar:"لَا يَحْرِمُ أَحَدًا",uz:"hech kimni mahrum qilmaydi"},{ar:"مِنْ دَعْوَتِهِ،",uz:"o‘z da’vatidan,"}],full_uz:"Hech kimni o‘z da’vatidan mahrum qilmaydi,",note:"حَرَمَهُ مِنْ — uni biror narsadan mahrum qilmoq."},
{num:459,time:"00:33:48,440 --> 00:33:52,880",arabic:"وَعَلَيْهِ كَذَلِكَ أَنْ يَبْرَعَ فِي اخْتِيَارِ مَنْ يَدْعُوهُمْ إِلَى مَذْهَبِهِ.",segs:[{ar:"وَعَلَيْهِ كَذَلِكَ أَنْ يَبْرَعَ",uz:"Shuningdek, u mohir bo‘lishi kerak"},{ar:"فِي اخْتِيَارِ مَنْ يَدْعُوهُمْ",uz:"da’vat qiladigan kishilarini tanlashda"},{ar:"إِلَى مَذْهَبِهِ.",uz:"o‘z mazhabiga."}],full_uz:"Shuningdek, o‘z mazhabiga da’vat qiladigan kishilarni tanlashda mohir bo‘lishi kerak.",note:"بَرَعَ فِي — bir ishda mohir bo‘lmoq, ustalik ko‘rsatmoq."},
{num:460,time:"00:33:52,880 --> 00:33:58,000",arabic:"لَقَدْ تَوَسَّمْتُ فِي الْبِدَايَةِ خَيْرًا أَنَّنِي أَسْتَطِيعُ هِدَايَتَهُ،",segs:[{ar:"لَقَدْ تَوَسَّمْتُ فِي الْبِدَايَةِ خَيْرًا",uz:"Boshida yaxshi umid qilgan edim"},{ar:"أَنَّنِي أَسْتَطِيعُ هِدَايَتَهُ،",uz:"uni yo‘lga sola olishimdan,"}],full_uz:"Boshida uni yo‘lga sola olishimga yaxshi umid qilgan edim,",note:"تَوَسَّمَ خَيْرًا — yaxshi alomat ko‘rib, yaxshilik kutmoq."},
{num:461,time:"00:33:58,000 --> 00:34:02,440",arabic:"لَكِنَّهُ قَدْ خَانَنِي تَقْدِيرِي وَدَفَعْتُ الثَّمَنَ.",segs:[{ar:"لَكِنَّهُ قَدْ خَانَنِي تَقْدِيرِي",uz:"Lekin hisobim xato chiqdi"},{ar:"وَدَفَعْتُ الثَّمَنَ.",uz:"va buning badalini to‘ladim."}],full_uz:"Lekin hisobim xato chiqdi va buning badalini to‘ladim.",note:"خَانَنِي تَقْدِيرِي — baholashim xato chiqdi. دَفَعَ الثَّمَنَ — ko‘chma ma’noda oqibatini tortmoq."},
{num:462,time:"00:34:02,440 --> 00:34:06,860",arabic:"لَا بَأْسَ يَا بَدْرُ، لَا بَأْسَ.",segs:[{ar:"لَا بَأْسَ يَا بَدْرُ،",uz:"Hechqisi yo‘q, Badr,"},{ar:"لَا بَأْسَ.",uz:"hechqisi yo‘q."}],full_uz:"Hechqisi yo‘q, Badr, hechqisi yo‘q.",note:"لَا بَأْسَ — zarari yo‘q, hechqisi yo‘q."},
{num:463,time:"00:34:06,860 --> 00:34:11,559",arabic:"قَدْ أُوذِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَكْثَرَ مِنْ ذَلِكَ،",segs:[{ar:"قَدْ أُوذِيَ رَسُولُ اللَّهِ",uz:"Allohning Rasuliga ozor yetkazilgan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salavot va salom yo‘llasin"},{ar:"بِأَكْثَرَ مِنْ ذَلِكَ،",uz:"bundan ham ko‘proq,"}],full_uz:"Allohning Rasuli sollallohu alayhi vasallamga bundan ham ko‘proq ozor yetkazilgan,",note:"أُوذِيَ — unga ozor yetkazildi; آذَى fe’lining majhul shakli."},
{num:464,time:"00:34:11,559 --> 00:34:17,019",arabic:"فَمَا أَثْنَاهُ هَذَا عَنْ إِكْمَالِ رِسَالَتِهِ فِي هِدَايَةِ الْبَشَرِ.",segs:[{ar:"فَمَا أَثْنَاهُ هَذَا",uz:"Bu u zotni qaytarmagan"},{ar:"عَنْ إِكْمَالِ رِسَالَتِهِ",uz:"vazifasini oxiriga yetkazishdan"},{ar:"فِي هِدَايَةِ الْبَشَرِ.",uz:"insonlarni hidoyatga boshlashdagi."}],full_uz:"Bu u zotni insonlarni hidoyatga boshlash vazifasini oxiriga yetkazishdan qaytarmagan.",note:"أَثْنَاهُ عَنْ — uni bir ishdan qaytarmoq, niyatidan voz kechirmoq."},
{num:465,time:"00:34:18,840 --> 00:34:24,260",arabic:"إِنَّنِي أَتَعَلَّمُ مِنْكُمْ أَشْيَاءَ مَا كُنْتُ لِأَتَعَلَّمَهَا لَوْ لَمْ أَعْرِفْكَ.",segs:[{ar:"إِنَّنِي أَتَعَلَّمُ مِنْكُمْ أَشْيَاءَ",uz:"Men sizlardan shunday narsalarni o‘rganyapmanki"},{ar:"مَا كُنْتُ لِأَتَعَلَّمَهَا",uz:"ularni o‘rgana olmagan bo‘lardim"},{ar:"لَوْ لَمْ أَعْرِفْكَ.",uz:"sizni tanimaganimda."}],full_uz:"Sizni tanimaganimda o‘rgana olmagan narsalarni sizlardan o‘rganyapman.",note:"مَا كُنْتُ لِأَفْعَلَ — buni qilmagan bo‘lardim; لِ inkorni kuchaytiradi."},
{num:466,time:"00:34:24,260 --> 00:34:28,860",arabic:"وَلَكِنَّنِي أَسْتَغْرِبُ عَدَمَ اخْتِلَافِكَ إِلَى شُيُوخِنَا،",segs:[{ar:"وَلَكِنَّنِي أَسْتَغْرِبُ",uz:"Lekin men hayron bo‘laman"},{ar:"عَدَمَ اخْتِلَافِكَ إِلَى شُيُوخِنَا،",uz:"shayxlarimiz huzuriga qatnamasligingizga,"}],full_uz:"Lekin shayxlarimiz huzuriga qatnamasligingizga hayron bo‘laman,",note:"اخْتِلَافٌ إِلَى — bir joyga qatnab turish; bu yerda kelishmovchilik ma’nosida emas."},
{num:467,time:"00:34:28,860 --> 00:34:33,019",arabic:"عَلَى الرَّغْمِ مِنْ أَنَّهُمْ يُشِيدُونَ بِذَكَائِكَ وَحُسْنِ بَيَانِكَ.",segs:[{ar:"عَلَى الرَّغْمِ مِنْ أَنَّهُمْ يُشِيدُونَ",uz:"Ular maqtashlariga qaramay"},{ar:"بِذَكَائِكَ وَحُسْنِ بَيَانِكَ.",uz:"aqlingiz va chiroyli bayoningizni."}],full_uz:"Ular aqlingiz va chiroyli bayoningizni maqtashlariga qaramay.",note:"أَشَادَ بِـ — maqtamoq, yuksak baholamoq. حُسْنُ الْبَيَانِ — fikrni chiroyli va ravshan ifodalash."},
{num:468,time:"00:34:33,019 --> 00:34:35,800",arabic:"اتَّفَقْنَا فِي الْمَنْهَجِ يَا بَدْرُ،",segs:[{ar:"اتَّفَقْنَا فِي الْمَنْهَجِ",uz:"Asosiy yo‘nalishda kelishganmiz"},{ar:"يَا بَدْرُ،",uz:"Badr,"}],full_uz:"Asosiy yo‘nalishda kelishganmiz, Badr,",note:"اتَّفَقَ فِي — bir masalada hamfikr bo‘lmoq."},
{num:469,time:"00:34:35,800 --> 00:34:38,400",arabic:"وَاخْتَلَفْنَا فِي الطَّرِيقَةِ وَالْأُسْلُوبِ.",segs:null,full_uz:"Lekin yo‘l va uslubda farqlanamiz.",note:"اخْتَلَفْنَا فِي — ...borasida fikrimiz yoki yo‘limiz farq qiladi."},
{num:470,time:"00:34:38,400 --> 00:34:42,180",arabic:"كَيْفَ ذَلِكَ يَا ابْنَ أَبِي دُؤَادٍ؟",segs:[{ar:"كَيْفَ ذَلِكَ",uz:"Bu qanday"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ؟",uz:"Ibn Abu Duod?"}],full_uz:"Bu qanday, Ibn Abu Duod?",note:null},
{num:471,time:"00:34:42,180 --> 00:34:45,720",arabic:"الشَّيْخُ الْمَرِيسِيُّ وَأَتْبَاعُهُ يُخَاطِرُونَ كَثِيرًا،",segs:[{ar:"الشَّيْخُ الْمَرِيسِيُّ وَأَتْبَاعُهُ",uz:"Shayx Marisiy va uning izdoshlari"},{ar:"يُخَاطِرُونَ كَثِيرًا،",uz:"o‘zlarini katta xavfga qo‘ymoqdalar,"}],full_uz:"Shayx Marisiy va uning izdoshlari o‘zlarini katta xavfga qo‘ymoqdalar,",note:"خَاطَرَ — tavakkal qilmoq, o‘zini xavfga qo‘ymoq."},
{num:472,time:"00:34:45,719 --> 00:34:49,959",arabic:"وَهُمْ يَرَوْنَ هَارُونَ الرَّشِيدَ وَهُوَ يُصِرُّ فِي طَلَبِهِمْ،",segs:[{ar:"وَهُمْ يَرَوْنَ هَارُونَ الرَّشِيدَ",uz:"Ular Horun ar-Rashidni ko‘rib turibdilar"},{ar:"وَهُوَ يُصِرُّ فِي طَلَبِهِمْ،",uz:"ularni qidirishda qat’iy turayotganini,"}],full_uz:"Horun ar-Rashid ularni qat’iy izlayotganini ko‘rib turib ham,",note:"طَلَبُهُمْ bu yerda ularni qidirish, qo‘lga olishga intilish ma’nosida."},
{num:473,time:"00:34:49,959 --> 00:34:54,599",arabic:"وَأَنَا هُنَا لَا أَرَى أَيَّ مُسَوِّغٍ لِهَذِهِ الْمُخَاطَرَةِ،",segs:[{ar:"وَأَنَا هُنَا لَا أَرَى أَيَّ مُسَوِّغٍ",uz:"Men bunda hech qanday asos ko‘rmayapman"},{ar:"لِهَذِهِ الْمُخَاطَرَةِ،",uz:"bunday tavakkal uchun,"}],full_uz:"Men bunday tavakkal uchun hech qanday asos ko‘rmayapman,",note:"مُسَوِّغٌ — bir ishni oqlaydigan sabab, asos."},
{num:474,time:"00:34:54,599 --> 00:34:57,779",arabic:"وَلَكِنِ الْحَذَرُ وَاجِبٌ.",segs:null,full_uz:"Lekin ehtiyot bo‘lish zarur.",note:"الْحَذَرُ — ehtiyotkorlik; وَاجِبٌ — zarur, lozim."},
{num:475,time:"00:34:57,779 --> 00:35:08,119",arabic:"وَأَنَا هُنَا لَا أُنْكِرُ جُهْدَ الشُّرَفَاءِ الَّذِينَ يُحَاوِلُونَ حَمْلَ هَذِهِ الدَّعْوَةِ وَنَشْرَهَا كَأَمْثَالِكَ.",segs:[{ar:"وَأَنَا هُنَا لَا أُنْكِرُ",uz:"Men bu o‘rinda inkor qilmayman"},{ar:"جُهْدَ الشُّرَفَاءِ",uz:"olijanob kishilarning mehnatini"},{ar:"الَّذِينَ يُحَاوِلُونَ حَمْلَ هَذِهِ الدَّعْوَةِ",uz:"bu da’vatni olib borishga urinayotgan"},{ar:"وَنَشْرَهَا",uz:"va uni yoyishga"},{ar:"كَأَمْثَالِكَ.",uz:"senga o‘xshagan."}],full_uz:"Men bu da’vatni olib borish va yoyishga urinayotgan senga o‘xshash olijanob kishilarning mehnatini inkor qilmayman.",note:"حَمْلُ الدَّعْوَةِ — da’vat mas’uliyatini zimmasiga olish, uni olib borish."},
{num:476,time:"00:35:08,119 --> 00:35:12,519",arabic:"ثَنَاؤُكَ هَذَا وِسَامٌ عَلَى صَدْرِي وَتَاجٌ فَوْقَ رَأْسِي.",segs:[{ar:"ثَنَاؤُكَ هَذَا",uz:"Bu maqtovingiz"},{ar:"وِسَامٌ عَلَى صَدْرِي",uz:"ko‘ksimdagi nishondir"},{ar:"وَتَاجٌ فَوْقَ رَأْسِي.",uz:"va boshimdagi tojdir."}],full_uz:"Bu maqtovingiz ko‘ksimdagi nishon va boshimdagi tojdir.",note:"وِسَامٌ — mukofot nishoni, orden. Gap maqtovning katta sharaf ekanini ifodalaydi."},
{num:477,time:"00:35:12,519 --> 00:35:14,960",arabic:"وَلَكِنْ...",segs:null,full_uz:"Lekin...",note:null},
{num:478,time:"00:35:16,159 --> 00:35:19,519",arabic:"وَلَكِنْ مَاذَا يَا بَدْرُ؟",segs:[{ar:"وَلَكِنْ مَاذَا",uz:"Lekin nima"},{ar:"يَا بَدْرُ؟",uz:"Badr?"}],full_uz:"Lekin nima, Badr?",note:null},
{num:479,time:"00:35:20,519 --> 00:35:24,259",arabic:"لَسْتُ مُرْتَاحًا لِبَقَائِكَ فِي مَنْزِلِ مُحَمَّدِ بْنِ نُوحٍ هَذَا،",segs:[{ar:"لَسْتُ مُرْتَاحًا لِبَقَائِكَ",uz:"Qolishingizdan ko‘nglim tinch emas"},{ar:"فِي مَنْزِلِ مُحَمَّدِ بْنِ نُوحٍ هَذَا،",uz:"bu Muhammad ibn Nuhning uyida,"}],full_uz:"Bu Muhammad ibn Nuhning uyida qolishingizdan ko‘nglim tinch emas,",note:"مُرْتَاحٌ لِـ — ...dan ko‘ngli xotirjam, mamnun."},
{num:480,time:"00:35:24,259 --> 00:35:26,820",arabic:"وَخَاصَّةً بَعْدَ أَنْ حَدَثَ مَا حَدَثَ.",segs:[{ar:"وَخَاصَّةً",uz:"ayniqsa"},{ar:"بَعْدَ أَنْ حَدَثَ مَا حَدَثَ.",uz:"bo‘lib o‘tgan voqealardan keyin."}],full_uz:"Ayniqsa, bo‘lib o‘tgan voqealardan keyin.",note:"حَدَثَ مَا حَدَثَ — bo‘lgan ish bo‘ldi; tafsiloti ma’lum voqeani qayta sanamasdan eslatadi."},
{num:481,time:"00:35:26,820 --> 00:35:28,219",arabic:"لَا تَقْلَقْ يَا بَدْرُ.",segs:[{ar:"لَا تَقْلَقْ",uz:"Xavotir olma"},{ar:"يَا بَدْرُ.",uz:"Badr."}],full_uz:"Xavotir olma, Badr.",note:null},
{num:482,time:"00:35:28,219 --> 00:35:29,519",arabic:"لَا تَقْلَقْ.",segs:null,full_uz:"Xavotir olma.",note:null},
{num:483,time:"00:35:29,519 --> 00:35:32,579",arabic:"سَأَبْحَثُ عَنْ بَيْتٍ غَيْرِهِ.",segs:null,full_uz:"Boshqa uy izlayman.",note:"بَيْتٍ غَيْرِهِ — undan boshqa uy."},
{num:484,time:"00:35:32,579 --> 00:35:35,820",arabic:"فَلَا يَسُرُّنِي أَنْ يَسْكُنَ ابْنُ أَبِي دُؤَادٍ،",segs:[{ar:"فَلَا يَسُرُّنِي",uz:"Meni xursand qilmaydi"},{ar:"أَنْ يَسْكُنَ ابْنُ أَبِي دُؤَادٍ،",uz:"Ibn Abu Duodning yashashi,"}],full_uz:"Ibn Abu Duodning yashashi menga ma’qul emas,",note:"لَا يَسُرُّنِي — meni xursand qilmaydi, menga yoqmaydi. Fikr keyingi parchada tugallanadi."},
{num:485,time:"00:35:35,820 --> 00:35:37,920",arabic:"دَارَ جَهَالَةٍ وَضَلَالٍ.",segs:null,full_uz:"Johillik va adashish uyida.",note:"جَهَالَةٌ — johillik; ضَلَالٌ — yo‘ldan adashish."},
{num:486,time:"00:35:42,519 --> 00:35:46,079",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"Sizlarga ham salom"},{ar:"وَرَحْمَةُ اللَّهِ.",uz:"va Allohning rahmati bo‘lsin."}],full_uz:"Va alaykum assalom va rahmatulloh.",note:null},
{num:487,time:"00:36:12,519 --> 00:36:21,360",arabic:"أُقَلِّبُ طَرْفِي فَوْقَ رَحْلِي فَلَا أَرَى بِهِ مِنْ عُيُونِ الْمُؤْنِسَاتِ مُرَاعِيَا.",segs:[{ar:"أُقَلِّبُ طَرْفِي",uz:"Nigohimni aylantiraman"},{ar:"فَوْقَ رَحْلِي",uz:"safar o‘rnim ustida"},{ar:"فَلَا أَرَى بِهِ",uz:"lekin u yerda ko‘rmayman"},{ar:"مِنْ عُيُونِ الْمُؤْنِسَاتِ مُرَاعِيَا.",uz:"mehribon ayollarning menga qarab turgan biror nigohini."}],full_uz:"Safar o‘rnimga ko‘z yugurtiraman, ammo menga mehr bilan qarab turgan ayollardan biror nigoh ko‘rmayman.",note:"طَرْفٌ — nigoh, ko‘z. رَحْلٌ — safar anjomi yoki yo‘lovchining turar joyi. مُرَاعِيَا oxiridagi ا she’riy qofiya uchun kelgan."},
{num:488,time:"00:36:21,360 --> 00:36:26,860",arabic:"وَبِالرَّمْلِ مِنِّي نِسْوَةٌ لَوْ شَهِدْنَنِي،",segs:[{ar:"وَبِالرَّمْلِ مِنِّي نِسْوَةٌ",uz:"Raml degan joyda menga yaqin ayollar bor"},{ar:"لَوْ شَهِدْنَنِي،",uz:"agar ular meni ko‘rganlarida,"}],full_uz:"Raml degan joyda menga yaqin ayollar bor; agar ular meni ko‘rganlarida,",note:"نِسْوَةٌ — bir guruh ayollar. شَهِدْنَنِي — ular, ya’ni ayollar meni ko‘rdilar."},
{num:489,time:"00:36:26,860 --> 00:36:32,360",arabic:"بَكَيْنَ وَفَدَّيْنَ الطَّبِيبَ الْمُدَاوِيَا.",segs:[{ar:"بَكَيْنَ",uz:"yig‘lagan bo‘lardilar"},{ar:"وَفَدَّيْنَ الطَّبِيبَ الْمُدَاوِيَا.",uz:"va davolovchi tabibga jonimiz fido degan bo‘lardilar."}],full_uz:"Yig‘lab, davolovchi tabibga jonimiz fido degan bo‘lardilar.",note:"فَدَّى فُلَانًا — unga jonim fido mazmunida murojaat qildi. الْمُدَاوِيَا — she’riy shakl; odatiy shakli الْمُدَاوِيَ."},
{num:490,time:"00:36:32,360 --> 00:36:38,759",arabic:"فَمِنْهُنَّ أُمِّي وَابْنَتَاهَا وَخَالَتِي،",segs:[{ar:"فَمِنْهُنَّ أُمِّي",uz:"Ular orasida onam bor"},{ar:"وَابْنَتَاهَا وَخَالَتِي،",uz:"uning ikki qizi va xolam ham,"}],full_uz:"Ular orasida onam, uning ikki qizi va xolam bor,",note:"ابْنَتَاهَا — uning ikki qizi; ikkilik shakli egalik qo‘shimchasi bilan kelgan."},
{num:491,time:"00:36:38,760 --> 00:36:44,760",arabic:"وَبَاكِيَةٌ أُخْرَى تُهَيِّجُ الْبَوَاكِيَا.",segs:[{ar:"وَبَاكِيَةٌ أُخْرَى",uz:"yana bir yig‘lovchi ayol"},{ar:"تُهَيِّجُ الْبَوَاكِيَا.",uz:"boshqa yig‘lovchilarning ham yig‘isini kuchaytiradigan."}],full_uz:"Yana boshqalarning yig‘isini ham kuchaytiradigan bir yig‘lovchi ayol bor.",note:"تُهَيِّجُ — qo‘zg‘atadi, kuchaytiradi. الْبَوَاكِي — yig‘layotgan ayollar."},
{num:492,time:"00:37:08,760 --> 00:37:25,520",arabic:"مَا بِكَ يَا وَلَدِي؟",segs:[{ar:"مَا بِكَ",uz:"Senga nima bo‘ldi"},{ar:"يَا وَلَدِي؟",uz:"bolam?"}],full_uz:"Senga nima bo‘ldi, bolam?",note:null},
{num:493,time:"00:37:25,520 --> 00:37:28,080",arabic:"لِمَاذَا كُلُّ هَذَا الشُّرُودِ وَالْقَلَقِ؟",segs:null,full_uz:"Nega bunchalik parishon va xavotirdasan?",note:"شُرُودٌ — xayolning chalg‘ishi, parishonlik; قَلَقٌ — xavotir."},
{num:494,time:"00:37:28,080 --> 00:37:32,520",arabic:"لَا شَيْءَ يَا أُمِّي، لَا شَيْءَ.",segs:[{ar:"لَا شَيْءَ يَا أُمِّي،",uz:"Hech narsa, onajon,"},{ar:"لَا شَيْءَ.",uz:"hech narsa."}],full_uz:"Hech narsa, onajon, hech narsa.",note:null},
{num:495,time:"00:37:32,520 --> 00:37:37,760",arabic:"مُنْذُ مَتَى تُخْفِي عَنْ أُمِّكَ مَا تُفَكِّرُ فِيهِ يَا وَلَدِي؟",segs:[{ar:"مُنْذُ مَتَى تُخْفِي عَنْ أُمِّكَ",uz:"Qachondan beri onangdan yashirasan"},{ar:"مَا تُفَكِّرُ فِيهِ",uz:"nima haqida o‘ylayotganingni"},{ar:"يَا وَلَدِي؟",uz:"bolam?"}],full_uz:"Qachondan beri nima haqida o‘ylayotganingni onangdan yashiradigan bo‘lding, bolam?",note:"فَكَّرَ فِي — ...haqida o‘ylamoq; أَخْفَى عَنْ — ...dan yashirmoq."},
{num:496,time:"00:37:37,760 --> 00:37:42,240",arabic:"أَمْ أَنَّ الْأُمُورَ تَغَيَّرَتْ وَدَارَتْ بِكَ الْأَيَّامُ،",segs:[{ar:"أَمْ أَنَّ الْأُمُورَ تَغَيَّرَتْ",uz:"Yoki ishlar o‘zgardimi"},{ar:"وَدَارَتْ بِكَ الْأَيَّامُ،",uz:"kunlar seni o‘zgartirdimi,"}],full_uz:"Yoki ishlar o‘zgarib, kunlar seni ham o‘zgartirdimi,",note:"دَارَتْ بِهِ الْأَيَّامُ — vaqt o‘tib uning holati o‘zgardi, boshidan turli kunlar o‘tdi."},
{num:497,time:"00:37:42,240 --> 00:37:46,420",arabic:"وَأَصْبَحَتْ لَكَ أَسْرَارُكَ الَّتِي تُخْفِيهَا عَنْ أُمِّكَ؟",segs:[{ar:"وَأَصْبَحَتْ لَكَ أَسْرَارُكَ",uz:"O‘zingga xos sirlaring paydo bo‘ldimi"},{ar:"الَّتِي تُخْفِيهَا عَنْ أُمِّكَ؟",uz:"onangdan yashiradigan?"}],full_uz:"Onangdan yashiradigan o‘zingga xos sirlaring paydo bo‘ldimi?",note:"أَسْرَارٌ — سِرٌّ so‘zining ko‘pligi: sirlar."},
{num:498,time:"00:37:46,420 --> 00:37:49,780",arabic:"وَلَدُكِ هُوَ وَلَدُكِ يَا أُمَّاهُ.",segs:[{ar:"وَلَدُكِ هُوَ وَلَدُكِ",uz:"O‘g‘lingiz o‘sha o‘g‘lingiz"},{ar:"يَا أُمَّاهُ.",uz:"onajon."}],full_uz:"O‘g‘lingiz o‘sha-o‘sha, onajon.",note:"Bir so‘zning shu tarzda takrorlanishi kishining o‘zgarmaganini ta’kidlaydi."},
{num:499,time:"00:37:49,780 --> 00:37:52,020",arabic:"الْأَمْرُ لَيْسَ كَمَا تَظُنِّينَ.",segs:null,full_uz:"Gap siz o‘ylagandek emas.",note:"تَظُنِّينَ — sen o‘ylaysan; ayol kishiga murojaat shakli."},
{num:500,time:"00:37:52,020 --> 00:37:56,300",arabic:"كُلُّ مَا فِي الْأَمْرِ أَنَّنِي أُحِسُّ أَنَّ نَفْسِي قَدْ شَبِعَتْ،",segs:[{ar:"كُلُّ مَا فِي الْأَمْرِ",uz:"Bor gap shuki"},{ar:"أَنَّنِي أُحِسُّ",uz:"men his qilyapman"},{ar:"أَنَّ نَفْسِي قَدْ شَبِعَتْ،",uz:"ko‘nglim to‘yganini,"}],full_uz:"Bor gap shuki, ko‘nglim to‘yganini his qilyapman,",note:"شَبِعَتْ نَفْسِي — ko‘nglim to‘ydi; bu yerda ma’lum manbadan yetarlicha bilim olganlik."},
{num:501,time:"00:37:56,300 --> 00:37:59,220",arabic:"وَعَقْلِي قَدِ امْتَلَأَ مِنْ بَغْدَادَ وَعُلَمَائِهَا،",segs:[{ar:"وَعَقْلِي قَدِ امْتَلَأَ",uz:"aqlim ham to‘lganini"},{ar:"مِنْ بَغْدَادَ وَعُلَمَائِهَا،",uz:"Bag‘dod va uning olimlaridan,"}],full_uz:"Aqlim ham Bag‘dod va uning olimlaridan olgan bilimlarga to‘lganini,",note:"امْتَلَأَ مِنْ — ...bilan to‘lmoq."},
{num:502,time:"00:37:59,220 --> 00:38:03,760",arabic:"وَلَمْ يَبْقَ شَيْخٌ مِنْ شُيُوخِ الْحَدِيثِ الشَّرِيفِ إِلَّا وَقَصَدْتُهُ.",segs:[{ar:"وَلَمْ يَبْقَ شَيْخٌ",uz:"Biror shayx qolmadi"},{ar:"مِنْ شُيُوخِ الْحَدِيثِ الشَّرِيفِ",uz:"hadisi sharif shayxlaridan"},{ar:"إِلَّا وَقَصَدْتُهُ.",uz:"men uning huzuriga bormagan."}],full_uz:"Hadisi sharif shayxlaridan huzuriga bormagan birortasi qolmadi.",note:"لَمْ يَبْقَ — qolmadi; يَبْقَى fe’lining oxirgi ا harfi jazmda tushadi."},
{num:503,time:"00:38:03,760 --> 00:38:06,980",arabic:"تَتُوقُ نَفْسِي إِلَى أَبْعَدَ مِنْ ذَلِكَ.",segs:[{ar:"تَتُوقُ نَفْسِي",uz:"Ko‘nglim intilyapti"},{ar:"إِلَى أَبْعَدَ مِنْ ذَلِكَ.",uz:"bundan ham uzoqroqqa."}],full_uz:"Ko‘nglim bundan ham uzoqroqqa intilyapti.",note:"تَاقَ يَتُوقُ إِلَى — ...ga kuchli intilmoq, qo‘msamoq."},
{num:504,time:"00:38:07,760 --> 00:38:13,660",arabic:"طَالَمَا أَنَّكَ اكْتَفَيْتَ مِنْ عُلَمَاءِ بَغْدَادَ يَا وَلَدِي كَمَا تَقُولُ،",segs:[{ar:"طَالَمَا أَنَّكَ اكْتَفَيْتَ",uz:"Modomiki yetarlicha olgan ekansan"},{ar:"مِنْ عُلَمَاءِ بَغْدَادَ",uz:"Bag‘dod olimlaridan"},{ar:"يَا وَلَدِي",uz:"bolam"},{ar:"كَمَا تَقُولُ،",uz:"o‘zing aytganingdek,"}],full_uz:"Bolam, modomiki o‘zing aytganingdek Bag‘dod olimlaridan yetarlicha bilim olgan ekansan,",note:"اكْتَفَى — kifoyalanmoq, yetarli deb bilmoq."},
{num:505,time:"00:38:13,660 --> 00:38:16,780",arabic:"وَأَنَا مَعَكَ عَلَى هَذَا الرَّأْيِ،",segs:null,full_uz:"Men ham bu fikringga qo‘shilaman,",note:"أَنَا مَعَكَ — men sen bilanman; fikrga qo‘shilishni ham bildiradi."},
{num:506,time:"00:38:16,780 --> 00:38:19,020",arabic:"فَلِمَ لَا تَجُوبُ الْبُلْدَانَ وَالْأَمْصَارَ؟",segs:[{ar:"فَلِمَ لَا تَجُوبُ",uz:"Unda nega kezib chiqmaysan"},{ar:"الْبُلْدَانَ وَالْأَمْصَارَ؟",uz:"yurtlar va shaharlarni?"}],full_uz:"Unda nega yurtlar va shaharlarni kezib chiqmaysan?",note:"جَابَ يَجُوبُ — kezib chiqmoq; أَمْصَارٌ — yirik shaharlar."},
{num:507,time:"00:38:19,020 --> 00:38:24,440",arabic:"تَقْصِدُ عُلَمَاءَهَا وَتَطْلُبُ عِلْمَهَا وَتَجْلُو أَخْبَارَهَا،",segs:[{ar:"تَقْصِدُ عُلَمَاءَهَا",uz:"ularning olimlari huzuriga borasan"},{ar:"وَتَطْلُبُ عِلْمَهَا",uz:"ilmini talab qilasan"},{ar:"وَتَجْلُو أَخْبَارَهَا،",uz:"va xabarlarini oydinlashtirasan,"}],full_uz:"Ularning olimlari huzuriga borib, ilm talab qilasan va u yerdagi xabarlardan xabardor bo‘lasan,",note:"جَلَا يَجْلُو — ochmoq, oydinlashtirmoq; bu yerda xabarlarning mohiyatini bilib olish."},
{num:508,time:"00:38:24,440 --> 00:38:28,540",arabic:"وَسَتَصِلُ بِذَلِكَ إِلَى مُبْتَغَاكَ بِإِذْنِ اللَّهِ يَا وَلَدِي.",segs:[{ar:"وَسَتَصِلُ بِذَلِكَ إِلَى مُبْتَغَاكَ",uz:"Shu bilan maqsadingga yetasan"},{ar:"بِإِذْنِ اللَّهِ",uz:"Allohning izni bilan"},{ar:"يَا وَلَدِي.",uz:"bolam."}],full_uz:"Shu bilan Allohning izni ila maqsadingga yetasan, bolam.",note:"مُبْتَغَاكَ — sen ko‘zlagan maqsad; ابْتَغَى — istamoq, izlamoq."},
{num:509,time:"00:38:28,540 --> 00:38:32,080",arabic:"كَيْفَ السَّبِيلُ إِلَى ذَلِكَ؟",segs:null,full_uz:"Buning ilojini qanday topsam bo‘ladi?",note:"السَّبِيلُ إِلَى — ...ga eltadigan yo‘l, imkon."},
{num:510,time:"00:38:32,080 --> 00:38:33,400",arabic:"وَنَفَقَةُ السَّفَرِ كَثِيرَةٌ،",segs:null,full_uz:"Safar xarajati ko‘p bo‘lsa,",note:"نَفَقَةُ السَّفَرِ — safarga ketadigan xarajat."},
{num:511,time:"00:38:33,400 --> 00:38:35,980",arabic:"وَنَحْنُ بِالْكَادِ نُؤَمِّنُ قُوتَ يَوْمِنَا.",segs:[{ar:"وَنَحْنُ بِالْكَادِ نُؤَمِّنُ",uz:"Biz esa zo‘rg‘a ta’minlaymiz"},{ar:"قُوتَ يَوْمِنَا.",uz:"bir kunlik yeguligimizni."}],full_uz:"Biz esa bir kunlik yeguligimizni zo‘rg‘a topamiz.",note:"بِالْكَادِ — zo‘rg‘a. قُوتٌ — tirikchilik uchun zarur yegulik."},
{num:512,time:"00:38:35,980 --> 00:38:42,240",arabic:"إِذَا كَانَ مَا يَحُولُ بَيْنَكَ وَبَيْنَ السَّفَرِ هُوَ رِقَّةُ حَالِنَا وَقِلَّةُ نَفَقَتِنَا،",segs:[{ar:"إِذَا كَانَ مَا يَحُولُ",uz:"Agar to‘sqinlik qilayotgan narsa"},{ar:"بَيْنَكَ وَبَيْنَ السَّفَرِ",uz:"sen bilan safar o‘rtasida"},{ar:"هُوَ رِقَّةُ حَالِنَا",uz:"kambag‘al holimiz bo‘lsa"},{ar:"وَقِلَّةُ نَفَقَتِنَا،",uz:"va mablag‘imiz ozligi,"}],full_uz:"Agar safarga chiqishingga kambag‘al holimiz va mablag‘imiz ozligi to‘sqinlik qilayotgan bo‘lsa,",note:"حَالَ بَيْنَهُ وَبَيْنَ — u bilan biror narsa orasiga to‘siq bo‘lmoq. رِقَّةُ الْحَالِ — moddiy tanglik."},
{num:513,time:"00:38:42,240 --> 00:38:45,260",arabic:"فَالرَّازِقُ لَا يَنْسَى عِبَادَهُ يَا وَلَدِي.",segs:[{ar:"فَالرَّازِقُ لَا يَنْسَى عِبَادَهُ",uz:"Rizq beruvchi O‘z bandalarini unutmaydi"},{ar:"يَا وَلَدِي.",uz:"bolam."}],full_uz:"Rizq beruvchi O‘z bandalarini unutmaydi, bolam.",note:"الرَّازِقُ — rizq beruvchi; رَزَقَ fe’lidan."},
{num:514,time:"00:38:45,260 --> 00:38:50,760",arabic:"وَتَذَكَّرْ أَنَّ مَنْ سَلَكَ طَرِيقًا يَبْتَغِي فِيهِ عِلْمًا،",segs:[{ar:"وَتَذَكَّرْ",uz:"Yodingda tut"},{ar:"أَنَّ مَنْ سَلَكَ طَرِيقًا",uz:"kim bir yo‘lga kirsa"},{ar:"يَبْتَغِي فِيهِ عِلْمًا،",uz:"unda ilm izlab,"}],full_uz:"Yodingda tut: kim ilm izlab bir yo‘lga kirsa,",note:"سَلَكَ طَرِيقًا — yo‘lga kirmoq, yo‘ldan yurmoq. يَبْتَغِي — izlaydi, ko‘zlaydi."},
{num:515,time:"00:38:50,760 --> 00:38:54,099",arabic:"سَهَّلَ اللَّهُ لَهُ طَرِيقًا إِلَى الْجَنَّةِ.",segs:[{ar:"سَهَّلَ اللَّهُ لَهُ طَرِيقًا",uz:"Alloh unga yo‘lni oson qiladi"},{ar:"إِلَى الْجَنَّةِ.",uz:"jannatga."}],full_uz:"Alloh unga jannatga boradigan yo‘lni oson qiladi.",note:"سَهَّلَ — osonlashtirmoq; سَهُلَ — oson bo‘lmoq."},
{num:516,time:"00:38:54,099 --> 00:38:58,579",arabic:"فَالْأَمْرُ كُلُّهُ بِيَدِ اللَّهِ، فَتَوَكَّلْ عَلَيْهِ يَا وَلَدِي.",segs:[{ar:"فَالْأَمْرُ كُلُّهُ بِيَدِ اللَّهِ،",uz:"Barcha ish Allohning qo‘lida,"},{ar:"فَتَوَكَّلْ عَلَيْهِ",uz:"Unga tavakkal qil"},{ar:"يَا وَلَدِي.",uz:"bolam."}],full_uz:"Barcha ish Allohning qo‘lida. Unga tavakkal qil, bolam.",note:"تَوَكَّلَ عَلَى — ...ga suyanmoq, tavakkal qilmoq."},
{num:517,time:"00:38:58,579 --> 00:39:08,460",arabic:"فَهَلْ عَزَمْتَ أَمْرَكَ وَعَرَفْتَ قَصْدَكَ يَا وَلَدِي؟",segs:[{ar:"فَهَلْ عَزَمْتَ أَمْرَكَ",uz:"Xo‘sh, qat’iy qarorga keldingmi"},{ar:"وَعَرَفْتَ قَصْدَكَ",uz:"va qayerga borishingni bildingmi"},{ar:"يَا وَلَدِي؟",uz:"bolam?"}],full_uz:"Qat’iy qarorga kelib, qayerga borishingni belgiladingmi, bolam?",note:"عَزَمَ أَمْرَهُ — ishini qat’iy hal qilmoq. قَصْدٌ — niyat, yo‘nalish yoki boriladigan manzil."},
{num:518,time:"00:39:08,460 --> 00:39:13,739",arabic:"أَجَلْ يَا أُمَّاهُ، وَمَعَ ذَلِكَ كَيْفَ سَأَتْرُكُكِ وَحْدَكِ؟",segs:[{ar:"أَجَلْ يَا أُمَّاهُ،",uz:"Ha, onajon,"},{ar:"وَمَعَ ذَلِكَ",uz:"shunga qaramay"},{ar:"كَيْفَ سَأَتْرُكُكِ وَحْدَكِ؟",uz:"sizni qanday yolg‘iz qoldiraman?"}],full_uz:"Ha, onajon. Lekin sizni qanday yolg‘iz qoldiraman?",note:"وَحْدَكِ — sen yolg‘iz; ayol kishiga murojaat."},
{num:519,time:"00:39:13,739 --> 00:39:18,539",arabic:"هَلْ عَرَفْتَ أُمَّكَ ضَعِيفَةً لَا تَقْوَى عَلَى مُوَاجَهَةِ الْحَيَاةِ بِدُونِكَ؟",segs:[{ar:"هَلْ عَرَفْتَ أُمَّكَ ضَعِيفَةً",uz:"Onangni zaif deb bilganmisan"},{ar:"لَا تَقْوَى عَلَى مُوَاجَهَةِ الْحَيَاةِ",uz:"hayotga yuzlanishga kuchi yetmaydigan"},{ar:"بِدُونِكَ؟",uz:"sensiz?"}],full_uz:"Onangni sensiz hayotga yuzlanishga kuchi yetmaydigan zaif ayol deb bilganmisan?",note:"قَوِيَ عَلَى — bir ishga kuchi yetmoq. مُوَاجَهَةُ الْحَيَاةِ — hayot qiyinchiliklariga yuzlanish."},
{num:520,time:"00:39:18,539 --> 00:39:21,440",arabic:"لَا تَخْشَ عَلَيَّ شَيْئًا يَا وَلَدِي.",segs:[{ar:"لَا تَخْشَ عَلَيَّ شَيْئًا",uz:"Men uchun hech xavotir olma"},{ar:"يَا وَلَدِي.",uz:"bolam."}],full_uz:"Men uchun hech xavotir olma, bolam.",note:"لَا تَخْشَ — qo‘rqma; jazmda تَخْشَى fe’lining oxirgi ا harfi tushadi."},
{num:521,time:"00:39:21,440 --> 00:39:26,420",arabic:"فَاللَّهُ خَيْرٌ حَافِظًا، وَسَأَتَدَبَّرُ أَمْرِي.",segs:[{ar:"فَاللَّهُ خَيْرٌ حَافِظًا،",uz:"Alloh eng yaxshi asrovchidir,"},{ar:"وَسَأَتَدَبَّرُ أَمْرِي.",uz:"men esa o‘z ishimni uddalayman."}],full_uz:"Alloh eng yaxshi asrovchidir. Men o‘z ishimni uddalayman.",note:"تَدَبَّرَ أَمْرَهُ — o‘z ishining yo‘lini topmoq, uni boshqarmoq. حَافِظًا — tamyiz."},
{num:522,time:"00:39:26,420 --> 00:39:28,300",arabic:"الْمُهِمُّ أَنْتَ،",segs:null,full_uz:"Muhimi — sen,",note:"الْمُهِمُّ — muhim bo‘lgan narsa."},
{num:523,time:"00:39:28,300 --> 00:39:30,320",arabic:"وَمَا تَرْحَلُ إِلَيْهِ.",segs:null,full_uz:"Va safardan ko‘zlagan maqsading.",note:"رَحَلَ إِلَى — ...tomon safar qilmoq; bu yerda safarning maqsadi nazarda tutilgan."},
{num:524,time:"00:39:30,320 --> 00:39:44,360",arabic:"لَوْ أَعْرِفُ فَقَطْ مَاذَا قَالَتْ لَهُ هَذِهِ الْمَجْنُونَةُ!",segs:[{ar:"لَوْ أَعْرِفُ فَقَطْ",uz:"Qaniydi bilsam"},{ar:"مَاذَا قَالَتْ لَهُ",uz:"unga nima deganini"},{ar:"هَذِهِ الْمَجْنُونَةُ!",uz:"bu telba!"}],full_uz:"Qaniydi bu telba unga nima deganini bilsam!",note:"لَوْ bu yerda shartdan ko‘ra istakni ifodalaydi: qaniydi."},
{num:525,time:"00:39:44,360 --> 00:39:46,539",arabic:"لَقَدْ تَأَخَّرَ الرَّجُلُ كَثِيرًا.",segs:null,full_uz:"U kishi juda kechikdi.",note:null},
{num:526,time:"00:39:46,539 --> 00:39:49,340",arabic:"وَأَشَدُّ مَا أَخْشَاهُ أَلَّا يَعُودَ أَبَدًا.",segs:[{ar:"وَأَشَدُّ مَا أَخْشَاهُ",uz:"Eng qo‘rqayotganim"},{ar:"أَلَّا يَعُودَ أَبَدًا.",uz:"uning umuman qaytmasligi."}],full_uz:"Eng qo‘rqayotganim — uning umuman qaytmasligi.",note:"أَلَّا — أَنْ va لَا birikmasi; أَلَّا يَعُودَ — qaytmasligi."},
{num:527,time:"00:39:49,340 --> 00:39:50,340",arabic:"لَا أَظُنُّ ذَلِكَ.",segs:null,full_uz:"Men bunday deb o‘ylamayman.",note:null},
{num:528,time:"00:39:50,340 --> 00:39:52,019",arabic:"فَقَدْ قَالَ إِنَّهُ سَيَعُودُ.",segs:[{ar:"فَقَدْ قَالَ",uz:"Axir aytdi"},{ar:"إِنَّهُ سَيَعُودُ.",uz:"qaytishini."}],full_uz:"Axir u qaytishini aytdi.",note:null},
{num:529,time:"00:39:52,019 --> 00:39:53,840",arabic:"لَيْسَ هُنَاكَ مُسَوِّغٌ لِكَذِبِهِ.",segs:null,full_uz:"Uning yolg‘on aytishiga sabab yo‘q.",note:"مُسَوِّغٌ — bir ishga asos bo‘ladigan yoki uni oqlaydigan sabab."},
{num:530,time:"00:39:53,840 --> 00:39:56,400",arabic:"لِمَاذَا تَأَخَّرَ إِذَنْ كُلَّ هَذَا الْوَقْتِ؟",segs:[{ar:"لِمَاذَا تَأَخَّرَ إِذَنْ",uz:"Unda nega kechikdi"},{ar:"كُلَّ هَذَا الْوَقْتِ؟",uz:"shuncha vaqt?"}],full_uz:"Unda nega shuncha vaqt kechikdi?",note:null},
{num:531,time:"00:39:56,400 --> 00:39:59,460",arabic:"تَعْرِفِينَ مَشَاغِلَهُ، قَدْ يَكُونُ مَرَضُ أُخْتِهِ مَا أَخَّرَهُ،",segs:[{ar:"تَعْرِفِينَ مَشَاغِلَهُ،",uz:"Uning tashvishlarini bilasan,"},{ar:"قَدْ يَكُونُ مَرَضُ أُخْتِهِ",uz:"balki opa-singlisining kasalligi"},{ar:"مَا أَخَّرَهُ،",uz:"uni kechiktirgandir,"}],full_uz:"Uning tashvishlarini bilasan. Balki opa-singlisining kasalligi uni kechiktirgandir,",note:"مَشَاغِلُ — band qiladigan ishlar, tashvishlar. أُخْتٌ opa yoki singilni bildiradi."},
{num:532,time:"00:39:59,460 --> 00:40:01,880",arabic:"أَوْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ أَرْسَلَهُ خَارِجَ بَغْدَادَ.",segs:[{ar:"أَوْ أَنَّ أَمِيرَ الْمُؤْمِنِينَ أَرْسَلَهُ",uz:"yoki mo‘minlar amiri uni yuborgandir"},{ar:"خَارِجَ بَغْدَادَ.",uz:"Bag‘dod tashqarisiga."}],full_uz:"Yoki mo‘minlar amiri uni Bag‘dod tashqarisiga yuborgandir.",note:"خَارِجَ — tashqarida yoki tashqariga."},
{num:533,time:"00:40:01,880 --> 00:40:05,139",arabic:"لَيْسَ لَنَا إِلَّا الصَّبْرُ وَلَيْسَ أَمَامَنَا إِلَّاهُ.",segs:[{ar:"لَيْسَ لَنَا إِلَّا الصَّبْرُ",uz:"Bizga sabrdan boshqa chora yo‘q"},{ar:"وَلَيْسَ أَمَامَنَا إِلَّاهُ.",uz:"oldimizda bundan boshqa yo‘l yo‘q."}],full_uz:"Bizga sabrdan boshqa chora yo‘q, oldimizda boshqa yo‘l yo‘q.",note:"إِلَّاهُ — undan boshqa; ـهُ olmoshi الصَّبْرُ so‘ziga ishora qiladi."},
{num:534,time:"00:40:05,139 --> 00:40:06,800",arabic:"إِلَى مَتَى سَأَصْبِرُ؟",segs:null,full_uz:"Qachongacha sabr qilaman?",note:"إِلَى مَتَى؟ — qachongacha?"},
{num:535,time:"00:40:06,800 --> 00:40:09,900",arabic:"أُقْسِمُ إِنْ لَمْ يَعُدْ لِيَشْتَرِيَهَا هَذَا الرَّجُلُ،",segs:[{ar:"أُقْسِمُ",uz:"Qasam ichaman"},{ar:"إِنْ لَمْ يَعُدْ هَذَا الرَّجُلُ",uz:"agar bu kishi qaytmasa"},{ar:"لِيَشْتَرِيَهَا،",uz:"uni sotib olish uchun,"}],full_uz:"Qasam ichaman, agar bu kishi uni sotib olish uchun qaytmasa,",note:"لَمْ يَعُدْ — qaytmadi; يَعُودُ fe’lining o‘rtasidagi و jazmda tushadi."},
{num:536,time:"00:40:09,900 --> 00:40:13,800",arabic:"لَأَقْتُلَنَّهَا وَلَأُرِيَنَّهَا مِنَ الْعَذَابِ أَلْوَانًا.",segs:[{ar:"لَأَقْتُلَنَّهَا",uz:"uni albatta o‘ldiraman"},{ar:"وَلَأُرِيَنَّهَا",uz:"va unga albatta ko‘rsataman"},{ar:"مِنَ الْعَذَابِ أَلْوَانًا.",uz:"azobning turli ko‘rinishlarini."}],full_uz:"Uni albatta o‘ldiraman va unga turli azoblarni ko‘rsataman.",note:"لَـ va ta’kid ن harakati qat’iy va’da yoki tahdidni kuchaytiradi. أَلْوَانٌ bu yerda turlar ma’nosida."},
{num:537,time:"00:40:13,800 --> 00:40:17,960",arabic:"مَا يَعِيبُكِ يَا زَوْجِي أَنَّ غَضَبَكِ يَسْبِقُ عَقْلَكِ.",segs:[{ar:"مَا يَعِيبُكِ يَا زَوْجِي",uz:"Sening kamchiliging, rafiqam"},{ar:"أَنَّ غَضَبَكِ يَسْبِقُ عَقْلَكِ.",uz:"g‘azabing aqlingdan oldinga o‘tadi."}],full_uz:"Sening kamchiliging shuki, rafiqam, g‘azabing aqlingdan oldinga o‘tadi.",note:"زَوْجٌ xotinga ham, erga ham nisbatan ishlatiladi. سَبَقَ — oldinga o‘tmoq."},
{num:538,time:"00:40:17,960 --> 00:40:22,680",arabic:"وَمَا يَعِيبُكَ يَا زَوْجِي أَنَّكَ لَا تَمْلِكُ عَقْلًا وَلَا غَضَبًا.",segs:[{ar:"وَمَا يَعِيبُكَ يَا زَوْجِي",uz:"Sening kamchiliging esa, erim"},{ar:"أَنَّكَ لَا تَمْلِكُ عَقْلًا",uz:"senda aql yo‘q"},{ar:"وَلَا غَضَبًا.",uz:"g‘azab ham yo‘q."}],full_uz:"Sening kamchiliging esa, erim, senda na aql bor, na g‘azab.",note:"لَا ... وَلَا ... — na ... na ..."},
{num:539,time:"00:40:22,679 --> 00:40:27,059",arabic:"ثُمَّ مَاذَا تَقْصِدُ بِي؟",segs:null,full_uz:"O‘zi men haqimda nima demoqchisan?",note:"مَاذَا تَقْصِدُ بِـ؟ — ...bilan nimani nazarda tutyapsan?"},
{num:540,time:"00:40:27,059 --> 00:40:28,460",arabic:"هَلْ أَنَا غَبِيَّةٌ؟",segs:null,full_uz:"Men ahmoqmanmi?",note:"غَبِيَّةٌ — aqli past ayol; erkak uchun غَبِيٌّ."},
{num:541,time:"00:40:28,460 --> 00:40:30,179",arabic:"مَعَاذَ اللَّهِ! قَصَدْتُ...",segs:[{ar:"مَعَاذَ اللَّهِ!",uz:"Alloh saqlasin!"},{ar:"قَصَدْتُ...",uz:"Demoqchi edim..."}],full_uz:"Alloh saqlasin! Demoqchi edim...",note:"مَعَاذَ اللَّهِ — bunday gap yoki ishni keskin rad etishda ishlatiladi."},
{num:542,time:"00:40:30,179 --> 00:40:33,619",arabic:"كُنْتُ أُمَازِحُكِ يَا جَمِيلَةُ.",segs:[{ar:"كُنْتُ أُمَازِحُكِ",uz:"Senga hazillashayotgan edim"},{ar:"يَا جَمِيلَةُ.",uz:"go‘zalim."}],full_uz:"Senga hazillashayotgan edim, go‘zalim.",note:"مَازَحَ — birov bilan hazillashmoq."},
{num:543,time:"00:40:36,699 --> 00:40:40,399",arabic:"لَا أُرِيدُ شَيْئًا مِنْ هَذِهِ الدُّنْيَا،",segs:[{ar:"لَا أُرِيدُ شَيْئًا",uz:"Hech narsa istamayman"},{ar:"مِنْ هَذِهِ الدُّنْيَا،",uz:"bu dunyodan,"}],full_uz:"Bu dunyodan hech narsa istamayman,",note:"Keyingi إِلَّا bilan birga faqat bitta istakni ajratib ko‘rsatadi."},
{num:544,time:"00:40:40,399 --> 00:40:43,059",arabic:"إِلَّا أَنْ أَتْرُكَ بَيْتَ الشُّؤْمِ هَذَا.",segs:[{ar:"إِلَّا أَنْ أَتْرُكَ",uz:"faqat tark etishni"},{ar:"بَيْتَ الشُّؤْمِ هَذَا.",uz:"bu shum uyni."}],full_uz:"Faqat bu shum uyni tark etishni istayman.",note:"الشُّؤْمُ — shumlik, baxtsizlik."},
{num:545,time:"00:40:43,059 --> 00:40:48,359",arabic:"وَأَنْتَ أَيُّهَا الْمُنْقِذُ الْغَائِبُ،",segs:null,full_uz:"Sen esa, ey ko‘rinmayotgan qutqaruvchi,",note:"مُنْقِذٌ — qutqaruvchi; أَنْقَذَ fe’lidan."},
{num:546,time:"00:40:48,359 --> 00:40:52,399",arabic:"لِمَاذَا أَتَيْتَ إِلَى هَذِهِ الدَّارِ؟",segs:[{ar:"لِمَاذَا أَتَيْتَ",uz:"Nega kelding"},{ar:"إِلَى هَذِهِ الدَّارِ؟",uz:"bu uyga?"}],full_uz:"Nega bu uyga kelding?",note:null},
{num:547,time:"00:40:52,679 --> 00:40:58,000",arabic:"وَجَعَلْتَنِي أَتَعَلَّقُ بِأَهْدَابِ أَمَلٍ يَبْدُو أَنَّهُ لَنْ يَتَحَقَّقَ أَبَدًا؟",segs:[{ar:"وَجَعَلْتَنِي أَتَعَلَّقُ",uz:"Va meni yopishishga undading"},{ar:"بِأَهْدَابِ أَمَلٍ",uz:"bir umidning chetlariga"},{ar:"يَبْدُو أَنَّهُ",uz:"aftidan, u"},{ar:"لَنْ يَتَحَقَّقَ أَبَدًا؟",uz:"hech qachon amalga oshmaydigan?"}],full_uz:"Nega meni hech qachon amalga oshmaydiganga o‘xshagan umidga bog‘lab qo‘yding?",note:"تَعَلَّقَ بِأَهْدَابِ أَمَلٍ — umidning eng zaif uchiga ham yopishmoq. تَحَقَّقَ — amalga oshmoq."},
{num:548,time:"00:40:58,000 --> 00:41:04,119",arabic:"يَا رَبِّ، فَرِّجْ عَنِّي مَا أَنَا فِيهِ.",segs:[{ar:"يَا رَبِّ،",uz:"Ey Rabbim,"},{ar:"فَرِّجْ عَنِّي",uz:"meni xalos qil"},{ar:"مَا أَنَا فِيهِ.",uz:"tushib qolgan bu holatimdan."}],full_uz:"Ey Rabbim, meni tushib qolgan bu kulfatimdan xalos qil.",note:"فَرَّجَ عَنْهُ — uning g‘amini aritdi, qiyinchiligini yengillashtirdi."}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
